//! The resource system, cut one: the 1990 table, the derived HAVE ledger, the
//! stockpile, and the one gate that reads them — at the arsenal's pick.
//!
//! # The table
//!
//! `spheres-sim/data/resources_1990.json` is generated by
//! `tools/resources/make_resources_1990.py` from the web's district artifacts
//! and, for six of the twelve lines, from the transcription file beside the
//! generator (USGS Minerals Yearbook 1990 and the OECD/IAEA Red Book), and
//! committed, the way `districts.json` and the nation files are. It is
//! embedded with `include_str!` for the same reason they are: the library does
//! no file access, the binary is self-contained, and a determinism test cannot
//! fail because a data file moved. It is a STATIC table — never in
//! `WorldState`, never hashed, never saved — so nothing here can move a golden.
//!
//! Two passes, the `data/mod.rs` convention: pass one parses with
//! `deny_unknown_fields` and checks each table against itself (shares sum to
//! one, every share above the pruning floor, quality zero exactly where the
//! presence bit is zero, every transcribed table reconciled to its printed
//! total); pass two resolves every key through `NationId::from_code` and the
//! 1990 roster, so a key that names nobody, or a seat that is not on the board
//! in January 1990, is a refusal addressed to whoever wrote the file rather
//! than a silent zero in somebody's ledger.
//!
//! What the numbers ARE, so no reader multiplies the wrong two:
//! - `national_1990[c][n]` is the transcribed 1990 national figure, verbatim,
//!   in `units[c]`. The USSR's iron is 236,000,000 t (DS-896) and a test says so.
//! - `located[c][n]` is a LOCATION WEIGHT per district — the share of the 1990
//!   owner's figure that sits in that district under one written rule
//!   (`meta.rules.share`). A share is never a tonnage; multiplied by the figure
//!   it says where the output is, which is what changes hands with the ground.
//! - `presence` and `quality` are presence bits and a presence RANK, used to
//!   choose a war aim, never to print a number.
//! - `price_1990[c]` is a 1990 unit value in dollars per `units[c]`, with the
//!   printed figure and its source beside it. Oil has no row; the sim prices
//!   it at `w.oil_price`.
//!
//! # The ledger (spec section 1)
//!
//! HAVE is a FLOW, derived and never stored: a nation's annual own production
//! is the located shares of every district it currently holds times the 1990
//! owner's figure, plus its own figure where the figure was never located.
//! Rebuilt only when the ownership map or the living roster changes (the
//! `districts_epoch` and the alive stamp), refreshed monthly for oil alone,
//! because the oil ledger is `n.oil_mbd` and districts only say where it sits.
//!
//! COVER is the pile: months of NEED in hand, 0..=12, one row per nation only
//! while some line is below twelve. It is written in exactly one place, inside
//! a gate evaluation, and folds back to nothing when every line is full — so
//! an untouched world serializes to the same bytes it did before this module
//! existed, which is the inert invariant the goldens hold.
//!
//! NEED is what this month's attempted gated action wants: one coefficient
//! set per equipment class per billion ordered, for kits that name a
//! technology. The legacy tier is exempt — the transcribed 1990 strength is
//! made of it and the 1990 economy demonstrably fed it — and that exemption is
//! what makes January 1990 inert under any floor.
//!
//! SUPPLY is pure over `&WorldState`: own flow, contract inflow (S2), and an
//! open market that fills the gap whenever any living holder is neither
//! sanctioning nor sanctioned by the buyer, not fighting it, and not below the
//! relation floor. In an open world shortage is an embargo phenomenon, never
//! scarcity; the measured minimum of open holders over 21 seeds and 40 years
//! never fell to zero, which is why the gate costs nothing in every test.
//!
//! The ruling this encodes, verbatim: "It should only hurt if you are trying
//! to do something with the resource and don't have enough of it." Nothing
//! here is read by growth, oil, stability or munitions.

use serde::{Deserialize, Serialize};
use std::borrow::Cow;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

use crate::arsenal::{Class, DECK};
use crate::data::{render_errors, LoadError};
use crate::nations::{all_nations, nation_count};
use crate::world::{start_nations, NationId, WorldState};

pub const EMBEDDED_RESOURCES_1990: &str = include_str!("../data/resources_1990.json");
const FILE: &str = "data/resources_1990.json";

/// The twelve lines, alphabetical. Index `i` is bit `i` of a `presence` mask
/// and column `i` of a `quality` row, and the file's `commodities` list must
/// read exactly this. `Commodity` mirrors it variant for variant.
pub const COMMODITIES: [&str; 12] = [
    "bauxite",
    "coal",
    "cobalt",
    "copper",
    "gas",
    "gold",
    "iron",
    "oil",
    "phosphate",
    "platinum_group",
    "rare_earths",
    "uranium",
];

/// The lines with a transcribed 1990 national figure. Since package D2 that
/// is all twelve: six from the web artifact, six from the transcription file
/// (`meta.transcription`). A line is gated, contracted and printed only while
/// it is here; the file's `tracked` must read exactly this.
pub const TRACKED: [&str; 12] = COMMODITIES;

/// `national` keys the generator refuses to seat, and the loader asserts it
/// refused exactly these. Namibia is a roster seat that comes alive after
/// January 1990 and holds no 1990 district; its figures are reported in
/// `meta.counts.dropped_rows` and carried nowhere else. A start nation may
/// never appear here: that would be a transcribed figure thrown away.
pub const DROPPED_KEYS: [&str; 1] = ["Namibia"];

/// The floor a located share must clear. The generator prunes below it and
/// renormalises; "located" means at or above it (spec section 1.2: a 1e-6
/// coalfield sliver must not count as located, as a district, or as a war aim).
pub const LOCATED_MIN_SHARE: f64 = 1e-3;

/// How far a located list's sum may sit from one.
pub const SHARE_SUM_TOLERANCE: f64 = 1e-9;

// ---------------------------------------------------------------------------
// The commodity
// ---------------------------------------------------------------------------

/// One of the twelve lines. Serialized by its file key (`platinum_group`), and
/// its discriminant is its index in `COMMODITIES`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Commodity {
    Bauxite,
    Coal,
    Cobalt,
    Copper,
    Gas,
    Gold,
    Iron,
    Oil,
    Phosphate,
    PlatinumGroup,
    RareEarths,
    Uranium,
}

pub const ALL: [Commodity; 12] = [
    Commodity::Bauxite,
    Commodity::Coal,
    Commodity::Cobalt,
    Commodity::Copper,
    Commodity::Gas,
    Commodity::Gold,
    Commodity::Iron,
    Commodity::Oil,
    Commodity::Phosphate,
    Commodity::PlatinumGroup,
    Commodity::RareEarths,
    Commodity::Uranium,
];

impl Commodity {
    /// 0..11, the presence bit and quality column.
    pub fn idx(self) -> usize {
        self as usize
    }
    pub fn bit(self) -> u16 {
        1 << self.idx()
    }
    pub fn from_idx(i: usize) -> Option<Commodity> {
        ALL.get(i).copied()
    }
    /// The file key: `platinum_group`, `rare_earths`.
    pub fn key(self) -> &'static str {
        COMMODITIES[self.idx()]
    }
    /// The card word: "platinum group", "rare earths".
    pub fn name(self) -> &'static str {
        match self {
            Commodity::Bauxite => "bauxite",
            Commodity::Coal => "coal",
            Commodity::Cobalt => "cobalt",
            Commodity::Copper => "copper",
            Commodity::Gas => "gas",
            Commodity::Gold => "gold",
            Commodity::Iron => "iron",
            Commodity::Oil => "oil",
            Commodity::Phosphate => "phosphate",
            Commodity::PlatinumGroup => "platinum group",
            Commodity::RareEarths => "rare earths",
            Commodity::Uranium => "uranium",
        }
    }
    /// The table's unit — the unit `flow` and every need are counted in. The
    /// loader holds the file's `units` to this.
    pub fn unit(self) -> &'static str {
        match self {
            Commodity::Bauxite => "t",
            Commodity::Coal => "kt",
            Commodity::Cobalt => "t",
            Commodity::Copper => "t",
            Commodity::Gas => "bcf",
            Commodity::Gold => "kg",
            Commodity::Iron => "t",
            Commodity::Oil => "kb/d",
            Commodity::Phosphate => "kt",
            Commodity::PlatinumGroup => "kg",
            Commodity::RareEarths => "t",
            Commodity::Uranium => "t",
        }
    }
    /// Whether the table carries a 1990 figure for this line. Read from the
    /// table so that a line whose figure were ever withdrawn falls back to the
    /// None arm — no consumption, no gate, no contract leg — by itself.
    pub fn tracked(self) -> bool {
        tables().tracked[self.idx()]
    }
    pub fn parse(s: &str) -> Option<Commodity> {
        COMMODITIES.iter().position(|k| *k == s).map(|i| ALL[i])
    }
}

// ---------------------------------------------------------------------------
// The schema
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct ResourceFile {
    pub meta: Meta,
    pub commodities: Vec<String>,
    pub tracked: Vec<String>,
    /// The sim's unit per tracked line.
    pub units: BTreeMap<String, String>,
    /// Per mined tracked line (never oil): the 1990 unit value.
    pub price_1990: BTreeMap<String, Price>,
    /// commodity -> 1990 start nation code -> the figure, verbatim.
    pub national_1990: BTreeMap<String, BTreeMap<String, Figure>>,
    /// commodity -> 1990 owner code -> [(district, share)], share desc then id.
    pub located: BTreeMap<String, BTreeMap<String, Vec<(String, f64)>>>,
    /// district -> 12-bit mask, bit i = `COMMODITIES[i]` present.
    pub presence: BTreeMap<String, u16>,
    /// district -> presence rank per commodity, 0 absent, 1..3 present.
    pub quality: BTreeMap<String, [u8; 12]>,
    /// district -> share of its 1990 owner's population.
    pub pop_share: BTreeMap<String, f64>,
    /// district -> GHS-POP 1990 count (a modelled surface, not a census line).
    pub pop_1990: BTreeMap<String, u64>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Meta {
    pub generator: String,
    pub upstream: Upstream,
    pub source_sha256: BTreeMap<String, String>,
    pub dropped_keys: Vec<String>,
    pub rules: BTreeMap<String, String>,
    pub counts: Counts,
    /// Mined tracked lines with no sourced 1990 price, and why.
    pub prices_omitted: BTreeMap<String, String>,
    /// The six lines transcribed for this table (package D2): the file they
    /// were read from, its sources, each table reconciled to its printed
    /// total, and every figure the roster could not seat.
    pub transcription: Transcription,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Upstream {
    pub generator: String,
    pub vintage: u32,
    pub sources: BTreeMap<String, UpstreamSource>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct UpstreamSource {
    pub title: String,
    pub url: String,
    pub role: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Counts {
    pub presence_districts: usize,
    pub located_rows: BTreeMap<String, usize>,
    pub located_nations: BTreeMap<String, usize>,
    pub national_rows: BTreeMap<String, usize>,
    pub pruned: BTreeMap<String, BTreeMap<String, usize>>,
    pub unlocated_producers: BTreeMap<String, Vec<String>>,
    pub zero_rows_omitted: BTreeMap<String, usize>,
    pub dropped_rows: BTreeMap<String, BTreeMap<String, f64>>,
    pub pop_districts: usize,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Transcription {
    pub file: String,
    pub lines: Vec<String>,
    pub sources: BTreeMap<String, TranscriptionSource>,
    pub tables: BTreeMap<String, TranscribedTable>,
    /// Figures the source prints for an entity with no roster seat, kept so
    /// nothing is silently lost, seated nowhere.
    pub unmapped_1990: BTreeMap<String, Vec<Unmapped>>,
    /// Producers the source names without a figure: no row, and the board
    /// says "no 1990 figure".
    pub no_figure_1990: BTreeMap<String, Vec<NoFigure>>,
    pub notes: BTreeMap<String, String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct TranscriptionSource {
    pub title: String,
    pub licence: String,
    pub url: String,
}

/// One transcribed table reconciled: seated + dropped + unmapped + zero rows
/// equal the total the source prints, or the generator refuses to write.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct TranscribedTable {
    pub table: String,
    pub unit_basis: String,
    pub printed_total_1990: f64,
    pub seated: f64,
    pub dropped: f64,
    pub unmapped: f64,
    pub zero: f64,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Unmapped {
    pub label: String,
    pub value: f64,
    pub unit: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct NoFigure {
    pub roster_key: String,
    pub label: String,
    pub reason: String,
}

/// One transcribed 1990 unit value. `usd_per_unit` is dollars per one
/// `units[c]`, derived from `as_printed` by `conversion`; `source` is the
/// citation verbatim, which the web prints on hover.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Price {
    pub usd_per_unit: f64,
    pub as_printed: String,
    pub conversion: String,
    pub source: String,
}

/// One transcribed 1990 national figure and where it came from: an artifact
/// source key (`meta.upstream.sources` describes it) for the artifact lines,
/// the citation verbatim for the transcribed lines. `flags` are the source's
/// own estimate and footnote flags; `note` is the transcriber's attribution
/// note (a territory folded to its sovereign, a merged row's components).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Figure {
    pub value: f64,
    pub source: String,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub flags: Vec<String>,
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub note: String,
}

/// One located row, flattened for the HAVE build: this district carries
/// `share` of `owner_1990`'s figure for commodity `c`.
#[derive(Clone, Debug)]
pub struct DistrictRow {
    pub district: String,
    pub c: usize,
    pub owner_1990: NationId,
    pub share: f64,
}

/// The parsed file plus the keys resolved to `NationId`, so a consumer never
/// touches a string twice, and the flattened rows `have_table` walks. Built
/// once, behind `tables()`.
#[derive(Clone, Debug)]
pub struct Tables {
    pub file: ResourceFile,
    /// commodity -> nation -> the 1990 figure in the sim's units.
    pub national: BTreeMap<String, BTreeMap<NationId, f64>>,
    /// commodity -> 1990 owner -> located (district, share), share desc.
    pub located: BTreeMap<String, BTreeMap<NationId, Vec<(String, f64)>>>,
    /// By commodity index: whether the file tracks the line.
    pub tracked: [bool; 12],
    /// By `NationId` index: the 1990 figure per commodity, the table's units.
    pub production: Vec<[f64; 12]>,
    /// By `NationId` index: a producer with a figure and no located district,
    /// which keeps its whole figure while it lives.
    pub unlocated: Vec<[bool; 12]>,
    /// Every located (district, commodity, 1990 owner, share) row.
    pub district_rows: Vec<DistrictRow>,
    /// Every (district, presence mask) row.
    pub presence_rows: Vec<(String, u16)>,
    /// By commodity index: the 1990 price in dollars per unit, if priced.
    pub price: [Option<f64>; 12],
}

/// Index of a commodity name in `COMMODITIES`, which is its presence bit and
/// quality column.
pub fn commodity_index(name: &str) -> Option<usize> {
    COMMODITIES.iter().position(|c| *c == name)
}

/// The table. Parsed and validated once; a broken file is a panic with every
/// problem listed, the way `districts::tables` treats `districts.json`.
pub fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let file = parse_and_validate(EMBEDDED_RESOURCES_1990)
            .unwrap_or_else(|e| panic!("{}", render_errors(&e)));
        let nn = nation_count();
        let mut national = BTreeMap::new();
        let mut production = vec![[0.0f64; 12]; nn];
        let mut unlocated = vec![[false; 12]; nn];
        for (c, rows) in &file.national_1990 {
            let ci = commodity_index(c).expect("validated above");
            let mut m = BTreeMap::new();
            for (code, fig) in rows {
                let id = NationId::from_code(code).expect("validated above");
                m.insert(id, fig.value);
                production[id.index()][ci] = fig.value;
                unlocated[id.index()][ci] =
                    !file.located.get(c).is_some_and(|l| l.contains_key(code));
            }
            national.insert(c.clone(), m);
        }
        let mut located = BTreeMap::new();
        let mut district_rows = vec![];
        for (c, rows) in &file.located {
            let ci = commodity_index(c).expect("validated above");
            let mut m = BTreeMap::new();
            for (code, list) in rows {
                let id = NationId::from_code(code).expect("validated above");
                for (d, share) in list {
                    district_rows.push(DistrictRow {
                        district: d.clone(),
                        c: ci,
                        owner_1990: id,
                        share: *share,
                    });
                }
                m.insert(id, list.clone());
            }
            located.insert(c.clone(), m);
        }
        district_rows.sort_by(|a, b| a.district.cmp(&b.district).then(a.c.cmp(&b.c)));
        let presence_rows = file.presence.iter().map(|(d, m)| (d.clone(), *m)).collect();
        let mut tracked = [false; 12];
        for t in &file.tracked {
            tracked[commodity_index(t).expect("validated above")] = true;
        }
        let mut price = [None; 12];
        for (c, p) in &file.price_1990 {
            price[commodity_index(c).expect("validated above")] = Some(p.usd_per_unit);
        }
        Tables {
            file,
            national,
            located,
            tracked,
            production,
            unlocated,
            district_rows,
            presence_rows,
            price,
        }
    })
}

/// Both passes over one source string. Errors are collected, not
/// short-circuited: a regenerated file with three problems should show three.
pub fn parse_and_validate(json: &str) -> Result<ResourceFile, Vec<LoadError>> {
    let file = serde_json::from_str::<ResourceFile>(json)
        .map_err(|e| vec![file_level(e.to_string())])?;
    let mut errors = check_file(&file);
    errors.extend(validate(&file));
    if errors.is_empty() {
        Ok(file)
    } else {
        Err(errors)
    }
}

fn file_level(message: impl Into<String>) -> LoadError {
    LoadError { file: FILE.to_string(), nation: None, message: message.into() }
}

fn nation_level(nation: &str, message: impl Into<String>) -> LoadError {
    LoadError { file: FILE.to_string(), nation: Some(nation.to_string()), message: message.into() }
}

// ---------------------------------------------------------------------------
// Pass one — the file against itself
// ---------------------------------------------------------------------------

/// Bounds that are facts about the table rather than opinions about history:
/// a share is a share, a list of shares sums to one, a rank is 0..3 and is 0
/// exactly where nothing is present, a mined line either has a sourced price
/// or says why it has none, and a transcribed table's rows add up to the
/// total the source prints.
fn check_file(f: &ResourceFile) -> Vec<LoadError> {
    let mut e = vec![];
    if f.commodities != COMMODITIES {
        e.push(file_level(format!(
            "commodities is {:?}; the twelve lines in this build are {:?}, in that order",
            f.commodities, COMMODITIES
        )));
    }
    if f.tracked != TRACKED {
        e.push(file_level(format!("tracked is {:?}, expected {:?}", f.tracked, TRACKED)));
    }
    let tracked: Vec<&str> = TRACKED.to_vec();
    let unit_keys: Vec<&str> = f.units.keys().map(String::as_str).collect();
    if unit_keys != tracked {
        e.push(file_level(format!("units is keyed {:?}, expected the tracked lines", unit_keys)));
    }
    for (c, u) in &f.units {
        if u.trim().is_empty() {
            e.push(file_level(format!("units.{c} is empty")));
        }
        if let Some(k) = Commodity::parse(c) {
            if k.unit() != u {
                e.push(file_level(format!(
                    "units.{c} is {u:?} but this build counts {c} in {:?} — the unit is the enum's, the file must agree",
                    k.unit()
                )));
            }
        }
    }
    for (c, p) in &f.price_1990 {
        if !TRACKED.contains(&c.as_str()) || c == "oil" {
            e.push(file_level(format!(
                "price_1990.{c}: only mined tracked lines carry a price; oil is priced at w.oil_price"
            )));
        }
        if !(p.usd_per_unit.is_finite() && p.usd_per_unit > 0.0) {
            e.push(file_level(format!(
                "price_1990.{c}.usd_per_unit is {}, expected a positive dollar figure",
                p.usd_per_unit
            )));
        }
        for (field, s) in [("source", &p.source), ("as_printed", &p.as_printed), ("conversion", &p.conversion)] {
            if s.trim().is_empty() {
                e.push(file_level(format!(
                    "price_1990.{c}.{field} is empty — iron rule 4: a price is transcribed, so say where from"
                )));
            }
        }
        if f.meta.prices_omitted.contains_key(c) {
            e.push(file_level(format!("price_1990.{c} is both priced and listed in prices_omitted")));
        }
    }
    for c in TRACKED.iter().filter(|c| **c != "oil") {
        if !f.price_1990.contains_key(*c) && !f.meta.prices_omitted.contains_key(*c) {
            e.push(file_level(format!(
                "{c} has no price_1990 row and no prices_omitted reason — an unsourced line is omitted AND says so"
            )));
        }
    }
    if f.national_1990.keys().map(String::as_str).collect::<Vec<_>>() != tracked {
        e.push(file_level("national_1990 must be keyed by exactly the tracked lines"));
    }
    if f.located.keys().map(String::as_str).collect::<Vec<_>>() != tracked {
        e.push(file_level("located must be keyed by exactly the tracked lines"));
    }
    for (c, rows) in &f.national_1990 {
        for (n, fig) in rows {
            if !(fig.value.is_finite() && fig.value > 0.0) {
                e.push(nation_level(n, format!(
                    "national_1990.{c} is {}, expected a positive figure (zero rows are omitted)",
                    fig.value
                )));
            }
            if fig.source.trim().is_empty() {
                e.push(nation_level(n, format!("national_1990.{c} has no source")));
            }
        }
    }
    for (c, rows) in &f.located {
        for (n, list) in rows {
            if list.is_empty() {
                e.push(nation_level(n, format!("located.{c} is an empty list; an unlocated producer is absent, not empty")));
                continue;
            }
            let sum: f64 = list.iter().map(|(_, s)| *s).sum();
            if !((sum - 1.0).abs() <= SHARE_SUM_TOLERANCE) {
                e.push(nation_level(n, format!("located.{c} sums to {sum}, expected 1 within {SHARE_SUM_TOLERANCE}")));
            }
            for (d, s) in list {
                if !(s.is_finite() && *s >= LOCATED_MIN_SHARE && *s <= 1.0) {
                    e.push(nation_level(n, format!(
                        "located.{c} share of {d} is {s}, expected {LOCATED_MIN_SHARE}..=1 (below the floor is pruned, not located)"
                    )));
                }
                if !f.presence.contains_key(d) {
                    e.push(nation_level(n, format!("located.{c} names {d}, which carries no presence bit")));
                }
            }
            for w in list.windows(2) {
                let ((d0, s0), (d1, s1)) = (&w[0], &w[1]);
                if s1 > s0 || (s1 == s0 && d1 <= d0) {
                    e.push(nation_level(n, format!("located.{c} is not sorted share desc then id at {d0} / {d1}")));
                    break;
                }
            }
        }
    }
    if f.presence.is_empty() {
        e.push(file_level("presence is empty"));
    }
    for (d, m) in &f.presence {
        if *m == 0 || *m >= 1 << 12 {
            e.push(file_level(format!("presence.{d} is {m}, expected a non-empty 12-bit mask")));
        }
    }
    if f.quality.keys().ne(f.presence.keys()) {
        e.push(file_level("quality must be keyed exactly like presence"));
    }
    for (d, q) in &f.quality {
        let mask = f.presence.get(d).copied().unwrap_or(0);
        for (i, r) in q.iter().enumerate() {
            let present = mask >> i & 1 == 1;
            if *r > 3 || (*r == 0) == present {
                e.push(file_level(format!(
                    "quality.{d}[{i}] ({}) is {r} but the presence bit is {}; a rank is 1..3 where present and 0 where not",
                    COMMODITIES[i], present as u8
                )));
            }
        }
    }
    for (d, s) in &f.pop_share {
        if !(s.is_finite() && (0.0..=1.0).contains(s)) {
            e.push(file_level(format!("pop_share.{d} is {s}, expected a share in 0..=1")));
        }
    }
    if f.pop_1990.keys().ne(f.pop_share.keys()) {
        e.push(file_level("pop_1990 must be keyed exactly like pop_share"));
    }
    if f.meta.dropped_keys != DROPPED_KEYS {
        e.push(file_level(format!(
            "meta.dropped_keys is {:?}; this build expects exactly {:?} to be unseated",
            f.meta.dropped_keys, DROPPED_KEYS
        )));
    }
    let c = &f.meta.counts;
    if c.presence_districts != f.presence.len() || c.pop_districts != f.pop_share.len() {
        e.push(file_level("meta.counts district totals do not describe the file"));
    }
    for t in TRACKED {
        let rows = f.located.get(t).map(|m| m.values().map(Vec::len).sum::<usize>()).unwrap_or(0);
        let nats = f.located.get(t).map(BTreeMap::len).unwrap_or(0);
        let natl = f.national_1990.get(t).map(BTreeMap::len).unwrap_or(0);
        if c.located_rows.get(t) != Some(&rows)
            || c.located_nations.get(t) != Some(&nats)
            || c.national_rows.get(t) != Some(&natl)
        {
            e.push(file_level(format!("meta.counts for {t} do not describe the file")));
        }
    }
    // The transcribed six: every table reconciles to the total the source
    // prints, and the seated sum is the sum of the rows this file carries.
    let tr = &f.meta.transcription;
    for (c, t) in &tr.tables {
        if !tr.lines.contains(c) {
            e.push(file_level(format!("meta.transcription.tables.{c} is not a transcribed line")));
        }
        let got = t.seated + t.dropped + t.unmapped + t.zero;
        if got != t.printed_total_1990 {
            e.push(file_level(format!(
                "meta.transcription.tables.{c}: seated + dropped + unmapped + zero = {got}, the table prints {}",
                t.printed_total_1990
            )));
        }
        let seated: f64 = f.national_1990.get(c).map(|m| m.values().map(|v| v.value).sum()).unwrap_or(0.0);
        if seated != t.seated {
            e.push(file_level(format!(
                "meta.transcription.tables.{c}: seated {} but the rows carried sum to {seated}",
                t.seated
            )));
        }
    }
    for c in &tr.lines {
        if !tr.tables.contains_key(c) {
            e.push(file_level(format!("meta.transcription.tables has no entry for {c}")));
        }
        if let Some(rows) = f.national_1990.get(c) {
            for (n, fig) in rows {
                if !fig.source.contains("1990") {
                    e.push(nation_level(n, format!("national_1990.{c}: a transcribed row must cite its 1990 table")));
                }
            }
        }
    }
    e
}

// ---------------------------------------------------------------------------
// Pass two — the file against the roster
// ---------------------------------------------------------------------------

/// Nothing here can be checked while looking at the file alone: every key
/// must name a nation this build has, that nation must be on the board in
/// January 1990, every located producer must have a figure, a dropped key
/// must never be a start nation, and a producer named without a figure must
/// be a start nation that indeed has no row.
fn validate(f: &ResourceFile) -> Vec<LoadError> {
    let mut e = vec![];
    let start = start_nations();
    for (c, rows) in &f.national_1990 {
        for code in rows.keys() {
            match NationId::from_code(code) {
                None => e.push(nation_level(code, format!(
                    "national_1990.{c} names a nation this build does not have — the join is the roster code, and dropped_keys are the only permitted misses"
                ))),
                Some(id) if !start.contains(&id) => e.push(nation_level(code, format!(
                    "national_1990.{c} names a seat that is not on the board in January 1990 — successor states inherit through the located shares, never a row of their own"
                ))),
                Some(_) => {}
            }
        }
    }
    for (c, rows) in &f.located {
        for code in rows.keys() {
            if !f.national_1990.get(c).is_some_and(|m| m.contains_key(code)) {
                e.push(nation_level(code, format!("located.{c} has shares but no national_1990.{c} figure to locate")));
            }
        }
    }
    for code in &f.meta.dropped_keys {
        if let Some(id) = NationId::from_code(code) {
            if start.contains(&id) {
                e.push(nation_level(code, "is listed in dropped_keys but is a 1990 start nation — a transcribed figure was thrown away"));
            }
        }
    }
    for (c, list) in &f.meta.transcription.no_figure_1990 {
        for nf in list {
            match NationId::from_code(&nf.roster_key) {
                None => e.push(nation_level(&nf.roster_key, format!(
                    "meta.transcription.no_figure_1990.{c} names a nation this build does not have"
                ))),
                Some(id) if !start.contains(&id) => e.push(nation_level(&nf.roster_key, format!(
                    "meta.transcription.no_figure_1990.{c} names a seat that is not on the board in January 1990"
                ))),
                Some(_) if f.national_1990.get(c).is_some_and(|m| m.contains_key(&nf.roster_key)) => {
                    e.push(nation_level(&nf.roster_key, format!(
                        "meta.transcription.no_figure_1990.{c} lists a nation that has a {c} row"
                    )))
                }
                Some(_) => {}
            }
        }
    }
    e
}

// ---------------------------------------------------------------------------
// The mechanic constants (Appendix A: named, classed, justified)
// ---------------------------------------------------------------------------

/// The pile, in months of need (M). Between the IEA's 90-day civil stock
/// obligation and the Stock Piling Act's three-year war stockpile. No physical
/// decay: cover erodes only when a line asks for what it cannot get.
pub const BUFFER_MONTHS: f64 = 12.0;

/// What a seller keeps of its own draw before it counts a surplus (M). The
/// same year the buyer holds, so neither side of a contract is asked to run
/// on less than the other.
pub const RESERVE_MONTHS: f64 = BUFFER_MONTHS;

/// Below this relation a holder will not sell (M). The zero of
/// `statecraft::propose_trade`'s curve, statecraft.rs 623; −30 and 0 were
/// both measured silent over 21 seeds × 40 years, so the floor sits between
/// two values that change nothing in an open world.
pub const RELATION_FLOOR: f64 = -20.0;

pub const MINE_BUILD_MONTHS: u32 = 12;
pub const MINE_PC_COST: f64 = 6.0;
pub const MINE_COST_YEARS: f64 = 2.0;
pub const MINE_COST_FLOOR_BN: f64 = 0.25;
pub const MINE_COST_CAP_BN: f64 = 25.0;

// NEED coefficients, kt per $bn ordered, per equipment class (M; order of
// magnitude, one platform per number). Each is a chain of two transcribed
// facts — a platform's mass and price, and the ore-and-coke burden of a tonne
// of steel — and none pretends to more than its first digit.
//
// Naval: a DDG-51 displaces ~8,300 t at ~$0.9bn FY90, so a naval billion is
// ~9 kt of steel. BF-BOF steel takes ~1.4 t of iron ore and ~0.78 t of coking
// coal per tonne of crude (worldsteel): 9 × 1.4 ≈ 12 kt ore, 9 × 0.78 ≈ 7 kt
// coal — rounded to 6.5 because a hull is not all crude steel.
/// Iron ore per $bn of naval kit, kt.
pub const NAVAL_ORE_KT_PER_BN: f64 = 12.0;
/// Coking coal per $bn of naval kit, kt.
pub const NAVAL_COAL_KT_PER_BN: f64 = 6.5;
// Armour: an M1A1 is ~62 t at ~$4.3m, so an armoured billion is ~14 kt of
// steel; × 1.4 ≈ 20 kt ore, × 0.78 ≈ 11 kt coal.
/// Iron ore per $bn of armour, kt.
pub const ARMOUR_ORE_KT_PER_BN: f64 = 20.0;
/// Coking coal per $bn of armour, kt.
pub const ARMOUR_COAL_KT_PER_BN: f64 = 11.0;
// Air: an F-16C is ~8.6 t empty, ~78% aluminium, at ~$20m; 4.5 t of bauxite
// per tonne of aluminium → ~50 airframes × 6.7 t Al × 4.5 ≈ 1.5 kt of bauxite
// per billion, rounded down.
/// Bauxite per $bn of aircraft, kt.
pub const AIR_BAUXITE_KT_PER_BN: f64 = 1.4;
// Missile and space: cabling and electronics. A Tomahawk is ~1.4 t at ~$1.4m
// and ~5% copper by mass → ~700 rounds × 70 kg ≈ 0.05 kt per billion; a
// satellite bus is denser in copper; 0.1 covers both.
/// Copper per $bn of missiles or spacecraft, kt.
pub const MISSILE_COPPER_KT_PER_BN: f64 = 0.1;
// Infantry: post-1990 infantry kit is electronics (Link 16, C4ISR, Raven);
// negligible tonnage. No coefficient.

// ---------------------------------------------------------------------------
// The derived ledger
// ---------------------------------------------------------------------------

/// Derived HAVE cache. `built == false` IS the None arm: every accessor
/// answers "not gated". Never serialized, never hashed.
#[derive(Clone, Debug, Default)]
pub struct Have {
    /// By `NationId` index; annual; the table's units; oil = kb/d.
    pub flow: Vec<[f64; 12]>,
    /// By `NationId` index: presence bits of every district held, plus every
    /// line with a positive flow.
    pub presence: Vec<u16>,
    pub built: bool,
    pub epoch: u64,
    /// `(nations.len(), alive count)` — a birth or a death rebuilds.
    pub alive_stamp: (usize, usize),
}

const OIL: usize = Commodity::Oil as usize;

fn alive_stamp(w: &WorldState) -> (usize, usize) {
    (w.nations.len(), w.nations.iter().filter(|n| n.alive).count())
}

/// HAVE for every nation: a pure function of the 1990 table and the current
/// ownership map. One pass over the located rows and the presence rows —
/// never over `w.districts`. Measured 0.10 ms at 137 nations, paid only on an
/// ownership change.
pub fn have_table(w: &WorldState) -> Have {
    let t = tables();
    let nn = nation_count();
    let mut flow = vec![[0.0f64; 12]; nn];
    let mut presence = vec![0u16; nn];
    // Unlocated (national-only) production stays with its 1990 owner while it
    // lives. Annexation moves none of it; nothing can, honestly.
    for (i, p) in t.production.iter().enumerate() {
        let alive = NationId::from_index(i)
            .and_then(|id| w.nation_opt(id))
            .is_some_and(|n| n.alive);
        if !alive {
            continue;
        }
        for c in 0..12 {
            if c != OIL && t.unlocated[i][c] {
                flow[i][c] += p[c];
            }
        }
    }
    // Located production follows the district it sits in.
    for r in &t.district_rows {
        if r.c == OIL {
            continue;
        }
        if let Some(cur) = w.districts.get(&r.district) {
            flow[cur.index()][r.c] += r.share * t.production[r.owner_1990.index()][r.c];
        }
    }
    // Oil is the single ledger, kb/d; districts only say where it sits.
    for n in w.nations.iter().filter(|n| n.alive) {
        flow[n.id.index()][OIL] = n.oil_mbd * 1000.0;
    }
    for (d, mask) in &t.presence_rows {
        if let Some(cur) = w.districts.get(d) {
            presence[cur.index()] |= mask;
        }
    }
    for (i, f) in flow.iter().enumerate() {
        for c in 0..12 {
            if f[c] > 0.0 {
                presence[i] |= 1 << c;
            }
        }
    }
    for (owner, c, output) in completed_mine_outputs(w, None) {
        flow[owner.index()][c.idx()] += output;
        presence[owner.index()] |= c.bit();
    }
    Have { flow, presence, built: true, epoch: w.districts_epoch, alive_stamp: alive_stamp(w) }
}

/// The SYSTEMS entry, between `economy` and `tech`: the cache must exist
/// before tech and arsenal read it. Rebuilds on an ownership or roster change;
/// otherwise refreshes the oil column, which moves monthly.
pub fn tick(w: &mut WorldState) {
    advance_mines(w);
    let stamp = alive_stamp(w);
    let stale = !w.resource_have.built
        || w.resource_have.epoch != w.districts_epoch
        || w.resource_have.alive_stamp != stamp;
    if stale {
        w.resource_have = have_table(w);
    } else {
        for n in w.nations.iter().filter(|n| n.alive) {
            w.resource_have.flow[n.id.index()][OIL] = n.oil_mbd * 1000.0;
        }
        for (owner, c, output) in completed_mine_outputs(w, Some(Commodity::Oil)) {
            w.resource_have.flow[owner.index()][c.idx()] += output;
            w.resource_have.presence[owner.index()] |= c.bit();
        }
    }
    if !w.rules.resource_gates {
        return;
    }
    deliver_contracts(w);
    expire_offers(w);
    cool_grievances(w);
}

fn completed_mine_outputs(
    w: &WorldState,
    only: Option<Commodity>,
) -> Vec<(NationId, Commodity, f64)> {
    w.resources
        .mines
        .iter()
        .filter(|m| only.map_or(true, |c| m.commodity == c))
        .filter_map(|m| {
            let owner = *w.districts.get(&m.district)?;
            w.nation_opt(owner)
                .filter(|n| n.alive)
                .map(|_| (owner, m.commodity, m.output))
        })
        .collect()
}

fn advance_mines(w: &mut WorldState) {
    if w.resources.mine_projects.is_empty() {
        return;
    }
    let now = month_abs(w);
    let mut keep = Vec::with_capacity(w.resources.mine_projects.len());
    let mut completed = vec![];
    for mut project in std::mem::take(&mut w.resources.mine_projects) {
        let active = w
            .districts
            .get(&project.district)
            .copied()
            .and_then(|owner| w.nation_opt(owner))
            .is_some_and(|n| n.alive)
            && !district_contested(w, &project.district);
        if active {
            project.months_left = project.months_left.saturating_sub(1);
        }
        if project.months_left > 0 {
            keep.push(project);
        } else {
            completed.push(Mine {
                district: project.district,
                commodity: project.commodity,
                output: project.output,
                completed: now,
            });
        }
    }
    w.resources.mine_projects = keep;
    for mine in completed {
        let owner = w.districts.get(&mine.district).copied();
        let label = if matches!(mine.commodity, Commodity::Oil | Commodity::Gas) {
            "field"
        } else {
            "mine"
        };
        let district_name = crate::districts::name_of(&mine.district)
            .unwrap_or(mine.district.as_str());
        if let Some(owner) = owner {
            w.headline(format!(
                "{} opens the {} {} in {}.",
                owner.name(), mine.commodity.name(), label, district_name
            ));
        }
        let key = (mine.district.as_str(), mine.commodity);
        match w
            .resources
            .mines
            .binary_search_by(|m| (m.district.as_str(), m.commodity).cmp(&key))
        {
            Ok(i) => w.resources.mines[i] = mine,
            Err(i) => w.resources.mines.insert(i, mine),
        }
        w.resource_have.built = false;
    }
}

/// One month of every live contract (spec section 4.6), in vector order.
/// A contract dies with either party (successors do not inherit; headlined).
/// Money legs move `debt_gdp` both ways — the fiscal channel `PACT_UPKEEP`
/// and `aid_flows` already use — and an oil leg is money at today's world
/// price, the giver's `oil_mbd` untouched. Commodity legs move nothing: they
/// are READ by `supply()` as the receiver's inflow and by `surplus()` as the
/// giver's commitment, and when a giver's flow has fallen below what it
/// promised every leg of that line is delivered pro rata this month (force
/// majeure — headlined once per giver and line, uncharged). Depth grows at
/// a pact's rate; at zero months the contract has run its term. No relation
/// drift while running. A no-op while `contracts` is empty, which is every
/// world the suite runs.
fn deliver_contracts(w: &mut WorldState) {
    if w.resources.contracts.is_empty() {
        return;
    }
    let price = w.oil_price;
    let mut heads: Vec<String> = vec![];
    let mut keep = Vec::with_capacity(w.resources.contracts.len());
    for mut k in std::mem::take(&mut w.resources.contracts) {
        let alive = |id: NationId| w.nation_opt(id).is_some_and(|n| n.alive);
        if !alive(k.from) || !alive(k.to) {
            let dead = if alive(k.from) { k.to } else { k.from };
            heads.push(format!(
                "The {} contract between {} and {} dies with {}.",
                k.label(),
                k.from.name(),
                k.to.name(),
                dead.name()
            ));
            continue;
        }
        for (payer, payee, legs) in [(k.from, k.to, &k.give), (k.to, k.from, &k.take)] {
            for l in legs {
                let bn = match l {
                    Leg::Money { bn_per_year } => *bn_per_year,
                    Leg::Commodity { c: Commodity::Oil, per_month } => oil_leg_bn_per_year(*per_month, price),
                    _ => continue,
                };
                if bn > 0.0 {
                    settle(w, payer, payee, bn);
                }
            }
        }
        k.depth = (k.depth + DEPTH_RATE).min(1.0);
        k.months_left = k.months_left.saturating_sub(1);
        if k.months_left == 0 {
            heads.push(format!(
                "The {} contract between {} and {} has run its term.",
                k.label(),
                k.from.name(),
                k.to.name()
            ));
            continue;
        }
        keep.push(k);
    }
    w.resources.contracts = keep;
    // Force majeure, once per (giver, line, month).
    let mut promised: BTreeSet<(NationId, Commodity)> = BTreeSet::new();
    for k in &w.resources.contracts {
        for (giver, legs) in [(k.from, &k.give), (k.to, &k.take)] {
            for (c, _) in commodity_legs(legs) {
                promised.insert((giver, c));
            }
        }
    }
    for (giver, c) in promised {
        if delivery_ratio(w, giver, c) < 1.0 {
            heads.push(format!(
                "{} cannot deliver all of its {} this month; contracts are filled pro rata.",
                giver.name(),
                c.name()
            ));
        }
    }
    for h in heads {
        w.headline(h);
    }
}

/// One month of a money leg: `bn/12` of a year's money against each side's
/// output, the payer's debt up, the payee's down and floored at zero.
fn settle(w: &mut WorldState, payer: NationId, payee: NationId, bn_per_year: f64) {
    let g = w.nation(payer).gdp.max(0.1);
    w.nation_mut(payer).debt_gdp += bn_per_year / 12.0 / g;
    let g = w.nation(payee).gdp.max(0.1);
    let n = w.nation_mut(payee);
    n.debt_gdp = (n.debt_gdp - bn_per_year / 12.0 / g).max(0.0);
}

/// Offers past their month are gone (spec section 4.8), and the lapse is
/// remembered by the AI that made them as an `Unanswered` refusal on each
/// line it asked for (section 6.2): the AI waits for the player exactly as
/// long as it waits for itself, and asks again when that has cooled.
fn expire_offers(w: &mut WorldState) {
    if w.resources.offers.is_empty() {
        return;
    }
    let now = month_abs(w);
    let (lapsed, kept): (Vec<Offer>, Vec<Offer>) =
        std::mem::take(&mut w.resources.offers).into_iter().partition(|o| o.expires <= now);
    w.resources.offers = kept;
    for o in lapsed {
        let lines: Vec<Commodity> = o
            .take
            .iter()
            .filter_map(|l| match l {
                Leg::Commodity { c, .. } => Some(*c),
                _ => None,
            })
            .collect();
        for c in lines {
            remember_refusal(w, o.from, o.to, c, Reason::Unanswered);
        }
    }
}

/// A grievance is live while `until` is still ahead; past it, the row goes,
/// so a world that has forgotten serializes as one that never knew.
fn cool_grievances(w: &mut WorldState) {
    if w.resources.grievances.is_empty() {
        return;
    }
    let now = month_abs(w);
    w.resources.grievances.retain(|g| g.until > now);
}

// ---------------------------------------------------------------------------
// The persisted state
// ---------------------------------------------------------------------------

fn is_zero(v: &u32) -> bool {
    *v == 0
}

/// Everything the resource system persists. Every member is skipped when
/// empty so an untouched world serializes exactly as it did before this
/// existed. `Vec<Cover>` sorted by nation and `Vec<Refusal>` sorted by key
/// rather than maps: serde_json refuses non-string map keys, and
/// `statecraft.reputation: Vec<(NationId, f64)>` is the house idiom for a
/// sparse per-nation row. Upserts are `binary_search` + insert; iteration is
/// sorted by construction.
#[derive(Clone, Debug, Default, Serialize, Deserialize, PartialEq)]
pub struct Resources {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub mine_projects: Vec<MineProject>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub mines: Vec<Mine>,
    /// Sorted by nation. A row exists only while some line is below twelve.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub cover: Vec<Cover>,
    /// Creation order (S2).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub contracts: Vec<Contract>,
    /// Creation order (S2).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub offers: Vec<Offer>,
    /// Sorted by (buyer, seller, commodity) (S3).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub refusals: Vec<Refusal>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub grievances: Vec<Grievance>,
    #[serde(default, skip_serializing_if = "is_zero")]
    pub next_id: u32,
}

impl Resources {
    pub fn is_empty(&self) -> bool {
        self.mine_projects.is_empty()
            && self.mines.is_empty()
            && self.cover.is_empty()
            && self.contracts.is_empty()
            && self.offers.is_empty()
            && self.refusals.is_empty()
            && self.grievances.is_empty()
            && self.next_id == 0
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct MineProject {
    pub district: String,
    pub commodity: Commodity,
    pub started_by: NationId,
    pub months_left: u32,
    pub months_total: u32,
    pub investment_bn: f64,
    pub output: f64,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Mine {
    pub district: String,
    pub commodity: Commodity,
    pub output: f64,
    pub completed: i32,
}

/// Months of need in hand per line, 0..=12. Materialised on the first write
/// below twelve; removed when every line is back at twelve.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Cover {
    pub nation: NationId,
    pub months: [f64; 12],
}

/// One side of a bundle (S2).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Leg {
    /// The table's units per month; oil is kb/d and settles as money.
    Commodity { c: Commodity, per_month: f64 },
    Money { bn_per_year: f64 },
    /// One-shot at signing.
    District { id: String },
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Contract {
    pub id: u32,
    pub from: NationId,
    pub to: NationId,
    /// from → to.
    pub give: Vec<Leg>,
    /// to → from.
    pub take: Vec<Leg>,
    pub months_left: u32,
    pub months_total: u32,
    /// `month_abs` at signing.
    pub since: i32,
    pub depth: f64,
}

/// An AI buyer's standing offer to the player (S3).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Offer {
    pub id: u32,
    pub from: NationId,
    pub to: NationId,
    pub give: Vec<Leg>,
    pub take: Vec<Leg>,
    pub months: u32,
    /// `month_abs`.
    pub expires: i32,
}

/// A torn-up contract, remembered by the victim (S2).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Grievance {
    pub victim: NationId,
    pub breaker: NationId,
    /// `month_abs`.
    pub until: i32,
}

/// Why a receiver refuses. Each carries fixed prose (`sentence`, pinned by
/// test). `NotForThatPrice` names the price the counter would have wanted;
/// it is served to the player's card and never remembered as a refusal.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum Reason {
    AtWar,
    Embargoed,
    BrokeContract,
    Distrust,
    NoSurplus,
    LandContested,
    NotForSale,
    LandDistrust,
    GovernmentWouldFall,
    LastDistrict,
    NotForThatPrice { bn_per_year: f64 },
    Unanswered,
}

impl Reason {
    /// The fixed prose of spec section 4.4, verbatim.
    pub fn sentence(&self) -> String {
        match self {
            Reason::AtWar => "We are at war with you.".into(),
            Reason::Embargoed => "Sanctions bar it.".into(),
            Reason::BrokeContract => "You broke your last contract with us.".into(),
            Reason::Distrust => "We do not deal with a state we distrust.".into(),
            Reason::NoSurplus => "We haven't the surplus.".into(),
            Reason::LandContested => "That ground is being fought over.".into(),
            Reason::NotForSale => "Nobody sells their people.".into(),
            Reason::LandDistrust => "We do not sell land to a state we do not trust.".into(),
            Reason::GovernmentWouldFall => "The government would not survive selling it.".into(),
            Reason::LastDistrict => "It is all we have.".into(),
            Reason::NotForThatPrice { bn_per_year } => {
                format!("Not for that price: we would want ${bn_per_year:.1} bn a year.")
            }
            Reason::Unanswered => "You let our last offer lapse.".into(),
        }
    }
}

/// A seller's answer, as the buyer remembers it (S3 writes it). A row with
/// `NotForThatPrice` is not a refusal — it is the clock that keeps a
/// priced-out ask from being repeated every month — and `is_refusal` is
/// what every count and the predicate read.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Refusal {
    pub buyer: NationId,
    pub seller: NationId,
    pub c: Commodity,
    pub reason: Reason,
    pub heat: f64,
    pub asks: u32,
}

impl Refusal {
    /// A hard bar. PricedOut ("for any amount of money") never is.
    pub fn is_refusal(&self) -> bool {
        !matches!(self.reason, Reason::NotForThatPrice { .. })
    }
}

/// What a resource war is for: the district and the line (S3 writes it;
/// declared here so the save shape settles once).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Aim {
    pub district: String,
    pub commodity: Commodity,
}

// ---------------------------------------------------------------------------
// Accessors — pure; every one answers the None arm when the cache is unbuilt
// ---------------------------------------------------------------------------

/// The cache, or a local build when it is unbuilt (the month after a load,
/// before the first tick).
pub fn have(w: &WorldState) -> Cow<'_, Have> {
    if w.resource_have.built {
        Cow::Borrowed(&w.resource_have)
    } else {
        Cow::Owned(have_table(w))
    }
}

/// Annual own production of `c`, the table's units; 0 when unbuilt.
pub fn flow(w: &WorldState, id: NationId, c: Commodity) -> f64 {
    flow_of(&w.resource_have, id, c)
}

/// `flow` against a given ledger — the world's cache, or the local build a
/// command reads through `have()` the month after a load (spec section 1.15).
fn flow_of(h: &Have, id: NationId, c: Commodity) -> f64 {
    if !h.built {
        return 0.0;
    }
    h.flow.get(id.index()).map_or(0.0, |f| f[c.idx()])
}

/// Months of need in hand; `BUFFER_MONTHS` when no row exists.
pub fn cover(w: &WorldState, id: NationId, c: Commodity) -> f64 {
    match w.resources.cover.binary_search_by_key(&id, |r| r.nation) {
        Ok(i) => w.resources.cover[i].months[c.idx()],
        Err(_) => BUFFER_MONTHS,
    }
}

/// This month's need: what the kit procurement would pick wants, at the
/// nation's line. Zero for the legacy tier, for a nation with nothing to
/// buy, and for a seat that is not on the board.
pub fn draw(w: &WorldState, id: NationId) -> [f64; 12] {
    let Some(n) = w.nation_opt(id) else { return [0.0; 12] };
    match crate::arsenal::pick(n) {
        Some(kit) => kit_need(kit, crate::arsenal::line_of(n)),
        None => [0.0; 12],
    }
}

/// The commodity legs of one side of a bundle — oil excluded, because an oil
/// leg is money at the world price and never a delivery (spec section 4.6).
fn commodity_legs(legs: &[Leg]) -> impl Iterator<Item = (Commodity, f64)> + '_ {
    legs.iter().filter_map(|l| match l {
        Leg::Commodity { c, per_month } if *c != Commodity::Oil => Some((*c, *per_month)),
        _ => None,
    })
}

/// The district legs of one side of a bundle.
fn district_legs(legs: &[Leg]) -> impl Iterator<Item = &str> + '_ {
    legs.iter().filter_map(|l| match l {
        Leg::District { id } => Some(id.as_str()),
        _ => None,
    })
}

/// Σ contract legs `id` gives of `c` this month — what it promised, before
/// force majeure.
pub fn committed_out(w: &WorldState, id: NationId, c: Commodity) -> f64 {
    let mut q = 0.0;
    for k in &w.resources.contracts {
        let legs = if k.from == id {
            &k.give
        } else if k.to == id {
            &k.take
        } else {
            continue;
        };
        q += commodity_legs(legs).filter(|(lc, _)| *lc == c).map(|(_, p)| p).sum::<f64>();
    }
    q
}

/// A giver's delivery ratio for `c`: one while its flow covers what it
/// promised, else `flow/12 ÷ promised` — force majeure, pro rata across
/// every contract it gives `c` under (spec section 4.6).
pub fn delivery_ratio(w: &WorldState, giver: NationId, c: Commodity) -> f64 {
    delivery_ratio_with(w, &w.resource_have, giver, c)
}

fn delivery_ratio_with(w: &WorldState, h: &Have, giver: NationId, c: Commodity) -> f64 {
    let promised = committed_out(w, giver, c);
    if promised <= 0.0 {
        return 1.0;
    }
    (flow_of(h, giver, c) / 12.0 / promised).clamp(0.0, 1.0)
}

/// Σ contract legs `id` receives of `c` this month, each scaled by its
/// giver's delivery ratio.
pub fn contracted_in(w: &WorldState, id: NationId, c: Commodity) -> f64 {
    contracted_in_with(w, &w.resource_have, id, c)
}

fn contracted_in_with(w: &WorldState, h: &Have, id: NationId, c: Commodity) -> f64 {
    let mut q = 0.0;
    for k in &w.resources.contracts {
        let (giver, legs) = if k.to == id {
            (k.from, &k.give)
        } else if k.from == id {
            (k.to, &k.take)
        } else {
            continue;
        };
        let promised: f64 = commodity_legs(legs).filter(|(lc, _)| *lc == c).map(|(_, p)| p).sum();
        if promised > 0.0 {
            q += promised * delivery_ratio_with(w, h, giver, c);
        }
    }
    q
}

/// What `id` could sell of `c` this month: own flow less its own draw, its
/// commitments, and a year of its draw held in reserve.
pub fn surplus(w: &WorldState, id: NationId, c: Commodity) -> f64 {
    surplus_with(w, &w.resource_have, &live_draws(w), id, c)
}

/// Where the arithmetic reads a nation's draw this month: the live
/// computation (`draw`, a `pick` each time), or — inside one buy pass — a
/// memo of it, since a nation's draw does not move within the month the
/// pass runs in. Either is a pure function of the world.
pub type Draws<'a> = dyn Fn(NationId) -> [f64; 12] + 'a;

fn live_draws(w: &WorldState) -> impl Fn(NationId) -> [f64; 12] + '_ {
    move |id| draw(w, id)
}

fn surplus_with(w: &WorldState, h: &Have, draws: &Draws, id: NationId, c: Commodity) -> f64 {
    let d = draws(id)[c.idx()];
    flow_of(h, id, c) / 12.0 - d - committed_out(w, id, c) - d * RESERVE_MONTHS / 12.0
}

fn holds(h: &Have, id: NationId, c: Commodity) -> bool {
    h.flow.get(id.index()).is_some_and(|f| f[c.idx()] > 0.0)
}

fn open_to(w: &WorldState, buyer: NationId, h: NationId) -> bool {
    !w.is_sanctioning(h, buyer)
        && !w.is_sanctioning(buyer, h)
        && !crate::statecraft::belligerents(w, buyer, h)
        && w.relation(buyer, h) >= relation_floor()
}

/// The first living holder of `c`, in `NationId` order, that is open to
/// `buyer`: not sanctioning it, not sanctioned by it, not fighting it, and
/// not below the relation floor.
pub fn open_holder(w: &WorldState, buyer: NationId, c: Commodity) -> Option<NationId> {
    let h = have(w);
    all_nations()
        .iter()
        .copied()
        .filter(|id| *id != buyer && holds(&h, *id, c))
        .filter(|id| w.nation_opt(*id).is_some_and(|n| n.alive))
        .find(|id| open_to(w, buyer, *id))
}

/// Every living producer of `c`, `NationId` order.
pub fn producers(w: &WorldState, c: Commodity) -> Vec<NationId> {
    let h = have(w);
    all_nations()
        .iter()
        .copied()
        .filter(|id| holds(&h, *id, c) && w.nation_opt(*id).is_some_and(|n| n.alive))
        .collect()
}

/// Who feeds `need` of `c` to `buyer` this month, and how much of it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Supply {
    pub own: f64,
    pub contracts: f64,
    pub market: f64,
    pub available: f64,
    pub holder: Option<NationId>,
    /// Some living producer other than the buyer exists at all — the
    /// difference between "every producer refuses" and "nobody produces it".
    pub any_producer: bool,
}

/// Pure over `&WorldState`, no RNG. Own flow, contract inflow, and an open
/// market that fills the gap while any holder is open. `ration` is 0 in cut
/// one (spec section 1.4; cut two adds the sanction ration).
pub fn supply(w: &WorldState, buyer: NationId, c: Commodity, need: f64) -> Supply {
    supply_with(w, &w.resource_have, buyer, c, need)
}

fn supply_with(w: &WorldState, h: &Have, buyer: NationId, c: Commodity, need: f64) -> Supply {
    if !c.tracked() || !h.built {
        return Supply { own: 0.0, contracts: 0.0, market: 0.0, available: 0.0, holder: None, any_producer: false };
    }
    let own = flow_of(h, buyer, c) / 12.0;
    let contracts = contracted_in_with(w, h, buyer, c);
    let mut any_producer = false;
    let mut holder = None;
    for id in all_nations().iter().copied() {
        if id == buyer || !holds(h, id, c) || !w.nation_opt(id).is_some_and(|n| n.alive) {
            continue;
        }
        any_producer = true;
        if open_to(w, buyer, id) {
            holder = Some(id);
            break;
        }
    }
    let market = if holder.is_some() {
        let gap = (need - own - contracts).max(0.0);
        // SANCTION_RATION (cut two, behind the market switch): the share of
        // the buyer's imports its embargoes shut out — the constant its oil
        // exports already pay, `oil_blockade`, and the only route by which
        // the sim's own coalitions ever close a market. Switch off, the gap
        // is the gap, the same bytes as before the ration existed.
        if w.rules.resource_market && ration_on() {
            gap * (1.0 - w.oil_blockade(buyer))
        } else {
            gap
        }
    } else {
        0.0
    };
    Supply { own, contracts, market, available: own + contracts + market, holder, any_producer }
}

/// What ordering `kit` with `line_bn` this month wants, in the table's units
/// per month. Zero for the legacy tier (`tech: None`).
pub fn kit_need(kit: u16, line_bn: f64) -> [f64; 12] {
    let mut need = [0.0; 12];
    let Some(def) = DECK.get(kit as usize) else { return need };
    if def.tech.is_none() || line_bn <= 0.0 {
        return need;
    }
    match def.class {
        Class::Naval => {
            need[Commodity::Iron.idx()] = line_bn * NAVAL_ORE_KT_PER_BN * 1000.0;
            need[Commodity::Coal.idx()] = line_bn * NAVAL_COAL_KT_PER_BN;
        }
        Class::Armour => {
            need[Commodity::Iron.idx()] = line_bn * ARMOUR_ORE_KT_PER_BN * 1000.0;
            need[Commodity::Coal.idx()] = line_bn * ARMOUR_COAL_KT_PER_BN;
        }
        Class::Air => {
            need[Commodity::Bauxite.idx()] = line_bn * AIR_BAUXITE_KT_PER_BN * 1000.0;
        }
        Class::Missile | Class::Space => {
            need[Commodity::Copper.idx()] = line_bn * MISSILE_COPPER_KT_PER_BN * 1000.0;
        }
        Class::Infantry => {}
    }
    need
}

/// `(year − 1990) × 12 + (month − 1)`, the web's `month_index`.
pub fn month_abs(w: &WorldState) -> i32 {
    (w.year - 1990) * 12 + (w.month as i32 - 1)
}

// ---------------------------------------------------------------------------
// The gate
// ---------------------------------------------------------------------------

/// A line that asked for what it could not get.
#[derive(Clone, Debug, PartialEq)]
pub struct Stall {
    pub nation: NationId,
    pub kit: u16,
    pub commodity: Commodity,
    /// "every producer refuses" | "nobody produces it"
    pub why: &'static str,
}

impl Stall {
    pub fn headline(&self) -> String {
        format!(
            "{}: {} line delayed - needs {}; {}.",
            self.nation.name(),
            DECK[self.kit as usize].name,
            self.commodity.name(),
            self.why
        )
    }
}

/// The only writer of `cover`. Spec section 1.3: a shortfall month takes
/// `1 − available/need` off the pile; a surplus month puts back
/// `min(1, (available − need)/need)`, capped at twelve. The row is
/// materialised on the first write below twelve and removed when every line
/// is back at twelve, so a full pile is no row and no bytes.
pub(crate) fn write_cover(w: &mut WorldState, id: NationId, c: Commodity, available: f64, need: f64) -> f64 {
    let cur = cover(w, id, c);
    let next = if need <= 0.0 {
        cur
    } else if available < need {
        cur - (1.0 - available / need)
    } else {
        cur + ((available - need) / need).min(1.0)
    }
    .clamp(0.0, BUFFER_MONTHS);
    let ci = c.idx();
    match w.resources.cover.binary_search_by_key(&id, |r| r.nation) {
        Ok(i) => {
            w.resources.cover[i].months[ci] = next;
            if w.resources.cover[i].months.iter().all(|m| *m >= BUFFER_MONTHS) {
                w.resources.cover.remove(i);
            }
        }
        Err(i) => {
            if next < BUFFER_MONTHS {
                let mut months = [BUFFER_MONTHS; 12];
                months[ci] = next;
                w.resources.cover.insert(i, Cover { nation: id, months });
            }
        }
    }
    next
}

/// Read-only: could `id` feed `kit` at `line` this month?
fn inputs_held(w: &WorldState, id: NationId, kit: u16, line: f64) -> bool {
    let need = kit_need(kit, line);
    ALL.iter()
        .filter(|c| c.tracked() && need[c.idx()] > 0.0)
        .all(|c| supply(w, id, *c, need[c.idx()]).available >= need[c.idx()])
}

/// The gate at the arsenal's pick. Checks only the chosen kit (≤ four
/// queries); writes the pile for each line it asked about; stalls only when a
/// line is short AND the pile is empty. Then: a player's stated preference
/// stalls with the message and the money banks; the AI ranks the rest — sort
/// only now — and takes the best kit whose inputs are held. Returns the kit
/// to order and, if the chosen kit was skipped or the preference stalled,
/// why. Charges nothing.
pub fn gate(w: &mut WorldState, id: NationId, kit: u16, line: f64) -> (Option<u16>, Option<Stall>) {
    let need = kit_need(kit, line);
    if need.iter().all(|q| *q <= 0.0) {
        return (Some(kit), None);
    }
    let mut short: Option<(Commodity, &'static str)> = None;
    for c in ALL.iter().filter(|c| c.tracked() && need[c.idx()] > 0.0) {
        let s = supply(w, id, *c, need[c.idx()]);
        let cv = write_cover(w, id, *c, s.available, need[c.idx()]);
        if s.available < need[c.idx()] && cv <= 0.0 && short.is_none() {
            short = Some((*c, if s.any_producer { "every producer refuses" } else { "nobody produces it" }));
        }
    }
    let Some((c, why)) = short else { return (Some(kit), None) };
    let stall = Stall { nation: id, kit, commodity: c, why };
    let preferred = w
        .nation(id)
        .arsenal
        .preference
        .as_deref()
        .and_then(crate::arsenal::index_of)
        == Some(kit);
    if preferred {
        return (None, Some(stall));
    }
    for alt in crate::arsenal::ranked(w.nation(id)).into_iter().filter(|k| *k != kit) {
        if inputs_held(w, id, alt, line) {
            return (Some(alt), Some(stall));
        }
    }
    (None, Some(stall))
}

// ---------------------------------------------------------------------------
// Trade (package S2): the mechanic constants (Appendix A: named, classed,
// justified)
// ---------------------------------------------------------------------------

/// The terms a contract may run, in months (M): a year, three, five, ten.
pub const TERMS: [u32; 4] = [12, 36, 60, 120];

/// A bundle carries at most this many legs, at most one of them land (M).
pub const MAX_LEGS: usize = 4;

/// The most output a nation may have under contract at once (M): the same
/// share `statecraft::MAX_AID_SHARE` lets a patron promise away, so the two
/// fiscal channels a government can open abroad are bounded alike.
pub const MAX_CONTRACT_SPEND: f64 = crate::statecraft::MAX_AID_SHARE;

/// A tonne that covers a shortfall is worth its stall (M): four times the
/// 1990 unit value, from the receiver's chair.
pub const SCARCITY: f64 = 4.0;

/// A tonne beyond the receiver's uncovered draw resells at a discount (M).
pub const RESALE: f64 = 0.5;

/// Selling your whole surplus doubles its price (M): a leg out costs
/// `1 + STRATEGIC × q / surplus` times its value.
pub const STRATEGIC: f64 = 1.0;

/// Ten years of a district's 1990 output is the buyer's horizon (M).
pub const LAND_YEARS: f64 = 10.0;

/// A seller wants four times that horizon to part with ground (M).
pub const SOVEREIGNTY: f64 = 4.0;

/// Nobody signs at break-even (M): the receiver's gain must clear this share
/// of what the deal costs it.
pub const MARGIN: f64 = 0.10;

/// Nobody sells their people (M): a district holding more than this share
/// of the ceder's population is never for sale.
pub const NOT_FOR_SALE_POP: f64 = 0.05;

/// A receiver sells land only to a state it trusts at least this well (M).
pub const LAND_TRUST: f64 = 40.0;

/// A government below this stability would not survive selling ground (M).
pub const GOVERNMENT_FLOOR: f64 = 50.0;

/// Relation at signing (M): `statecraft::propose_trade`'s figure.
pub const SIGN_RELATION: f64 = 5.0;

/// Depth per month of a running contract (M): `statecraft::trade_deepens`'s
/// rate, so a contract and a pact mature at the same pace.
pub const DEPTH_RATE: f64 = 0.012;

/// Tearing one up (M): `statecraft::abrogate_trade`'s own reputation and
/// relation figures, and three years of being remembered by the other side.
pub const CANCEL_REPUTATION: f64 = -6.0;
pub const CANCEL_RELATION: f64 = -25.0;
pub const GRIEVANCE_MONTHS: i32 = 36;

/// One dollar, in the billions every value here is counted in. `ceil10`
/// rounds a counter UP to the tenth of a billion, so a counter re-offered
/// clears the margin by construction; this is the slack that keeps a
/// floating-point product from undoing that at the last digit. Not a
/// tolerance on any bar: a deal a dollar short of the margin is a deal at
/// the margin.
const DOLLAR: f64 = 1e-9;

/// What the receiver says (spec section 4.4). `Counter` carries the money
/// the proposer would have to pay, per year, and the receiver's own legs
/// clipped to its surplus; re-offered unchanged, it is accepted by
/// construction.
#[derive(Clone, Debug, PartialEq)]
pub enum Verdict {
    Accept,
    Counter { money_bn_per_year: f64, take: Vec<Leg> },
    Refuse(Reason),
}

/// Rounds a price UP to the tenth of a billion.
pub fn ceil10(x: f64) -> f64 {
    (x * 10.0).ceil() / 10.0
}

/// The step `ceil10` rounds to, $bn a year: the least any counter names. A
/// proposer whose spending cap is below it is priced out of every counter
/// before one is computed, which is how the buy pass knows not to compute
/// it.
pub const PRICE_STEP: f64 = 0.1;

/// A kb/d for a year is 365 kb; at `price` dollars a barrel that is
/// `365 × 1000 × price` dollars, here in billions. The one place oil is
/// priced in this module: a leg, a district's oil output, the spend cap.
pub fn oil_leg_bn_per_year(kb_d: f64, price: f64) -> f64 {
    kb_d * 1000.0 * 365.0 * price / 1e9
}

/// The 1990 unit value in billions of dollars per one unit of `c`; none for
/// oil, which is priced at the world price, and for a line with no sourced
/// price.
pub fn unit_price_bn(c: Commodity) -> Option<f64> {
    tables().price[c.idx()].map(|usd| usd / 1e9)
}

/// What `per_month` units of `c` a month are worth over a year, $bn: the
/// table's price, or the world price for oil.
pub fn leg_bn_per_year(w: &WorldState, c: Commodity, per_month: f64) -> f64 {
    if c == Commodity::Oil {
        oil_leg_bn_per_year(per_month, w.oil_price)
    } else {
        per_month * 12.0 * unit_price_bn(c).unwrap_or(0.0)
    }
}

/// A line can be contracted while it is tracked and priced. Oil is priced at
/// the world price; every other tracked line carries its 1990 unit value
/// (none is omitted today; a withdrawn figure or price falls out here by
/// itself and the leg is refused with its sentence).
pub fn contractable(c: Commodity) -> bool {
    c.tracked() && (c == Commodity::Oil || tables().price[c.idx()].is_some())
}

/// The sentence a leg on a line with no 1990 figure gets (spec section 4.3).
pub fn untracked_leg_sentence(c: Commodity) -> String {
    format!("No 1990 figure is transcribed for {}; it cannot be contracted.", c.name())
}

/// A quantity as a card prints it: thousands separated, no more digits than
/// the size warrants.
fn human(q: f64) -> String {
    let s = if q >= 100.0 {
        format!("{q:.0}")
    } else if q >= 10.0 {
        format!("{q:.1}")
    } else {
        format!("{q:.2}")
    };
    let s = if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.').to_string() } else { s };
    let (int, frac) = match s.split_once('.') {
        Some((i, f)) => (i.to_string(), Some(f.to_string())),
        None => (s, None),
    };
    let digits: Vec<char> = int.chars().collect();
    let mut out = String::new();
    for (i, ch) in digits.iter().enumerate() {
        if i > 0 && (digits.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*ch);
    }
    match frac {
        Some(f) => format!("{out}.{f}"),
        None => out,
    }
}

impl Leg {
    /// One leg in words, for the signing headline and the contract line.
    pub fn describe(&self) -> String {
        match self {
            Leg::Commodity { c: Commodity::Oil, per_month } => {
                format!("{} kb/d of oil at the world price", human(*per_month))
            }
            Leg::Commodity { c, per_month } => format!("{} {}/mo of {}", human(*per_month), c.unit(), c.name()),
            Leg::Money { bn_per_year } => format!("${bn_per_year:.1}bn a year"),
            Leg::District { id } => {
                format!("the district of {}", crate::districts::name_of(id).unwrap_or(id))
            }
        }
    }
}

impl Contract {
    /// The line a headline names the contract after: its first commodity
    /// leg, or "supply" for a bundle of money and land.
    pub fn label(&self) -> &'static str {
        self.give
            .iter()
            .chain(self.take.iter())
            .find_map(|l| match l {
                Leg::Commodity { c, .. } => Some(c.name()),
                _ => None,
            })
            .unwrap_or("supply")
    }
    pub fn other(&self, id: NationId) -> NationId {
        if self.from == id {
            self.to
        } else {
            self.from
        }
    }
}

/// How many districts `id` holds.
pub fn holdings(w: &WorldState, id: NationId) -> usize {
    w.districts.values().filter(|&&o| o == id).count()
}

/// A district's share of its holder's people (spec section 1.11): its 1990
/// population share over the sum across every district the holder holds
/// today. One definition, read by the land bars, the land premium and the
/// transfer; zero for ground the holder does not hold.
pub fn pop_share_of(w: &WorldState, holder: NationId, d: &str) -> f64 {
    if w.districts.get(d) != Some(&holder) {
        return 0.0;
    }
    let ps = &tables().file.pop_share;
    let mine = ps.get(d).copied().unwrap_or(0.0);
    let total: f64 = w
        .districts
        .iter()
        .filter(|&(_, &o)| o == holder)
        .map(|(id, _)| ps.get(id).copied().unwrap_or(0.0))
        .sum();
    if total > 0.0 {
        mine / total
    } else {
        0.0
    }
}

/// The 1990 oil the table locates in one district, kb/d.
fn located_oil_kbd(d: &str) -> f64 {
    let t = tables();
    let start = t.district_rows.partition_point(|r| r.district.as_str() < d);
    t.district_rows[start..]
        .iter()
        .take_while(|r| r.district == d)
        .filter(|r| r.c == OIL)
        .map(|r| r.share * t.production[r.owner_1990.index()][OIL])
        .sum()
}

/// The share of `holder`'s oil ledger that sits in `d` (spec section 4.9):
/// the district's located 1990 oil over everything the holder's districts
/// locate plus what its own figure never located. An unlocated producer's
/// districts locate nothing, so selling one moves no oil, and the card says
/// "located in ceded ground: 0%".
pub fn located_oil_fraction(w: &WorldState, holder: NationId, d: &str) -> f64 {
    let t = tables();
    let mut total: f64 =
        w.districts.iter().filter(|&(_, &o)| o == holder).map(|(id, _)| located_oil_kbd(id)).sum();
    if t.unlocated.get(holder.index()).is_some_and(|u| u[OIL]) {
        total += t.production[holder.index()][OIL];
    }
    if total > 0.0 && w.districts.get(d) == Some(&holder) {
        located_oil_kbd(d) / total
    } else {
        0.0
    }
}

/// A district's 1990 output at 1990 prices, $bn a year: the located share of
/// each line it carries times its 1990 owner's figure, oil at the world
/// price. The one number a district is worth in a bundle.
pub fn district_output_bn_per_year(w: &WorldState, d: &str) -> f64 {
    let t = tables();
    let start = t.district_rows.partition_point(|r| r.district.as_str() < d);
    t.district_rows[start..]
        .iter()
        .take_while(|r| r.district == d)
        .map(|r| {
            let annual = r.share * t.production[r.owner_1990.index()][r.c];
            let c = ALL[r.c];
            if c == Commodity::Oil {
                oil_leg_bn_per_year(annual, w.oil_price)
            } else {
                annual * unit_price_bn(c).unwrap_or(0.0)
            }
        })
        .sum()
}

/// Whether `d` is being fought over: on any live conflict's front, or in the
/// ground a conflict's principals contest (front.rs's contested set — the two
/// principals' home-theatre districts — read here without building it).
pub fn district_contested(w: &WorldState, d: &str) -> bool {
    let Some(&owner) = w.districts.get(d) else { return false };
    w.conflicts.iter().any(|c| {
        if c.front.contains_key(d) {
            return true;
        }
        let (att, def) = (c.attacker(), c.defender());
        (owner == att && crate::theatre::is_home(w, att, c.theatre))
            || (owner == def && att != def && crate::theatre::is_home(w, def, c.theatre))
    })
}

/// The money side of one side of a bundle, $bn a year: its money legs and
/// its oil legs at today's world price.
fn money_of(w: &WorldState, legs: &[Leg]) -> f64 {
    legs.iter()
        .map(|l| match l {
            Leg::Money { bn_per_year } => *bn_per_year,
            Leg::Commodity { c: Commodity::Oil, per_month } => oil_leg_bn_per_year(*per_month, w.oil_price),
            _ => 0.0,
        })
        .sum()
}

/// The money `id` pays under its live contracts, $bn a year.
pub fn contracted_spend(w: &WorldState, id: NationId) -> f64 {
    w.resources
        .contracts
        .iter()
        .map(|k| {
            if k.from == id {
                money_of(w, &k.give)
            } else if k.to == id {
                money_of(w, &k.take)
            } else {
                0.0
            }
        })
        .sum()
}

/// What `id` may still commit, $bn a year: `MAX_CONTRACT_SPEND` of its
/// output less what it already pays.
pub fn cap(w: &WorldState, id: NationId) -> f64 {
    let gdp = w.nation_opt(id).map_or(0.0, |n| n.gdp);
    MAX_CONTRACT_SPEND * gdp - contracted_spend(w, id)
}

/// The political price of ceding ground with a bundle (spec section 4.2):
/// twenty, plus three hundred times the share of the ceder's people on it.
pub fn land_premium(w: &WorldState, from: NationId, give: &[Leg]) -> f64 {
    district_legs(give).map(|d| 20.0 + 300.0 * pop_share_of(w, from, d)).sum()
}

/// The receiver's ledger of a bundle over `years`, $bn: what comes in, what
/// goes out, and the money the proposer pays per year — the one leg a
/// counter moves. Spec section 4.4's value arithmetic, nothing else.
fn value_of(
    w: &WorldState,
    h: &Have,
    draws: &Draws,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    years: f64,
) -> (f64, f64, f64) {
    let rel = w.relation(from, to);
    let hostility = 1.0 + (-rel).max(0.0) / 50.0;
    let partners = w.pact_partners(to);
    let patrons = w.patrons_of(to);
    let bloc = if partners.iter().chain(patrons.iter()).any(|x| w.is_sanctioning(*x, from)) { 2.0 } else { 1.0 };
    let draw_to = draws(to);
    let (mut value_in, mut cost_out, mut money_in) = (0.0, 0.0, 0.0);
    for l in give {
        match l {
            Leg::Commodity { c: Commodity::Oil, per_month } => {
                value_in += years * oil_leg_bn_per_year(*per_month, w.oil_price);
            }
            Leg::Commodity { c, per_month } => {
                let need = draw_to[c.idx()];
                let gap = (need - supply_with(w, h, to, *c, need).available).max(0.0);
                let covering = per_month.min(gap);
                value_in += years
                    * 12.0
                    * unit_price_bn(*c).unwrap_or(0.0)
                    * (covering * SCARCITY + (per_month - covering) * RESALE);
            }
            Leg::Money { bn_per_year } => {
                value_in += bn_per_year * years;
                money_in += bn_per_year;
            }
            Leg::District { id } => {
                value_in += district_output_bn_per_year(w, id)
                    * LAND_YEARS
                    * (1.0 + 2.0 * crate::nations::claim_share(to, from));
            }
        }
    }
    for l in take {
        match l {
            Leg::Commodity { c: Commodity::Oil, per_month } => {
                cost_out += years * oil_leg_bn_per_year(*per_month, w.oil_price);
            }
            Leg::Commodity { c, per_month } => {
                let s = surplus_with(w, h, draws, to, *c).max(DOLLAR);
                cost_out += years
                    * 12.0
                    * unit_price_bn(*c).unwrap_or(0.0)
                    * per_month
                    * (1.0 + STRATEGIC * per_month / s)
                    * hostility
                    * bloc;
            }
            Leg::Money { bn_per_year } => cost_out += bn_per_year * years,
            Leg::District { id } => {
                cost_out += district_output_bn_per_year(w, id) * LAND_YEARS * SOVEREIGNTY;
            }
        }
    }
    (value_in, cost_out, money_in)
}

/// The one function (spec sections 1.9 and 4.4). Pure over `&WorldState`,
/// from the receiver's chair; the AI, the buy pass and `/api/talks` all call
/// it. Hard bars in order with fixed prose; then value in $bn over the term:
/// accept if `gain ≥ MARGIN × cost_out`; else counter with the proposer's
/// money raised to the price that makes the gain exactly the margin, the
/// receiver's commodity legs clipped to its surplus; a counter above the
/// proposer's cap is `NotForThatPrice`. A counter re-offered unchanged is
/// accepted by construction.
///
/// The spec's sketch of the counter (4.4) wrote the price as
/// `(MARGIN × cost − nonmoney_in) / T`, which lands the receiver at
/// `gain = (MARGIN − 1) × cost` — a loss — and could never be accepted when
/// re-offered; the sentence beside it ("the price that makes gain = MARGIN ×
/// cost_out") is the model, and that is `((1 + MARGIN) × cost − nonmoney_in)
/// / T`. Decided for the sentence; recorded here and in the test.
pub fn evaluate(
    w: &WorldState,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    months: u32,
) -> Verdict {
    evaluate_with(w, &live_draws(w), from, to, give, take, months)
}

/// The hard bars of spec section 4.4, in order, each with its reason;
/// `None` when the bundle clears them all and the value decides.
fn hard_bars(
    w: &WorldState,
    h: &Have,
    draws: &Draws,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
) -> Option<Reason> {
    if crate::statecraft::belligerents(w, from, to) {
        return Some(Reason::AtWar);
    }
    if w.is_sanctioning(from, to) || w.is_sanctioning(to, from) {
        return Some(Reason::Embargoed);
    }
    let now = month_abs(w);
    if w.resources.grievances.iter().any(|g| g.victim == to && g.breaker == from && g.until > now) {
        return Some(Reason::BrokeContract);
    }
    let rel = w.relation(from, to);
    if rel < relation_floor() {
        return Some(Reason::Distrust);
    }
    for l in take {
        if let Leg::Commodity { c, per_month } = l {
            let s = surplus_with(w, h, draws, to, *c);
            if *per_month > s && s <= 0.0 {
                return Some(Reason::NoSurplus);
            }
        }
    }
    for (ceder, legs) in [(from, give), (to, take)] {
        for d in district_legs(legs) {
            if district_contested(w, d) {
                return Some(Reason::LandContested);
            }
            if pop_share_of(w, ceder, d) > NOT_FOR_SALE_POP {
                return Some(Reason::NotForSale);
            }
            if ceder == to && rel < LAND_TRUST {
                return Some(Reason::LandDistrust);
            }
            if w.nation_opt(ceder).map_or(0.0, |n| n.stability) < GOVERNMENT_FLOOR {
                return Some(Reason::GovernmentWouldFall);
            }
            if holdings(w, ceder) <= 1 {
                return Some(Reason::LastDistrict);
            }
        }
    }
    None
}

/// `evaluate` against a given draw source (see `Draws`).
fn evaluate_with(
    w: &WorldState,
    draws: &Draws,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    months: u32,
) -> Verdict {
    let h = have(w);
    let h: &Have = &h;
    if let Some(r) = hard_bars(w, h, draws, from, to, give, take) {
        return Verdict::Refuse(r);
    }
    // --- Value.
    let years = (months as f64 / 12.0).max(1.0 / 12.0);
    let (value_in, cost_out, _) = value_of(w, h, draws, from, to, give, take, years);
    if value_in + DOLLAR >= (1.0 + MARGIN) * cost_out {
        return Verdict::Accept;
    }
    // --- Counter: keep every leg, clip what the receiver gives to its
    // surplus, and name the money that makes the clipped bundle worth it.
    let clipped: Vec<Leg> = take
        .iter()
        .map(|l| match l {
            Leg::Commodity { c, per_month } => {
                Leg::Commodity { c: *c, per_month: per_month.min(surplus_with(w, h, draws, to, *c).max(0.0)) }
            }
            other => other.clone(),
        })
        .collect();
    let (value_in, cost_out, money_in) = value_of(w, h, draws, from, to, give, &clipped, years);
    let nonmoney_in = value_in - money_in * years;
    let want = ceil10(((1.0 + MARGIN) * cost_out - nonmoney_in) / years);
    if want <= money_in + DOLLAR {
        // The clip alone did it: the same money, the receiver's own legs.
        return Verdict::Counter { money_bn_per_year: money_in, take: clipped };
    }
    if want > cap(w, from) + DOLLAR {
        return Verdict::Refuse(Reason::NotForThatPrice { bn_per_year: want });
    }
    Verdict::Counter { money_bn_per_year: want, take: clipped }
}

/// Why the world refuses a bundle outright (spec section 4.3): the shape,
/// the term, the lines, the land, the proposer's spending cap, and then the
/// receiver's hard bars — each with its sentence. Pure, so `world_refusal`
/// can ask it before anything is priced and a refused ask costs nothing. A
/// counter is NOT a refusal here: `dispatch` returns it as the error so the
/// player reads the price, and `apply_command` charges only on `Ok`.
pub fn deal_refusal(
    w: &WorldState,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    months: u32,
) -> Option<String> {
    validate_bundle(w, from, to, give, take, months, contractable)
}

/// `deal_refusal` with the line predicate injected, so the untracked arm can
/// be exercised while every line in the table is tracked.
fn validate_bundle(
    w: &WorldState,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    months: u32,
    contractable: impl Fn(Commodity) -> bool,
) -> Option<String> {
    if from == to {
        return Some("A nation cannot trade with itself.".into());
    }
    let alive = |id: NationId| w.nation_opt(id).is_some_and(|n| n.alive);
    if !alive(from) || !alive(to) {
        return Some("Nation no longer exists.".into());
    }
    let legs = give.len() + take.len();
    let land = district_legs(give).count() + district_legs(take).count();
    if legs > MAX_LEGS || land > 1 {
        return Some("At most four legs, one of them land.".into());
    }
    for l in give.iter().chain(take) {
        if let Leg::Commodity { c, .. } = l {
            if !contractable(*c) {
                return Some(untracked_leg_sentence(*c));
            }
        }
    }
    if !TERMS.contains(&months) {
        return Some("Terms run 12, 36, 60 or 120 months.".into());
    }
    let money = |legs: &[Leg]| legs.iter().any(|l| matches!(l, Leg::Money { .. }));
    let hollow = legs == 0
        || (money(give) && money(take))
        || give.iter().chain(take).any(|l| match l {
            Leg::Commodity { per_month, .. } => !(per_month.is_finite() && *per_month > 0.0),
            Leg::Money { bn_per_year } => !(bn_per_year.is_finite() && *bn_per_year >= 0.0),
            Leg::District { id } => id.is_empty(),
        });
    if hollow {
        return Some("A leg must carry something.".into());
    }
    for (ceder, legs) in [(from, give), (to, take)] {
        for d in district_legs(legs) {
            if w.districts.get(d) != Some(&ceder) {
                return Some(format!("{} does not hold {}.", ceder.name(), d));
            }
        }
    }
    let gdp = w.nation(from).gdp;
    if contracted_spend(w, from) + money_of(w, give) > MAX_CONTRACT_SPEND * gdp + DOLLAR {
        return Some(format!("That would put {}'s contracted spending over 1% of output.", from.name()));
    }
    match evaluate(w, from, to, give, take, months) {
        Verdict::Refuse(r) => Some(r.sentence()),
        _ => None,
    }
}

/// The signing sentence's summary: the side with the goods sends.
fn summary(from: NationId, to: NationId, give: &[Leg], take: &[Leg], months: u32) -> String {
    let words = |legs: &[Leg]| -> String {
        if legs.is_empty() {
            "nothing".to_string()
        } else {
            legs.iter().map(Leg::describe).collect::<Vec<_>>().join(", ")
        }
    };
    let goods = |legs: &[Leg]| legs.iter().any(|l| !matches!(l, Leg::Money { .. }));
    if goods(give) || !goods(take) {
        format!("{} sends {} {} for {}, {} months", from.name(), to.name(), words(give), words(take), months)
    } else {
        format!("{} sends {} {} for {}, {} months", to.name(), from.name(), words(take), words(give), months)
    }
}

/// Sign (spec section 4.5). Land moves now, by consent, through the one
/// transfer function; the contract is pushed in creation order; +5 relation;
/// the headline. `w.rng` untouched. Returns the contract's id.
pub(crate) fn sign(
    w: &mut WorldState,
    from: NationId,
    to: NationId,
    give: &[Leg],
    take: &[Leg],
    months: u32,
) -> Result<u32, String> {
    for (ceder, receiver, legs) in [(from, to, give), (to, from, take)] {
        let land: Vec<String> = district_legs(legs).map(str::to_string).collect();
        for d in land {
            crate::districts::transfer_district(w, ceder, receiver, &d)?;
        }
    }
    w.resources.next_id += 1;
    let id = w.resources.next_id;
    let since = month_abs(w);
    w.resources.contracts.push(Contract {
        id,
        from,
        to,
        give: give.to_vec(),
        take: take.to_vec(),
        months_left: months,
        months_total: months,
        since,
        depth: 0.0,
    });
    w.shift_relation(from, to, SIGN_RELATION);
    w.headline(format!(
        "{} and {} sign a supply contract: {}.",
        from.name(),
        to.name(),
        summary(from, to, give, take, months)
    ));
    Ok(id)
}

/// `AcceptDeal`: the offer must exist and be addressed to `nation`; it is
/// signed at its own terms (evaluated from the AI's side when it was made,
/// so the AI accepts by construction), removed, and any refusal the buyer
/// remembered of this seller on the lines it now gets is forgotten.
pub(crate) fn accept_offer(w: &mut WorldState, nation: NationId, offer: u32) -> Result<(), String> {
    let pos = w
        .resources
        .offers
        .iter()
        .position(|o| o.id == offer && o.to == nation)
        .ok_or("No such offer.")?;
    let o = w.resources.offers[pos].clone();
    sign(w, o.from, o.to, &o.give, &o.take, o.months)?;
    w.resources.offers.remove(pos);
    let sold: Vec<Commodity> = o
        .take
        .iter()
        .filter_map(|l| match l {
            Leg::Commodity { c, .. } => Some(*c),
            _ => None,
        })
        .collect();
    w.resources
        .refusals
        .retain(|r| !(r.buyer == o.from && r.seller == nation && sold.contains(&r.c)));
    Ok(())
}

/// `DeclineDeal`: the offer is removed and nothing else happens. Free, and
/// no memory: the player said no once, which is what an AI seller's "no" is.
pub(crate) fn decline_offer(w: &mut WorldState, nation: NationId, offer: u32) -> Result<(), String> {
    let pos = w
        .resources
        .offers
        .iter()
        .position(|o| o.id == offer && o.to == nation)
        .ok_or("No such offer.")?;
    w.resources.offers.remove(pos);
    Ok(())
}

/// `CancelDeal`: never refused beyond existence. The contract goes; the
/// breaker pays `abrogate_trade`'s reputation and relation, and the other
/// side remembers for three years.
pub(crate) fn cancel_contract(w: &mut WorldState, nation: NationId, contract: u32) -> Result<(), String> {
    let pos = w
        .resources
        .contracts
        .iter()
        .position(|k| k.id == contract && (k.from == nation || k.to == nation))
        .ok_or("No such contract.")?;
    let k = w.resources.contracts.remove(pos);
    let other = k.other(nation);
    w.shift_reputation(nation, CANCEL_REPUTATION);
    w.shift_relation(nation, other, CANCEL_RELATION);
    let until = month_abs(w) + GRIEVANCE_MONTHS;
    match w.resources.grievances.iter_mut().find(|g| g.victim == other && g.breaker == nation) {
        Some(g) => g.until = g.until.max(until),
        None => w.resources.grievances.push(Grievance { victim: other, breaker: nation, until }),
    }
    w.headline(format!("{} tears up its supply contract with {}.", nation.name(), other.name()));
    Ok(())
}

/// A contract is leverage (spec section 4.7): over every line, the
/// depth-weighted share of `id`'s sourcing of that line that comes from
/// `partner` under contract — `Σ depth × in_from_partner / (own/12 + in_all)`
/// — and the largest such share is the dependency. `WorldState::
/// trade_dependency` returns the larger of this and the pact form, so
/// commitment.rs and theatre.rs feel a contract for free. Free while there
/// are no contracts, which is every world the suite runs.
pub fn contract_dependency(w: &WorldState, id: NationId, partner: NationId) -> f64 {
    if w.resources.contracts.is_empty() {
        return 0.0;
    }
    let h = have(w);
    let h: &Have = &h;
    let mut best: f64 = 0.0;
    for c in ALL {
        if c == Commodity::Oil {
            continue;
        }
        let (mut from_partner, mut all) = (0.0, 0.0);
        for k in &w.resources.contracts {
            let (giver, legs) = if k.to == id {
                (k.from, &k.give)
            } else if k.from == id {
                (k.to, &k.take)
            } else {
                continue;
            };
            let promised: f64 = commodity_legs(legs).filter(|(lc, _)| *lc == c).map(|(_, p)| p).sum();
            if promised <= 0.0 {
                continue;
            }
            let q = promised * delivery_ratio_with(w, h, giver, c);
            all += q;
            if giver == partner {
                from_partner += k.depth * q;
            }
        }
        if from_partner <= 0.0 {
            continue;
        }
        let total = (flow_of(h, id, c) / 12.0 + all).max(1e-9);
        best = best.max(from_partner / total);
    }
    best
}

// ---------------------------------------------------------------------------
// Surface queries (package W1): what the web serves. Every one is a pure read
// over `&WorldState` and the static table; nothing here is written by the
// tick and nothing here writes the world. `warm` is the one exception and it
// writes only the derived cache, which is never serialized and never hashed.
// ---------------------------------------------------------------------------

/// A refusal counts toward "everyone refused" while its heat is at least
/// this (M, Appendix A): a refusal counts for one year. S3 writes the rows;
/// declared here so the surface and the last-resort predicate read one bar.
pub const GATE_HEAT: f64 = 0.5;

/// Build the derived HAVE cache if it is unbuilt or stale, exactly as the
/// first half of `tick` does, and refresh the oil column otherwise. The web
/// calls this when it seats a world and after a command, so the board reads
/// the ledger before the first tick and after a land sale in the same month
/// — the tick would build the identical cache and, finding the epoch equal,
/// build nothing. `resource_have` is `#[serde(skip)]`: no save byte, no hash
/// bit, no RNG word moves.
pub fn warm(w: &mut WorldState) {
    let stamp = alive_stamp(w);
    let stale = !w.resource_have.built
        || w.resource_have.epoch != w.districts_epoch
        || w.resource_have.alive_stamp != stamp;
    if stale {
        w.resource_have = have_table(w);
    } else {
        for n in w.nations.iter().filter(|n| n.alive) {
            w.resource_have.flow[n.id.index()][OIL] = n.oil_mbd * 1000.0;
        }
    }
}

/// Spec section 6.4: `Some((refused, sellers))` iff every living producer of
/// `k` other than `a` carries `Refusal(a, s, k)` with heat at least
/// `GATE_HEAT` and at least two asks, and none of them is shut out by `a`'s
/// own sanction; `None` when there are no producers, or any has not refused
/// twice. Pure; reads a memory that is empty until S3 writes it.
pub fn refused_all(w: &WorldState, a: NationId, k: Commodity) -> Option<(usize, usize)> {
    let sellers: Vec<NationId> = producers(w, k).into_iter().filter(|s| *s != a).collect();
    if sellers.is_empty() {
        return None;
    }
    if sellers.iter().any(|s| w.is_sanctioning(a, *s)) {
        return None;
    }
    let refused = sellers.iter().filter(|s| refusal_counted(w, a, **s, k)).count();
    if refused == sellers.len() {
        Some((refused, sellers.len()))
    } else {
        None
    }
}

/// Whether `a` remembers `s` refusing it `k` recently enough and often enough
/// to count (heat at least `GATE_HEAT`, at least two asks).
pub fn refusal_counted(w: &WorldState, a: NationId, s: NationId, k: Commodity) -> bool {
    refusal_of(w, a, s, k).is_some_and(|r| r.is_refusal() && r.heat >= GATE_HEAT && r.asks >= 2)
}

/// How many sellers of `k` have refused `a` at all (any live refusal row),
/// for the card's "N asked". A priced-out row is not one.
pub fn refusals_of(w: &WorldState, a: NationId, k: Commodity) -> usize {
    w.resources.refusals.iter().filter(|r| r.buyer == a && r.c == k && r.is_refusal() && r.heat > 0.0).count()
}

/// The equipment class as the card says it.
pub fn class_word(c: Class) -> &'static str {
    match c {
        Class::Naval => "naval",
        Class::Armour => "armour",
        Class::Air => "air",
        Class::Missile => "missile",
        Class::Space => "space",
        Class::Infantry => "infantry",
    }
}

/// The kit `id`'s procurement would order this month — the one whose need
/// `draw` sizes — as (designation, class word). `None` when nothing is
/// orderable.
pub fn needed_by(w: &WorldState, id: NationId) -> Option<(&'static str, &'static str)> {
    let n = w.nation_opt(id)?;
    let kit = crate::arsenal::pick(n)?;
    let def = DECK.get(kit as usize)?;
    Some((def.name, class_word(def.class)))
}

/// Where a nation's flow of one line sits: how many located districts it
/// holds that carry the line, the annual output those districts locate, and
/// the annual output nothing locates (an unlocated producer's whole figure;
/// for oil, the ledger less what the held districts locate).
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Holdings {
    pub districts: usize,
    /// Annual, the table's units.
    pub located: f64,
    /// Annual, the table's units.
    pub unlocated: f64,
}

pub fn holdings_of(w: &WorldState, id: NationId, c: Commodity) -> Holdings {
    let t = tables();
    let ci = c.idx();
    let mut out = Holdings::default();
    for r in &t.district_rows {
        if r.c != ci || w.districts.get(&r.district) != Some(&id) {
            continue;
        }
        out.districts += 1;
        out.located += r.share * t.production[r.owner_1990.index()][ci];
    }
    out.unlocated = if c == Commodity::Oil {
        (flow(w, id, c) - out.located).max(0.0)
    } else if t.unlocated.get(id.index()).is_some_and(|u| u[ci]) {
        t.production[id.index()][ci]
    } else {
        0.0
    };
    out
}

/// The presence rank word (spec section 2.2's `quality`): never a tonnage.
pub fn quality_word(q: u8) -> &'static str {
    match q {
        3 => "strong",
        2 => "moderate",
        1 => "sparse",
        _ => "absent",
    }
}

/// A district's presence rank for `c`, 0 when absent.
pub fn quality_of(d: &str, c: Commodity) -> u8 {
    tables().file.quality.get(d).map_or(0, |q| q[c.idx()])
}

/// The lines a district carries at any band or level, in `ALL` order.
pub fn presence_of(d: &str) -> Vec<Commodity> {
    let mask = tables().file.presence.get(d).copied().unwrap_or(0);
    ALL.iter().copied().filter(|c| mask & c.bit() != 0).collect()
}

/// Could `a` put an army on `d` (spec section 1.14, clause 5)? Adjacent to
/// ground `a` holds; or `a` has region or claim reach on the holder and `d`
/// is peripheral by front.rs's entry rule — no land neighbour at all, or one
/// not held by the holder.
pub fn reachable(w: &WorldState, a: NationId, d: &str) -> bool {
    let Some(&holder) = w.districts.get(d) else { return false };
    let adj = crate::districts::adj_of(d);
    if adj.iter().any(|n| w.districts.get(n.as_str()) == Some(&a)) {
        return true;
    }
    if crate::dyads::reach(a, holder) <= 0.0 {
        return false;
    }
    adj.is_empty() || adj.iter().any(|n| w.districts.get(n.as_str()) != Some(&holder))
}

/// `holder`'s best-sourced located district of `c` that `a` can reach:
/// presence rank desc, ties by id asc. `None` when it holds none in reach.
pub fn reachable_best_district(w: &WorldState, a: NationId, holder: NationId, c: Commodity) -> Option<(String, u8)> {
    let t = tables();
    let ci = c.idx();
    let mut best: Option<(u8, &str)> = None;
    for r in &t.district_rows {
        if r.c != ci || w.districts.get(&r.district) != Some(&holder) {
            continue;
        }
        let q = quality_of(&r.district, c);
        let better = match best {
            None => true,
            Some((bq, bd)) => q > bq || (q == bq && r.district.as_str() < bd),
        };
        if better && reachable(w, a, &r.district) {
            best = Some((q, r.district.as_str()));
        }
    }
    best.map(|(q, d)| (d.to_string(), q))
}

/// The TAKE card's target: the nearest reachable holder of `c` and its
/// best-sourced district. Sellers that have refused `a` twice rank first
/// (the mine that refused you), then neighbours over the region, then
/// presence rank, then `NationId` order — a total order, so two reads agree.
pub fn take_target(w: &WorldState, a: NationId, c: Commodity) -> Option<(NationId, String, u8)> {
    let mut best: Option<(u8, u8, u8, NationId, String)> = None;
    for t in producers(w, c) {
        if t == a {
            continue;
        }
        let Some((d, q)) = reachable_best_district(w, a, t, c) else { continue };
        let refused = if refusal_counted(w, a, t, c) { 0 } else { 1 };
        let far = if crate::nations::adjacent(a, t) { 0 } else { 1 };
        let key = (refused, far, 3 - q.min(3), t, d);
        if best.as_ref().map_or(true, |b| key < *b) {
            best = Some(key);
        }
    }
    best.map(|(_, _, _, t, d)| {
        let q = quality_of(&d, c);
        (t, d, q)
    })
}

/// REFERENCE_MINE (D, Appendix A): the median 1990 output per located
/// district across every producer of `c`, annual, the table's units — the
/// one figure the MINE card labels "a typical mine". Computed from the table
/// once; `None` for a line nobody locates.
pub fn reference_mine(c: Commodity) -> Option<f64> {
    static M: OnceLock<[Option<f64>; 12]> = OnceLock::new();
    M.get_or_init(|| {
        let t = tables();
        let mut out = [None; 12];
        for ci in 0..12 {
            let mut v: Vec<f64> = t
                .district_rows
                .iter()
                .filter(|r| r.c == ci)
                .map(|r| r.share * t.production[r.owner_1990.index()][ci])
                .filter(|q| *q > 0.0)
                .collect();
            if v.is_empty() {
                continue;
            }
            v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let n = v.len();
            out[ci] = Some(if n % 2 == 1 { v[n / 2] } else { (v[n / 2 - 1] + v[n / 2]) / 2.0 });
        }
        out
    })[c.idx()]
}

pub fn mine_output(district: &str, c: Commodity) -> Option<f64> {
    let scale = match quality_of(district, c) {
        3 => 1.5,
        2 => 1.0,
        1 => 0.5,
        _ => return None,
    };
    reference_mine(c).map(|reference| reference * scale)
}

pub fn mine_output_bn_per_year(w: &WorldState, district: &str, c: Commodity) -> Option<f64> {
    let output = mine_output(district, c)?;
    Some(if c == Commodity::Oil {
        oil_leg_bn_per_year(output, w.oil_price)
    } else {
        output * unit_price_bn(c)?
    })
}

pub fn mine_cost_bn(w: &WorldState, district: &str, c: Commodity) -> Option<f64> {
    mine_output_bn_per_year(w, district, c)
        .map(|value| (value * MINE_COST_YEARS).clamp(MINE_COST_FLOOR_BN, MINE_COST_CAP_BN))
}

pub fn mine_project_at<'a>(w: &'a WorldState, district: &str, c: Commodity) -> Option<&'a MineProject> {
    w.resources
        .mine_projects
        .binary_search_by(|m| (m.district.as_str(), m.commodity).cmp(&(district, c)))
        .ok()
        .map(|i| &w.resources.mine_projects[i])
}

pub fn mine_at<'a>(w: &'a WorldState, district: &str, c: Commodity) -> Option<&'a Mine> {
    w.resources
        .mines
        .binary_search_by(|m| (m.district.as_str(), m.commodity).cmp(&(district, c)))
        .ok()
        .map(|i| &w.resources.mines[i])
}

pub fn mine_refusal(
    w: &WorldState,
    nation: NationId,
    district: &str,
    c: Commodity,
) -> Option<String> {
    if !w.rules.resource_gates {
        return Some("The resource system is not enabled for this world.".into());
    }
    if !w.nation_opt(nation).is_some_and(|n| n.alive) {
        return Some(format!("{} is not an active state.", nation.name()));
    }
    let Some(&owner) = w.districts.get(district) else {
        return Some(format!("There is no district called {}.", district));
    };
    if owner != nation {
        return Some(format!(
            "{} does not control {}.",
            nation.name(),
            crate::districts::name_of(district).unwrap_or(district)
        ));
    }
    if quality_of(district, c) == 0 {
        return Some(format!(
            "No mapped {} deposit is present in {}.",
            c.name(),
            crate::districts::name_of(district).unwrap_or(district)
        ));
    }
    if district_contested(w, district) {
        return Some("Construction cannot begin while that district is contested.".into());
    }
    if mine_at(w, district, c).is_some() {
        return Some(format!("The {} development there is already online.", c.name()));
    }
    if mine_project_at(w, district, c).is_some() {
        return Some(format!("The {} development there is already under construction.", c.name()));
    }
    if mine_cost_bn(w, district, c).is_none() {
        return Some(format!("There is no defensible production benchmark for {}.", c.name()));
    }
    None
}

pub fn start_mine(
    w: &mut WorldState,
    nation: NationId,
    district: &str,
    c: Commodity,
) -> Result<(), String> {
    if let Some(why) = mine_refusal(w, nation, district, c) {
        return Err(why);
    }
    let investment_bn = mine_cost_bn(w, district, c).expect("precondition checked");
    let output = mine_output(district, c).expect("precondition checked");
    let gdp = w.nation(nation).gdp.max(0.1);
    w.nation_mut(nation).debt_gdp += investment_bn / gdp;
    let project = MineProject {
        district: district.to_string(),
        commodity: c,
        started_by: nation,
        months_left: MINE_BUILD_MONTHS,
        months_total: MINE_BUILD_MONTHS,
        investment_bn,
        output,
    };
    let key = (project.district.as_str(), project.commodity);
    let i = w
        .resources
        .mine_projects
        .binary_search_by(|m| (m.district.as_str(), m.commodity).cmp(&key))
        .unwrap_err();
    w.resources.mine_projects.insert(i, project);
    let verb = if matches!(c, Commodity::Oil | Commodity::Gas) {
        "field development"
    } else {
        "mine"
    };
    let district_name = crate::districts::name_of(district).unwrap_or(district);
    w.headline(format!(
        "{} commits ${:.1} bn to a {} {} in {}; first output in {} months.",
        nation.name(), investment_bn, c.name(), verb, district_name, MINE_BUILD_MONTHS
    ));
    Ok(())
}

// ---------------------------------------------------------------------------
// The market (package S3): the buy pass, the refusal memory, the aim. Behind
// `GameRules::resource_market` (fork F1(b)): the pass returns before it reads
// anything while the switch is off, the memory is written by nothing else, and
// the switch is off in every test and in the headless CLI — so the goldens and
// the headless bytes are the world before this section existed.
// ---------------------------------------------------------------------------

/// The lattice a refusal cools on: twenty-fourths. Cooling snaps to it (see
/// `cool_refusals`) so six coolings from one land on exactly `REASK_HEAT`
/// and twelve on exactly `GATE_HEAT` — a float subtracted twenty-four times
/// lands a hair above both and would make every wait a month long.
pub const HEAT_STEPS: f64 = 24.0;

/// A refusal cools by this much a month (M, Appendix A): forgotten in two
/// years, always staler than the grievance that caused it.
pub const REFUSAL_COOL: f64 = 1.0 / HEAT_STEPS;

/// One number for three waits (M, Appendix A): the re-ask cadence, an
/// offer's life in the player's inbox, and the AI's patience before a lapse
/// counts as a no.
pub const PATIENCE: i32 = 6;

/// A buyer asks a seller again once its refusal has cooled to this: six
/// months of `REFUSAL_COOL` off a fresh refusal, `18/24`, exact.
pub const REASK_HEAT: f64 = (HEAT_STEPS - PATIENCE as f64) / HEAT_STEPS;

/// The term the AI asks for (M): the middle rung of `TERMS`, three years.
pub const AI_TERM: u32 = 36;

/// A player holds at most this many unanswered offers (M): an inbox, not a
/// queue. A fourth is not asked this month.
pub const MAX_PENDING_OFFERS: usize = 3;

/// The relation floor as the code reads it: the constant, except on the
/// census thread of a test build, which sweeps it (fork F2).
#[cfg(not(test))]
pub(crate) fn relation_floor() -> f64 {
    RELATION_FLOOR
}
#[cfg(test)]
pub(crate) fn relation_floor() -> f64 {
    census::FLOOR.with(|f| f.get())
}

/// Whether the sanction ration is applied: always, except on the census
/// thread of a test build, which sweeps it off (fork F2).
#[cfg(not(test))]
fn ration_on() -> bool {
    true
}
#[cfg(test)]
fn ration_on() -> bool {
    census::RATION.with(|r| r.get())
}

/// Fork F2's two knobs, thread-local so the census (one thread) can sweep
/// them while every other test reads the design values. Test builds only;
/// the shipped binary reads the constants.
#[cfg(test)]
pub(crate) mod census {
    use std::cell::Cell;
    thread_local! {
        pub static FLOOR: Cell<f64> = const { Cell::new(super::RELATION_FLOOR) };
        pub static RATION: Cell<bool> = const { Cell::new(true) };
    }
}

fn refusal_slot(w: &WorldState, buyer: NationId, seller: NationId, c: Commodity) -> Result<usize, usize> {
    w.resources.refusals.binary_search_by(|r| (r.buyer, r.seller, r.c).cmp(&(buyer, seller, c)))
}

/// The row `buyer` keeps on `seller` for `c`, if any.
pub fn refusal_of(w: &WorldState, buyer: NationId, seller: NationId, c: Commodity) -> Option<&Refusal> {
    refusal_slot(w, buyer, seller, c).ok().map(|i| &w.resources.refusals[i])
}

/// The memory's one writer besides cooling (spec section 6.2): heat back to
/// one, asks up one, the reason the latest. Returns the asks now on the
/// row. Sorted by (buyer, seller, line) by construction.
pub(crate) fn remember_refusal(
    w: &mut WorldState,
    buyer: NationId,
    seller: NationId,
    c: Commodity,
    reason: Reason,
) -> u32 {
    match refusal_slot(w, buyer, seller, c) {
        Ok(i) => {
            let r = &mut w.resources.refusals[i];
            r.heat = 1.0;
            r.asks += 1;
            r.reason = reason;
            r.asks
        }
        Err(i) => {
            w.resources.refusals.insert(i, Refusal { buyer, seller, c, reason, heat: 1.0, asks: 1 });
            1
        }
    }
}

/// A signing forgets the refusal it answers.
pub(crate) fn forget_refusal(w: &mut WorldState, buyer: NationId, seller: NationId, c: Commodity) {
    if let Ok(i) = refusal_slot(w, buyer, seller, c) {
        w.resources.refusals.remove(i);
    }
}

/// Spec section 6.3, from `statecraft::tick`: every row cools one step on
/// the lattice of twenty-fourths, and a row at zero is gone — a world that
/// has forgotten serializes as one that never knew. Nothing else reads or
/// writes the memory: no relation, no growth, no reputation.
pub fn cool_refusals(w: &mut WorldState) {
    if w.resources.refusals.is_empty() {
        return;
    }
    for r in w.resources.refusals.iter_mut() {
        r.heat = ((r.heat * HEAT_STEPS).round() - 1.0) / HEAT_STEPS;
    }
    w.resources.refusals.retain(|r| r.heat > 0.0);
}

/// What one ask came to.
#[derive(Clone, Debug, PartialEq)]
pub(crate) enum Asked {
    /// A contract at the seller's own price.
    Signed,
    /// The seller is the player: an offer in its inbox.
    Offered,
    /// The seller's price is past what the buyer may spend. Not a refusal:
    /// never counted, never headlined; remembered only as the clock that
    /// says when to ask again.
    PricedOut { bn_per_year: f64 },
    /// A hard bar, with its reason — remembered.
    Refused(Reason),
    /// Not asked after all: the buyer had not the standing, or the player's
    /// inbox is full or already holds this ask.
    NotAsked,
}

/// One ask (spec section 6.2): `b` puts `short` of `c` a month to `s` with
/// a placeholder for money and takes the seller's own answer — accepted as
/// is, or countered at the seller's price with the seller's clipped legs,
/// which re-offered is accepted by construction. A seller that is the
/// player gets an offer in its inbox instead of a signature. No RNG.
///
/// Three things are not computed because their answer is already known: a
/// buyer without the standing to sign is not asked (the command would only
/// say so); the value stage is skipped for a buyer whose cap is under the
/// price step (every counter would be `NotForThatPrice`); and each seller's
/// draw is read from `memo`, the month's, rather than picked again.
pub(crate) fn ask(
    w: &mut WorldState,
    b: NationId,
    s: NationId,
    c: Commodity,
    short: f64,
    capped: bool,
    memo: &mut BTreeMap<NationId, [f64; 12]>,
) -> Asked {
    let give = vec![Leg::Money { bn_per_year: 0.0 }];
    let take = vec![Leg::Commodity { c, per_month: short }];
    let to_player = Some(s) == w.player;
    let probe = crate::Command::ProposeDeal { from: b, to: s, give: give.clone(), take: take.clone(), months: AI_TERM };
    if !to_player && !crate::affordable(w, &probe) {
        return Asked::NotAsked;
    }
    let verdict = {
        let wr: &WorldState = w;
        let cell = std::cell::RefCell::new(std::mem::take(memo));
        let draws = |id: NationId| *cell.borrow_mut().entry(id).or_insert_with(|| draw(wr, id));
        let h = have(wr);
        let h: &Have = &h;
        let v = match hard_bars(wr, h, &draws, b, s, &give, &take) {
            Some(r) => Verdict::Refuse(r),
            None if capped => Verdict::Refuse(Reason::NotForThatPrice { bn_per_year: PRICE_STEP }),
            None => evaluate_with(wr, &draws, b, s, &give, &take, AI_TERM),
        };
        *memo = cell.into_inner();
        v
    };
    let (money, take) = match verdict {
        Verdict::Accept => (0.0, take),
        Verdict::Counter { money_bn_per_year, take } => (money_bn_per_year, take),
        Verdict::Refuse(Reason::NotForThatPrice { bn_per_year }) => return Asked::PricedOut { bn_per_year },
        Verdict::Refuse(r) => return Asked::Refused(r),
    };
    let give = vec![Leg::Money { bn_per_year: money }];
    if Some(s) == w.player {
        let pending = w.resources.offers.iter().filter(|o| o.to == s).count();
        if pending >= MAX_PENDING_OFFERS {
            return Asked::NotAsked;
        }
        let same = |l: &Leg| matches!(l, Leg::Commodity { c: lc, .. } if *lc == c);
        if w.resources.offers.iter().any(|o| o.from == b && o.to == s && o.take.iter().any(same)) {
            return Asked::NotAsked;
        }
        w.resources.next_id += 1;
        let id = w.resources.next_id;
        let expires = month_abs(w) + PATIENCE;
        w.resources.offers.push(Offer { id, from: b, to: s, give, take, months: AI_TERM, expires });
        return Asked::Offered;
    }
    match crate::apply_command(w, &crate::Command::ProposeDeal { from: b, to: s, give, take, months: AI_TERM }) {
        Ok(()) => Asked::Signed,
        Err(_) => Asked::NotAsked,
    }
}

/// The buy pass (ruling 4's "must first attempt to buy"; spec sections 1.12
/// and 6.2), the first thing `politics::ai_statecraft` does. For every AI
/// state with a cover row — the gate materialises one on the first month a
/// line is short, so an open world has none and the pass costs one emptiness
/// check — for every tracked line its procurement wants more of than it can
/// get this month, in `NationId` order over every living producer: a seller
/// the buyer itself embargoes is blocked, not asked; a seller whose refusal
/// has not cooled to `REASK_HEAT` is not asked yet; otherwise one `ask`. A
/// signing forgets the refusal and ends the search for that line; a hard
/// refusal is remembered and headlined the first time; a priced-out ask is
/// neither. The month every producer stands refused twice is headlined
/// once, and again only after the memory has cooled and been refreshed.
/// Deterministic: sorted rows, registry order, no RNG.
#[cfg(not(test))]
pub fn ai_purchases(w: &mut WorldState) {
    buy_pass(w)
}
/// In a test build the pass is timed in place, two clock reads a month, so
/// `the_resource_pass_stays_under_budget` reads its cost inside the tick it
/// actually runs in rather than a copy run beside it.
#[cfg(test)]
pub fn ai_purchases(w: &mut WorldState) {
    meter::timed(&meter::BUY, || buy_pass(w))
}

/// The in-situ clock for the buy pass (test builds only).
#[cfg(test)]
pub(crate) mod meter {
    use std::cell::Cell;
    use std::time::{Duration, Instant};
    thread_local! {
        pub static BUY: Cell<Duration> = const { Cell::new(Duration::ZERO) };
        /// Asks by outcome: signed, offered, priced out, refused, not asked.
        pub static ASKS: Cell<[u32; 5]> = const { Cell::new([0; 5]) };
    }
    pub fn count(outcome: &super::Asked) {
        let i = match outcome {
            super::Asked::Signed => 0,
            super::Asked::Offered => 1,
            super::Asked::PricedOut { .. } => 2,
            super::Asked::Refused(_) => 3,
            super::Asked::NotAsked => 4,
        };
        ASKS.with(|a| {
            let mut v = a.get();
            v[i] += 1;
            a.set(v);
        });
    }
    pub fn timed<T>(slot: &'static std::thread::LocalKey<Cell<Duration>>, f: impl FnOnce() -> T) -> T {
        let t = Instant::now();
        let out = f();
        slot.with(|s| s.set(s.get() + t.elapsed()));
        out
    }
}

fn buy_pass(w: &mut WorldState) {
    if !(w.rules.resource_gates && w.rules.resource_market) || w.resources.cover.is_empty() {
        return;
    }
    let player = w.player;
    let buyers: Vec<NationId> = w.resources.cover.iter().map(|r| r.nation).collect();
    let mut memo: BTreeMap<NationId, [f64; 12]> = BTreeMap::new();
    for b in buyers {
        if Some(b) == player || !w.nation_opt(b).is_some_and(|n| n.alive) {
            continue;
        }
        let (kit, line) = {
            let n = w.nation(b);
            (crate::arsenal::pick(n), crate::arsenal::line_of(n))
        };
        let Some(kit) = kit else { continue };
        let need = kit_need(kit, line);
        memo.insert(b, need);
        for c in ALL.iter().copied().filter(|c| c.tracked() && need[c.idx()] > 0.0) {
            let s = supply(w, b, c, need[c.idx()]);
            if s.available >= need[c.idx()] {
                continue;
            }
            let short = need[c.idx()] - s.available;
            let sellers: Vec<NationId> = producers(w, c).into_iter().filter(|s| *s != b).collect();
            if sellers.is_empty() {
                continue;
            }
            let before = refused_all(w, b, c).is_some();
            // Constant across the sellers of one line: a signing ends the
            // line's search, and nothing else here moves the cap.
            let capped = cap(w, b) + DOLLAR < PRICE_STEP;
            for s in sellers {
                if w.is_sanctioning(b, s) {
                    continue;
                }
                if refusal_of(w, b, s, c).is_some_and(|r| r.heat > REASK_HEAT) {
                    continue;
                }
                let outcome = ask(w, b, s, c, short, capped, &mut memo);
                #[cfg(test)]
                meter::count(&outcome);
                match outcome {
                    Asked::Signed => {
                        forget_refusal(w, b, s, c);
                        break;
                    }
                    Asked::PricedOut { bn_per_year } => {
                        // Not a refusal — a clock. Nothing counts it, nothing
                        // prints it; it only says when to ask again.
                        remember_refusal(w, b, s, c, Reason::NotForThatPrice { bn_per_year });
                    }
                    Asked::Refused(r) => {
                        let sentence = r.sentence();
                        if remember_refusal(w, b, s, c, r) == 1 {
                            w.headline(format!(
                                "{} seeks {} from {}; {} refuses: {}",
                                b.name(),
                                c.name(),
                                s.name(),
                                s.name(),
                                sentence
                            ));
                        }
                    }
                    Asked::Offered | Asked::NotAsked => {}
                }
            }
            if !before {
                if let Some((_, sellers)) = refused_all(w, b, c) {
                    w.headline(format!("Nobody will sell {} to {} — {} asked.", c.name(), b.name(), sellers));
                }
            }
        }
    }
}

/// Why the world refuses an aim (spec section 6.6), each with its sentence:
/// no such conflict; `nation` did not open it; no such district; the
/// district is not the primary opponent's; the district carries no presence
/// of the line. Pure, so `world_refusal` asks it before anything is priced.
pub fn aim_refusal(
    w: &WorldState,
    conflict: u32,
    nation: NationId,
    district: &str,
    commodity: Commodity,
) -> Option<String> {
    let Some(c) = w.conflict(conflict) else { return Some("No such conflict.".into()) };
    if c.origin_attacker != nation {
        return Some(format!("Only {}, who opened the quarrel, names what it is for.", c.origin_attacker.name()));
    }
    let Some(name) = crate::districts::name_of(district) else {
        return Some(format!("No district called {district}."));
    };
    let Some(opponent) = crate::commitment::primary_opponent(c, nation) else {
        return Some("Not a party to that conflict.".into());
    };
    if w.districts.get(district) != Some(&opponent) {
        return Some(format!("{} does not hold {}.", opponent.name(), name));
    }
    if !presence_of(district).contains(&commodity) {
        return Some(format!("{} holds no {}.", name, commodity.name()));
    }
    None
}

/// `SetAim`'s effect: the conflict's aim. `aim_refusal` has already
/// answered; nothing else moves, nothing is headlined — the invasion, if it
/// comes, says what it was for.
pub(crate) fn set_aim(w: &mut WorldState, conflict: u32, district: &str, commodity: Commodity) -> Result<(), String> {
    let c = w.conflict_mut(conflict).ok_or("No such conflict.")?;
    c.aim = Some(Aim { district: district.to_string(), commodity });
    Ok(())
}

/// The invasion headline of a war opened for a line (spec section 6.7):
/// `WAR: {a} invades {t} for the {k} of {d*} — refused by {r} of {s}
/// sellers.` — the counts from `refused_all` at that moment, or the rows
/// still warm if the memory has cooled beneath the bar. `None` unless the
/// conflict carries an aim and the attacker is the state that set it.
pub fn resource_war_headline(
    w: &WorldState,
    c: &crate::world::Conflict,
    attacker: NationId,
    defender: NationId,
) -> Option<String> {
    let aim = c.aim.as_ref()?;
    if attacker != c.origin_attacker {
        return None;
    }
    let k = aim.commodity;
    let (refused, sellers) = refused_all(w, attacker, k).unwrap_or_else(|| {
        let sellers = producers(w, k).into_iter().filter(|s| *s != attacker).count();
        (refusals_of(w, attacker, k), sellers)
    });
    let name = crate::districts::name_of(&aim.district).unwrap_or(aim.district.as_str());
    Some(format!(
        "WAR: {} invades {} for the {} of {} — refused by {} of {} sellers.",
        attacker.name(),
        defender.name(),
        k.name(),
        name,
        refused,
        sellers
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::init::world_1990;
    use crate::world::GameRules;

    /// D1's gate, from the sim's side: the committed table loads through both
    /// passes, and the facts the spec pins (section 2.4) hold on what loaded.
    /// Nothing here touches `WorldState`; the table is static and unhashed.
    #[test]
    fn the_1990_resource_table_loads_and_holds_its_invariants() {
        let t = tables();
        let f = &t.file;

        // The join: every key seated, exactly one key refused, and it is not a
        // start nation (Namibia is a roster seat that comes alive later).
        assert_eq!(f.meta.dropped_keys, DROPPED_KEYS);
        let namibia = NationId::from_code("Namibia").expect("Namibia is a roster seat");
        assert!(!start_nations().contains(&namibia), "Namibia must not be a start nation while it is dropped");
        for c in TRACKED {
            for code in f.national_1990[c].keys() {
                assert!(NationId::from_code(code).is_some(), "{code} does not resolve");
            }
        }
        // All twelve lines are tracked since D2, and the enum agrees with the file.
        assert_eq!(f.tracked.len(), 12);
        for c in ALL {
            assert!(c.tracked(), "{} is not tracked", c.key());
            assert_eq!(f.units[c.key()], c.unit());
            assert_eq!(Commodity::parse(c.key()), Some(c));
            assert_eq!(c.idx(), commodity_index(c.key()).unwrap());
        }

        // The transcribed figure, exact: the USSR's iron is DS-896's 236,000,000 t.
        let ussr = NationId::from_code("USSR").unwrap();
        assert_eq!(t.national["iron"][&ussr], 236_000_000.0);
        assert_eq!(f.national_1990["iron"]["USSR"].source, "ds896_iron");

        // SPEC 7.3's named assertion: THE USSR MUST HOLD URANIUM THROUGH THE
        // UNLOCATED-PRODUCER RULE. No Soviet district carries a uranium site
        // (a survey hole), so the 14,000 tU the Red Book prints stays with
        // the USSR while it lives, and would vanish if "located" were the
        // only way to hold a figure.
        assert_eq!(t.national["uranium"][&ussr], 14_000.0);
        assert!(!t.located["uranium"].contains_key(&ussr));
        assert!(t.unlocated[ussr.index()][Commodity::Uranium.idx()]);
        assert!(f.meta.counts.unlocated_producers["uranium"].iter().any(|n| n == "USSR"));
        assert!(f.national_1990["uranium"]["USSR"].flags.iter().any(|x| x.contains("Secretariat estimate")));

        // Every transcribed table reconciles to the total its source prints.
        for c in &f.meta.transcription.lines {
            let tb = &f.meta.transcription.tables[c];
            assert_eq!(tb.seated + tb.dropped + tb.unmapped + tb.zero, tb.printed_total_1990, "{c}");
        }

        // Shares: sum to one, every one at or above the floor, sorted.
        for c in TRACKED {
            for (code, list) in &f.located[c] {
                let sum: f64 = list.iter().map(|(_, s)| s).sum();
                assert!((sum - 1.0).abs() <= SHARE_SUM_TOLERANCE, "{c}/{code} sums to {sum}");
                assert!(list.iter().all(|(_, s)| *s >= LOCATED_MIN_SHARE), "{c}/{code} carries a pruned share");
            }
        }
        let ussr_iron = &t.located["iron"][&ussr];
        assert!(!ussr_iron.is_empty());
        assert!(ussr_iron.windows(2).all(|w| w[0].1 >= w[1].1));
        // The Soviet coalfield tail was pruned, not carried at 1e-6.
        assert!(f.meta.counts.pruned["coal"]["USSR"] > 0);
        assert!(f.located["coal"]["USSR"].iter().all(|(_, s)| *s >= LOCATED_MIN_SHARE));

        // The USA: an unlocated oil producer (its ledger is oil_mbd, and the
        // shares only say where it sits — nowhere, so nothing can be taken),
        // and no 1990 bauxite row at all.
        let usa = NationId::from_code("USA").unwrap();
        assert!(!t.located["oil"].contains_key(&usa));
        assert!(t.national["oil"].contains_key(&usa));
        assert!(f.meta.counts.unlocated_producers["oil"].iter().any(|n| n == "USA"));
        assert!(!t.national["bauxite"].contains_key(&usa));

        // Presence and quality: 1,471 districts, rank 0 exactly where the bit is 0.
        assert_eq!(f.presence.len(), 1471);
        assert_eq!(f.quality.len(), 1471);
        for (d, q) in &f.quality {
            let mask = f.presence[d];
            for i in 0..12 {
                assert_eq!(q[i] == 0, mask >> i & 1 == 0, "{d}[{i}]");
            }
        }
        assert!(commodity_index("iron") == Some(6) && commodity_index("rice").is_none());

        // Prices: oil never has a row; every mined line is priced with a
        // source or named as omitted.
        assert!(!f.price_1990.contains_key("oil"));
        assert!(t.price[OIL].is_none());
        for c in TRACKED.iter().filter(|c| **c != "oil") {
            let priced = f.price_1990.get(*c).is_some_and(|p| p.usd_per_unit > 0.0 && !p.source.trim().is_empty());
            let omitted = f.meta.prices_omitted.contains_key(*c);
            assert!(priced ^ omitted, "{c}: priced={priced} omitted={omitted}");
        }

        // The resolved index agrees with the file.
        for c in TRACKED {
            assert_eq!(t.national[c].len(), f.national_1990[c].len());
            assert_eq!(t.located[c].len(), f.located[c].len());
        }
        assert_eq!(t.district_rows.len(), f.meta.counts.located_rows.values().sum::<usize>());
        assert_eq!(t.presence_rows.len(), 1471);
    }

    /// The loader refuses what it should: an unknown field, a share below the
    /// floor, a key that names nobody, a dropped key that is a start nation,
    /// and a transcribed table that no longer adds up. Each is a listed error,
    /// not a panic and not a silent default.
    #[test]
    fn the_loader_refuses_a_bad_table() {
        let mut v: serde_json::Value = serde_json::from_str(EMBEDDED_RESOURCES_1990).unwrap();
        v["located"]["iron"]["USSR"][0][1] = serde_json::json!(1e-4);
        v["national_1990"]["iron"]["Atlantis"] = serde_json::json!({"value": 1.0, "source": "x"});
        v["national_1990"]["iron"]["Russia"] = serde_json::json!({"value": 1.0, "source": "x"});
        v["meta"]["dropped_keys"] = serde_json::json!(["USA"]);
        v["national_1990"]["uranium"]["USSR"]["value"] = serde_json::json!(14001.0);
        let errs = parse_and_validate(&v.to_string()).unwrap_err();
        let text = render_errors(&errs);
        assert!(text.contains("sums to"), "{text}");
        assert!(text.contains("below the floor"), "{text}");
        assert!(text.contains("Atlantis"), "{text}");
        assert!(text.contains("Russia") && text.contains("not on the board"), "{text}");
        assert!(text.contains("dropped_keys"), "{text}");
        assert!(text.contains("rows carried sum to"), "{text}");

        let mut v: serde_json::Value = serde_json::from_str(EMBEDDED_RESOURCES_1990).unwrap();
        v["tonnage_per_district"] = serde_json::json!({});
        let errs = parse_and_validate(&v.to_string()).unwrap_err();
        assert!(render_errors(&errs).contains("unknown field"));
    }

    fn built(mut w: WorldState) -> WorldState {
        w.reindex();
        tick(&mut w);
        w
    }

    fn code(s: &str) -> NationId {
        NationId::from_code(s).unwrap()
    }

    #[test]
    fn a_mine_builds_for_a_year_and_follows_the_district() {
        let mut w = built(world_1990(GameRules {
            resource_gates: true,
            ..GameRules::default()
        }));
        let (chile, peru) = (code("Chile"), code("Peru"));
        let c = Commodity::Copper;
        let district = w
            .districts
            .iter()
            .find(|(d, owner)| **owner == chile && quality_of(d, c) > 0)
            .map(|(d, _)| d.clone())
            .expect("Chile has a mapped copper deposit");
        let expected = mine_output(&district, c).unwrap();
        w.nation_mut(chile).political_capital = 100.0;
        crate::apply_command(
            &mut w,
            &crate::Command::DevelopResource {
                nation: chile,
                district: district.clone(),
                commodity: c,
            },
        )
        .unwrap();
        assert_eq!(w.nation(chile).political_capital, 100.0 - MINE_PC_COST);
        assert_eq!(mine_project_at(&w, &district, c).unwrap().months_left, MINE_BUILD_MONTHS);

        // Construction and completed output stay with the ground, not the
        // government that paid for it.
        w.districts.insert(district.clone(), peru);
        w.districts_epoch = w.districts_epoch.wrapping_add(1);
        for _ in 0..MINE_BUILD_MONTHS - 1 {
            tick(&mut w);
        }
        let before = flow(&w, peru, c);
        tick(&mut w);
        assert!((flow(&w, peru, c) - before - expected).abs() < expected * 1e-12 + 1e-6);
        assert!(mine_at(&w, &district, c).is_some());
    }

    /// HAVE is the transcribed figure, located and summed back: the USSR's
    /// iron is 236,000,000 t after renormalisation, the USA's oil is its
    /// `oil_mbd` ledger and nothing else, the USA mines no bauxite, and the
    /// three figures the spec names read as the table prints them. (The
    /// spec's sketch wrote Chile's copper as 1,588,000; the artifact carries
    /// DS-896's 1,590,000 and the table is what is pinned.) Every located
    /// share is at or above the floor and each nation's shares sum to one.
    #[test]
    fn have_is_the_transcribed_figure() {
        let w = built(world_1990(GameRules::default()));
        let (ussr, usa, china, chile) = (code("USSR"), code("USA"), code("China"), code("Chile"));
        let near = |a: f64, b: f64, tol: f64| (a - b).abs() <= tol;
        assert!(near(flow(&w, ussr, Commodity::Iron), 236_000_000.0, 1.0), "{}", flow(&w, ussr, Commodity::Iron));
        assert_eq!(flow(&w, usa, Commodity::Oil), w.nation(usa).oil_mbd * 1000.0);
        assert_eq!(flow(&w, usa, Commodity::Bauxite), 0.0);
        assert!(near(flow(&w, china, Commodity::Coal), 1_079_300.0, 1.0), "{}", flow(&w, china, Commodity::Coal));
        assert!(near(flow(&w, chile, Commodity::Copper), 1_590_000.0, 1.0), "{}", flow(&w, chile, Commodity::Copper));
        assert!(near(flow(&w, ussr, Commodity::Gas), 28_782.0, 1.0), "{}", flow(&w, ussr, Commodity::Gas));
        // Every 1990 producer's HAVE equals its national figure in January
        // 1990: located shares sum to one and the unlocated keep the whole.
        let t = tables();
        for c in ALL.iter().filter(|c| **c != Commodity::Oil) {
            for (id, v) in &t.national[c.key()] {
                assert!(near(flow(&w, *id, *c), *v, v.abs() * 1e-9 + 1e-6), "{} {}: {} vs {}", id.code(), c.key(), flow(&w, *id, *c), v);
            }
            for (id, list) in &t.located[c.key()] {
                let sum: f64 = list.iter().map(|(_, s)| s).sum();
                assert!((sum - 1.0).abs() <= SHARE_SUM_TOLERANCE, "{} {}", id.code(), c.key());
                assert!(list.iter().all(|(_, s)| *s >= LOCATED_MIN_SHARE));
            }
        }
        // The France of the transcription: cobalt unlocated (New Caledonia
        // has no district), gold located to three districts incl. Guiana.
        let france = code("France");
        assert_eq!(flow(&w, france, Commodity::Cobalt), 800.0);
        assert!(near(flow(&w, france, Commodity::Gold), 4150.0, 1e-6));
        assert!(w.resource_have.presence[france.index()] & Commodity::Gold.bit() != 0);
        assert_eq!(flow(&w, ussr, Commodity::Uranium), 14_000.0);
    }

    /// HAVE follows the ground. Iraq annexing Kuwait gains Kuwait's 147.97
    /// bcf of gas (six located districts); Iran ceding IR-15, IR-13, IR-30
    /// and IR-25 hands Iraq all of Iran's bauxite, 61% of its copper and 54%
    /// of its iron; the USSR dissolving leaves Russia 0.808 of its iron,
    /// Ukraine 0.115, Kazakhstan 0.058 — successor splits fall out of
    /// `dissolve_to` with no new code.
    #[test]
    fn ownership_moves_have() {
        let (iraq, kuwait, iran, ussr) = (code("Iraq"), code("Kuwait"), code("Iran"), code("USSR"));
        let near = |a: f64, b: f64, tol: f64| (a - b).abs() <= tol;

        let mut w = built(world_1990(GameRules::default()));
        let gas_before = flow(&w, iraq, Commodity::Gas);
        let epoch = w.districts_epoch;
        assert_eq!(crate::districts::annex_all(&mut w, iraq, kuwait), 6);
        assert_eq!(w.districts_epoch, epoch.wrapping_add(1));
        tick(&mut w);
        assert!(near(flow(&w, iraq, Commodity::Gas) - gas_before, 147.97, 1e-9), "{}", flow(&w, iraq, Commodity::Gas) - gas_before);
        assert_eq!(flow(&w, kuwait, Commodity::Gas), 0.0);
        // Kuwait's oil is its ledger and did not move: annexation of ground
        // is not a transfer of `oil_mbd`, which the settlement handles.
        assert_eq!(flow(&w, kuwait, Commodity::Oil), w.nation(kuwait).oil_mbd * 1000.0);

        let mut w = built(world_1990(GameRules::default()));
        let (bx, cu, fe) = (
            flow(&w, iran, Commodity::Bauxite),
            flow(&w, iran, Commodity::Copper),
            flow(&w, iran, Commodity::Iron),
        );
        for d in ["IR-15", "IR-13", "IR-30", "IR-25"] {
            assert_eq!(w.districts.get(d), Some(&iran));
            w.districts.insert(d.to_string(), iraq);
        }
        w.districts_epoch = w.districts_epoch.wrapping_add(1);
        tick(&mut w);
        assert!(near(flow(&w, iraq, Commodity::Bauxite), bx, 1e-6));
        assert!(near(flow(&w, iraq, Commodity::Copper) / cu, 0.6111, 5e-4), "{}", flow(&w, iraq, Commodity::Copper) / cu);
        assert!(near(flow(&w, iraq, Commodity::Iron) / fe, 0.5385, 5e-4), "{}", flow(&w, iraq, Commodity::Iron) / fe);
        assert!(near(flow(&w, iran, Commodity::Bauxite), 0.0, 1e-9));
        assert!(near(flow(&w, iran, Commodity::Copper) + flow(&w, iraq, Commodity::Copper), cu, 1e-6));

        let mut w = built(world_1990(GameRules::default()));
        let fe = flow(&w, ussr, Commodity::Iron);
        let heirs: Vec<NationId> = crate::districts::SUCCESSOR_PARENTS
            .iter()
            .filter(|(_, p)| *p == ussr)
            .map(|(h, _)| *h)
            .collect();
        crate::districts::dissolve_to(&mut w, ussr, &heirs);
        tick(&mut w);
        let share = |h: &str| flow(&w, code(h), Commodity::Iron) / fe;
        assert!(near(share("Russia"), 0.808, 1e-3), "{}", share("Russia"));
        assert!(near(share("Ukraine"), 0.115, 1e-3), "{}", share("Ukraine"));
        assert!(near(share("Kazakhstan"), 0.058, 1e-3), "{}", share("Kazakhstan"));
        assert!(near(share("Azerbaijan"), 0.019, 1e-3), "{}", share("Azerbaijan"));
        // The USSR still lives here (nothing killed it), so its unlocated
        // uranium stays; its located iron has all gone to the heirs.
        assert_eq!(flow(&w, ussr, Commodity::Iron), 0.0);
        assert_eq!(flow(&w, ussr, Commodity::Uranium), 14_000.0);
    }

    /// The pile: twelve shortfall evaluations at zero available take cover
    /// from 12 to 0 — the twelfth write lands on 0 and binds (a gate binds
    /// when cover ≤ 0 after this month's write), and so does the thirteenth;
    /// then twelve surplus evaluations, each worth `min(1, surplus/need) = 1`,
    /// refill it to 12, the row folds away, and the save loses the key.
    #[test]
    fn cover_counts_down_and_folds_back() {
        let mut w = built(world_1990(GameRules::default()));
        let iraq = code("Iraq");
        let c = Commodity::Copper;
        assert_eq!(cover(&w, iraq, c), BUFFER_MONTHS);
        assert!(crate::save(&w).find("\"resources\"").is_none());
        for i in 1..=11 {
            let cv = write_cover(&mut w, iraq, c, 0.0, 100.0);
            assert!((cv - (12.0 - i as f64)).abs() < 1e-12, "{i}: {cv}");
            assert!(cv > 0.0);
        }
        assert_eq!(w.resources.cover.len(), 1);
        assert!(crate::save(&w).contains("\"resources\""));
        let cv = write_cover(&mut w, iraq, c, 0.0, 100.0);
        assert_eq!(cv, 0.0, "the twelfth write lands on zero and the gate binds");
        let cv = write_cover(&mut w, iraq, c, 0.0, 100.0);
        assert_eq!(cv, 0.0, "the thirteenth stays bound; the pile never goes negative");
        for i in 1..=12 {
            let cv = write_cover(&mut w, iraq, c, 200.0, 100.0);
            assert!((cv - i as f64).abs() < 1e-12, "{i}: {cv}");
        }
        assert_eq!(cover(&w, iraq, c), BUFFER_MONTHS);
        assert!(w.resources.cover.is_empty() && w.resources.is_empty());
        assert!(crate::save(&w).find("\"resources\"").is_none());
        // A surplus month with no row writes nothing: the pile is full and
        // stays unmaterialised.
        assert_eq!(write_cover(&mut w, iraq, c, 200.0, 100.0), BUFFER_MONTHS);
        assert!(w.resources.is_empty());
        // Exactly enough is neither shortfall nor surplus.
        assert_eq!(write_cover(&mut w, iraq, c, 100.0, 100.0), BUFFER_MONTHS);
        assert!(w.resources.is_empty());
    }

    /// Ruling 2, in the one place a shortage can hurt. Every living nation
    /// sanctions France — every copper producer among them — and France, which
    /// knows laser-guided munitions in 1990, prefers the Paveway line. France
    /// mines 300 t of copper a year against a draw near 76 t a month, so
    /// under section 1.3's arithmetic the pile falls by `1 − 25/76 ≈ 0.67` a
    /// month and binds in the eighteenth evaluation (the spec's sketch said
    /// thirteen, which assumed nothing of its own; the arithmetic is the
    /// model). The month it binds the headline reads exactly
    /// `France: GBU-24 Paveway III line delayed - needs copper; every producer
    /// refuses.`; the order book gains nothing, the money banks under the
    /// 24-line cap, and the gate touched no political capital. With no
    /// preference the staff order the best kit whose inputs are held — the
    /// light infantry formation — and the same sentence prints.
    #[test]
    fn a_closed_market_delays_the_line_and_says_so() {
        let france = code("France");
        let paveway = crate::arsenal::index_of("paveway").unwrap();
        let inf_light = crate::arsenal::index_of("inf_light").unwrap();
        let expected = "France: GBU-24 Paveway III line delayed - needs copper; every producer refuses.";

        let close = |w: &mut WorldState| {
            let ids: Vec<NationId> = w.nations.iter().filter(|n| n.alive && n.id != france).map(|n| n.id).collect();
            for h in ids {
                if !w.is_sanctioning(h, france) {
                    w.sanctions.push((h, france));
                }
            }
        };

        // The preference stalls.
        let mut w = world_1990(GameRules::default());
        assert!(w.nation(france).tech.knows("aero_precision_munitions"));
        w.nation_mut(france).arsenal.preference = Some("paveway".into());
        assert_eq!(crate::arsenal::pick(w.nation(france)), Some(paveway));
        let mut first = None;
        let mut banked_at_stall = 0.0;
        for m in 1..=24 {
            close(&mut w);
            let heads = crate::tick_month(&mut w, &[]);
            let printed = heads.iter().filter(|h| h.as_str() == expected).count();
            assert!(printed <= 1, "{heads:?}");
            // A fresh order carries its kit's full lead time; a month that
            // ordered nothing leaves no such row.
            let fresh = |a: &crate::arsenal::Arsenal| {
                a.orders.iter().any(|o| o.due == DECK[o.kit as usize].lead_months)
            };
            if printed == 1 && first.is_none() {
                first = Some(m);
                // The order book gained nothing this month; the money banked.
                let a = &w.nation(france).arsenal;
                assert!(!fresh(a), "a stalled line placed an order");
                assert!(a.banked > 0.0, "the stalled line's money did not bank");
                banked_at_stall = a.banked;
            } else if let Some(f) = first {
                if m == f + 1 {
                    let a = &w.nation(france).arsenal;
                    assert!(!fresh(a), "a stalled line placed an order the month after");
                    assert!(a.banked > banked_at_stall, "banked money did not grow while the line stayed stalled");
                    assert!(a.banked <= crate::arsenal::budget_of(w.nation(france)) * 24.0 + 1e-9, "banked money escaped the 24-line cap");
                }
            }
            for h in &heads {
                assert!(!h.contains("line delayed") || h == expected, "{h}");
            }
        }
        let first = first.expect("the Paveway line never stalled in 24 months");
        // The arithmetic's own prediction, from the ledger as January read it.
        let mut p = world_1990(GameRules::default());
        close(&mut p);
        let p = built(p);
        let need = kit_need(paveway, crate::arsenal::line_of(p.nation(france)))[Commodity::Copper.idx()];
        let own = flow(&p, france, Commodity::Copper) / 12.0;
        assert!(own > 0.0 && own < need, "France should be short of copper: own {own} need {need}");
        let per_month = 1.0 - own / need;
        let predicted = (BUFFER_MONTHS / per_month).ceil() as usize;
        assert!((first as i64 - predicted as i64).abs() <= 1, "stalled in month {first}, the arithmetic predicts {predicted}");
        assert!(first >= 12, "a stall can never bind before the pile is spent");
        assert_eq!(cover(&w, france, Commodity::Copper), 0.0);

        // The gate itself charges nothing: run it by hand on a bound pile,
        // with the doors closed again (politics may have reopened one in the
        // last tick's statecraft, which runs after the arsenal).
        close(&mut w);
        let pc = w.nation(france).political_capital;
        let line = crate::arsenal::line_of(w.nation(france));
        let (choice, stall) = gate(&mut w, france, paveway, line);
        assert_eq!(choice, None);
        assert_eq!(stall.as_ref().map(|s| s.headline()).as_deref(), Some(expected));
        assert_eq!(w.nation(france).political_capital, pc);

        // With no preference the staff buy the best kit whose inputs are held.
        let mut w = world_1990(GameRules::default());
        assert!(w.nation(france).arsenal.preference.is_none());
        let mut seen = false;
        for _ in 1..=24 {
            close(&mut w);
            let heads = crate::tick_month(&mut w, &[]);
            if heads.iter().any(|h| h == expected) {
                seen = true;
                let last = w.nation(france).arsenal.orders.last().expect("the staff ordered something");
                assert_eq!(last.kit, inf_light, "the fallback is the best kit whose inputs are held");
                assert_eq!(last.due, DECK[inf_light as usize].lead_months, "the fallback order is this month's");
                break;
            }
        }
        assert!(seen, "the AI's delayed line was not headlined");
        close(&mut w);
        let line = crate::arsenal::line_of(w.nation(france));
        assert_eq!(crate::arsenal::ranked(w.nation(france)).first(), Some(&paveway));
        let (choice, stall) = gate(&mut w, france, paveway, line);
        assert_eq!(choice, Some(inf_light));
        assert_eq!(stall.map(|s| s.headline()).as_deref(), Some(expected));
    }

    /// The coefficients are an order of magnitude, and the check the spec
    /// names holds: the whole United States line ordered as naval kit draws
    /// under 2% of the ore the United States mines; the legacy tier draws
    /// nothing at any line.
    #[test]
    fn kit_need_magnitudes() {
        let w = built(world_1990(GameRules::default()));
        let usa = code("USA");
        let line = crate::arsenal::line_of(w.nation(usa));
        assert!(line > 4.0 && line < 7.0, "US line {line} $bn/month");
        let naval = crate::arsenal::index_of("la_ssn").unwrap();
        let need = kit_need(naval, line);
        let ore_month = flow(&w, usa, Commodity::Iron) / 12.0;
        let share = need[Commodity::Iron.idx()] / ore_month;
        assert!(share > 0.005 && share < 0.02, "US naval line draws {:.2}% of US ore", share * 100.0);
        assert!(need[Commodity::Coal.idx()] > 0.0 && need[Commodity::Bauxite.idx()] == 0.0);
        let air = crate::arsenal::index_of("f15e").unwrap();
        assert!(kit_need(air, line)[Commodity::Bauxite.idx()] > 0.0);
        let missile = crate::arsenal::index_of("tomahawk").unwrap();
        assert!(kit_need(missile, line)[Commodity::Copper.idx()] > 0.0);
        let infantry = crate::arsenal::index_of("c4isr").unwrap();
        assert!(kit_need(infantry, line).iter().all(|q| *q == 0.0));
        for (i, def) in DECK.iter().enumerate() {
            if def.tech.is_none() {
                assert!(kit_need(i as u16, 100.0).iter().all(|q| *q == 0.0), "{} draws", def.id);
            }
        }
        assert!(kit_need(naval, 0.0).iter().all(|q| *q == 0.0));
        assert!(kit_need(u16::MAX, 1.0).iter().all(|q| *q == 0.0));
    }

    /// The accessors answer the None arm before the first tick and the real
    /// ledger after it; the market reads sanctions, war and the floor.
    #[test]
    fn supply_is_pure_and_reads_the_closed_doors() {
        let mut w = world_1990(GameRules::default());
        w.reindex();
        assert!(!w.resource_have.built);
        assert_eq!(flow(&w, code("USSR"), Commodity::Iron), 0.0);
        let s = supply(&w, code("Japan"), Commodity::Iron, 1.0);
        assert_eq!(s.available, 0.0);
        assert!(!s.any_producer);
        assert!(matches!(have(&w), Cow::Owned(_)));
        tick(&mut w);
        assert!(matches!(have(&w), Cow::Borrowed(_)));
        // Japan mines 34,000 t of iron ore a year — 2,833 t a month — so a
        // draw of 10,000 t is two-thirds market, and the market fills it.
        let japan = code("Japan");
        let need = 10_000.0;
        let s = supply(&w, japan, Commodity::Iron, need);
        assert!(s.any_producer && s.holder.is_some());
        assert!(s.own > 0.0 && s.own < need, "{}", s.own);
        assert_eq!(s.available, need);
        assert_eq!(s.market, need - s.own);
        // Own flow alone covers a smaller draw and the market sells nothing.
        let s0 = supply(&w, japan, Commodity::Iron, 1000.0);
        assert_eq!(s0.market, 0.0);
        assert_eq!(s0.available, s0.own);
        let holder = s.holder.unwrap();
        assert_eq!(open_holder(&w, japan, Commodity::Iron), Some(holder));
        assert!(producers(&w, Commodity::Iron).contains(&holder));
        // Sanctions in either direction close a door; the next holder opens.
        w.sanctions.push((japan, holder));
        let s2 = supply(&w, japan, Commodity::Iron, need);
        assert_ne!(s2.holder, Some(holder));
        assert!(s2.holder > Some(holder));
        // Relations below the floor close it too.
        let mut w2 = w.clone();
        let ps = producers(&w2, Commodity::Iron);
        for p in &ps {
            w2.set_relation(japan, *p, RELATION_FLOOR - 1.0);
        }
        w2.sanctions.clear();
        let s3 = supply(&w2, japan, Commodity::Iron, need);
        assert!(s3.any_producer && s3.holder.is_none());
        assert_eq!(s3.available, s3.own);
        // Same state, same answer, no RNG: twice over.
        assert_eq!(supply(&w2, japan, Commodity::Iron, need), s3);
        assert_eq!(month_abs(&w), 0);
    }

    // -----------------------------------------------------------------
    // Package S2 — player trade (spec section 4.10, and the brief's five:
    // evaluate is pure, a contract delivers and expires, a breach is
    // charged through the reneging path, a land transfer conserves
    // ownership, and two worlds with the same deals are byte-identical).
    // Nothing here fires without a command, which is why both goldens'
    // actuals stay where S1 left them (lib.rs, `the_resource_layer_is_
    // inert_*`: 0xa5c9c5b2306313d8 and 0x20c24ab0f1581807, re-pinned by
    // nothing).
    // -----------------------------------------------------------------

    use crate::{apply_command, tick_month, Command};

    fn money(bn: f64) -> Leg {
        Leg::Money { bn_per_year: bn }
    }
    fn com(c: Commodity, per_month: f64) -> Leg {
        Leg::Commodity { c, per_month }
    }
    fn land(id: &str) -> Leg {
        Leg::District { id: id.to_string() }
    }
    fn propose(
        w: &mut WorldState,
        from: NationId,
        to: NationId,
        give: Vec<Leg>,
        take: Vec<Leg>,
        months: u32,
    ) -> Result<(), String> {
        apply_command(w, &Command::ProposeDeal { from, to, give, take, months })
    }
    /// The price a counter names: "We would want $X bn a year."
    fn asked(err: &str) -> f64 {
        err.strip_prefix("We would want $")
            .and_then(|s| s.strip_suffix(" bn a year."))
            .unwrap_or_else(|| panic!("not a counter: {err}"))
            .parse()
            .unwrap()
    }
    /// Ask at zero, take the counter, sign. Returns the money agreed.
    fn buy(w: &mut WorldState, buyer: NationId, seller: NationId, c: Commodity, per_month: f64, months: u32) -> f64 {
        let e = propose(w, buyer, seller, vec![money(0.0)], vec![com(c, per_month)], months).unwrap_err();
        let m = asked(&e);
        propose(w, buyer, seller, vec![money(m)], vec![com(c, per_month)], months).unwrap();
        m
    }
    /// A seat with the standing to spend, open to `other`: no sanction
    /// either way and a warm relation, so only the bar under test answers.
    fn seat(w: &mut WorldState, id: NationId, other: NationId) {
        w.player = Some(id);
        w.nation_mut(id).political_capital = 100.0;
        w.sanctions.retain(|(a, b)| !((*a == id && *b == other) || (*a == other && *b == id)));
        w.set_relation(id, other, 60.0);
    }
    fn near(a: f64, b: f64, tol: f64) -> bool {
        (a - b).abs() <= tol
    }

    /// Acceptance item 7. `evaluate` is a pure function of state: the same
    /// world answers the same way two hundred times, a clone answers
    /// identically, and asking leaves no trace in the save. The four commands
    /// consume no randomness — `w.rng` is bit-identical across a signing, a
    /// declined offer, an accepted one and a cancellation — and the same
    /// sequence on the clone lands on the same bytes.
    #[test]
    fn a_deal_is_a_pure_function_of_state() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        let give = vec![money(0.4)];
        let take = vec![com(Commodity::Bauxite, 8_000.0)];
        let first = evaluate(&w, japan, australia, &give, &take, 60);
        assert!(matches!(first, Verdict::Accept | Verdict::Counter { .. }), "{first:?}");
        let twin = w.clone();
        let before = crate::save(&w);
        for _ in 0..200 {
            assert_eq!(evaluate(&w, japan, australia, &give, &take, 60), first);
            assert_eq!(evaluate(&twin, japan, australia, &give, &take, 60), first);
            assert_eq!(deal_refusal(&w, japan, australia, &give, &take, 60), None);
        }
        assert_eq!(crate::save(&w), before, "evaluate wrote something");

        let script = |w: &mut WorldState| -> (u32, f64) {
            let rng = w.rng.state;
            let m = buy(w, japan, australia, Commodity::Bauxite, 8_000.0, 60);
            assert_eq!(w.rng.state, rng, "ProposeDeal rolled a die");
            let contract = w.resources.contracts[0].id;
            for (id, accept) in [(101u32, false), (102u32, true)] {
                w.resources.offers.push(Offer {
                    id,
                    from: australia,
                    to: japan,
                    give: vec![money(0.2)],
                    take: vec![com(Commodity::Iron, 100.0)],
                    months: 12,
                    expires: 6,
                });
                let c = if accept {
                    Command::AcceptDeal { nation: japan, offer: id }
                } else {
                    Command::DeclineDeal { nation: japan, offer: id }
                };
                apply_command(w, &c).unwrap();
                assert_eq!(w.rng.state, rng, "{c:?} rolled a die");
            }
            assert!(w.resources.offers.is_empty());
            assert_eq!(w.resources.contracts.len(), 2);
            apply_command(w, &Command::CancelDeal { nation: japan, contract }).unwrap();
            assert_eq!(w.rng.state, rng, "CancelDeal rolled a die");
            assert_eq!(w.resources.contracts.len(), 1);
            (contract, m)
        };
        let mut twin = twin;
        assert_eq!(script(&mut w), script(&mut twin));
        assert_eq!(crate::save(&w), crate::save(&twin));
    }

    /// Acceptance item 7: each hard bar, provoked once, answers with its
    /// sentence exactly — through `deal_refusal` and through the command —
    /// and charges nothing. `LastDistrict` is answered at the transfer
    /// itself: the ordered bars put "Nobody sells their people" first, and a
    /// nation holding one district holds all of its people in it. The shape
    /// bars of section 4.3 follow, each uncharged.
    #[test]
    fn every_refusal_has_its_sentence() {
        let (japan, australia, usa, canada, mexico, iraq, kuwait) = (
            code("Japan"),
            code("Australia"),
            code("USA"),
            code("Canada"),
            code("Mexico"),
            code("Iraq"),
            code("Kuwait"),
        );
        let bauxite = vec![com(Commodity::Bauxite, 8_000.0)];
        let fresh = || built(world_1990(GameRules::default()));
        let check = |w: &mut WorldState, from: NationId, to: NationId, give: Vec<Leg>, take: Vec<Leg>, months: u32, want: &str| {
            w.nation_mut(from).political_capital = 50.0;
            let said = deal_refusal(w, from, to, &give, &take, months);
            assert_eq!(said.as_deref(), Some(want));
            let e = propose(w, from, to, give, take, months).unwrap_err();
            assert_eq!(e, want);
            assert_eq!(w.nation(from).political_capital, 50.0, "{want:?} was charged");
        };

        // AtWar: the receiver is fighting the proposer.
        let mut w = fresh();
        seat(&mut w, iraq, kuwait);
        let th = crate::war::theatre_between(&w, iraq, kuwait);
        crate::commitment::open_conflict(&mut w, iraq, kuwait, th).unwrap();
        check(&mut w, iraq, kuwait, vec![money(0.0)], vec![com(Commodity::Gas, 1.0)], 60, &Reason::AtWar.sentence());

        // Embargoed: a sanction either way.
        let mut w = fresh();
        seat(&mut w, japan, australia);
        w.sanctions.push((australia, japan));
        check(&mut w, japan, australia, vec![money(0.0)], bauxite.clone(), 60, &Reason::Embargoed.sentence());

        // BrokeContract: a live grievance.
        let mut w = fresh();
        seat(&mut w, japan, australia);
        let until = month_abs(&w) + GRIEVANCE_MONTHS;
        w.resources.grievances.push(Grievance { victim: australia, breaker: japan, until });
        check(&mut w, japan, australia, vec![money(0.0)], bauxite.clone(), 60, &Reason::BrokeContract.sentence());

        // Distrust: under the relation floor.
        let mut w = fresh();
        seat(&mut w, japan, australia);
        w.set_relation(japan, australia, RELATION_FLOOR - 1.0);
        check(&mut w, japan, australia, vec![money(0.0)], bauxite.clone(), 60, &Reason::Distrust.sentence());

        // NoSurplus: Japan mines no bauxite.
        let mut w = fresh();
        seat(&mut w, australia, japan);
        assert!(surplus(&w, japan, Commodity::Bauxite) <= 0.0);
        check(&mut w, australia, japan, vec![money(0.0)], bauxite.clone(), 60, &Reason::NoSurplus.sentence());

        // LandContested: Alaska on the front of somebody else's war.
        let mut w = fresh();
        seat(&mut w, usa, canada);
        let th = crate::war::theatre_between(&w, mexico, usa);
        let id = crate::commitment::open_conflict(&mut w, mexico, usa, th).unwrap();
        w.conflict_mut(id).unwrap().front.insert("US-AK".into(), 1.0);
        assert!(district_contested(&w, "US-AK"));
        check(&mut w, usa, canada, vec![land("US-AK")], vec![money(0.0)], 60, &Reason::LandContested.sentence());

        // NotForSale: the most populous American district.
        let mut w = fresh();
        seat(&mut w, usa, canada);
        let big = w
            .districts
            .iter()
            .filter(|&(_, &o)| o == usa)
            .map(|(d, _)| d.clone())
            .max_by(|a, b| pop_share_of(&w, usa, a).partial_cmp(&pop_share_of(&w, usa, b)).unwrap())
            .unwrap();
        assert!(pop_share_of(&w, usa, &big) > NOT_FOR_SALE_POP);
        check(&mut w, usa, canada, vec![land(&big)], vec![money(0.0)], 60, &Reason::NotForSale.sentence());

        // LandDistrust: the receiver cedes to a state it does not trust.
        let mut w = fresh();
        seat(&mut w, canada, usa);
        w.set_relation(canada, usa, LAND_TRUST - 1.0);
        check(&mut w, canada, usa, vec![money(0.0)], vec![land("US-AK")], 60, &Reason::LandDistrust.sentence());

        // GovernmentWouldFall: the ceder's government is too weak.
        let mut w = fresh();
        seat(&mut w, canada, usa);
        w.set_relation(canada, usa, 100.0);
        w.nation_mut(usa).stability = GOVERNMENT_FLOOR - 1.0;
        check(&mut w, canada, usa, vec![money(0.0)], vec![land("US-AK")], 60, &Reason::GovernmentWouldFall.sentence());

        // LastDistrict: Kuwait down to Al Ahmadi.
        let mut w = fresh();
        seat(&mut w, kuwait, iraq);
        let others: Vec<String> =
            w.districts.iter().filter(|&(d, &o)| o == kuwait && d != "KW-AH").map(|(d, _)| d.clone()).collect();
        for d in others {
            w.districts.insert(d, iraq);
        }
        w.districts_epoch = w.districts_epoch.wrapping_add(1);
        assert_eq!(holdings(&w, kuwait), 1);
        assert_eq!(
            crate::districts::transfer_district(&mut w, kuwait, iraq, "KW-AH"),
            Err(Reason::LastDistrict.sentence())
        );
        assert_eq!(pop_share_of(&w, kuwait, "KW-AH"), 1.0);
        check(&mut w, kuwait, iraq, vec![land("KW-AH")], vec![money(0.0)], 60, &Reason::NotForSale.sentence());

        // NotForThatPrice: the smallest economy on the board asks for a
        // million tonnes of bauxite a month.
        let mut w = fresh();
        let small = w
            .nations
            .iter()
            .filter(|n| n.alive && n.id != australia)
            .min_by(|a, b| a.gdp.partial_cmp(&b.gdp).unwrap())
            .unwrap()
            .id;
        seat(&mut w, small, australia);
        let ask = vec![com(Commodity::Bauxite, 1_000_000.0)];
        let said = deal_refusal(&w, small, australia, &[money(0.0)], &ask, 60).expect("a refusal");
        assert!(said.starts_with("Not for that price: we would want $") && said.ends_with(" bn a year."), "{said}");
        let want: f64 = said
            .trim_start_matches("Not for that price: we would want $")
            .trim_end_matches(" bn a year.")
            .parse()
            .unwrap();
        assert!(want > cap(&w, small), "{want} vs cap {}", cap(&w, small));
        assert_eq!(Reason::NotForThatPrice { bn_per_year: want }.sentence(), said);
        check(&mut w, small, australia, vec![money(0.0)], ask, 60, &said);

        // The two the receiver never says in this cut, pinned all the same.
        assert_eq!(Reason::LastDistrict.sentence(), "It is all we have.");
        assert_eq!(Reason::Unanswered.sentence(), "You let our last offer lapse.");

        // The shape bars, each uncharged.
        let mut w = fresh();
        seat(&mut w, japan, australia);
        let cases: Vec<(Vec<Leg>, Vec<Leg>, u32, &str)> = vec![
            (vec![money(0.0)], bauxite.clone(), 13, "Terms run 12, 36, 60 or 120 months."),
            (vec![money(0.0), land("JP-01"), land("JP-05")], bauxite.clone(), 60, "At most four legs, one of them land."),
            (vec![money(0.0)], vec![money(1.0)], 60, "A leg must carry something."),
            (vec![money(0.0)], vec![com(Commodity::Bauxite, 0.0)], 60, "A leg must carry something."),
            (vec![land("AU-WA")], vec![money(0.0)], 60, "Japan does not hold AU-WA."),
            (vec![money(1e9)], bauxite.clone(), 60, "That would put Japan's contracted spending over 1% of output."),
        ];
        for (give, take, months, want) in cases {
            check(&mut w, japan, australia, give, take, months, want);
        }
        assert_eq!(
            deal_refusal(&w, japan, japan, &[money(0.0)], &bauxite, 60).as_deref(),
            Some("A nation cannot trade with itself.")
        );
    }

    /// Acceptance item 7. Ask at zero: the answer is the price, as an error,
    /// and nothing is charged. Ask again at that price: signed, three
    /// political capital charged once, +5 relation, the headline exact, a
    /// tenth of a billion less and the seller counters again. Ask for more
    /// than the seller has: the counter clips the leg to the seller's
    /// surplus and, re-offered with the clipped leg, is accepted by
    /// construction — the spec's sentence ("the price that makes gain =
    /// MARGIN × cost_out"), not its sketch's formula, which landed the
    /// receiver at a loss.
    #[test]
    fn a_counter_re_offered_is_accepted() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        let q = 8_000.0;
        let e = propose(&mut w, japan, australia, vec![money(0.0)], vec![com(Commodity::Bauxite, q)], 60).unwrap_err();
        let m = asked(&e);
        assert!(m > 0.0 && near((m * 10.0).round(), m * 10.0, 1e-9), "{m} is not a tenth of a billion");
        assert_eq!(w.nation(japan).political_capital, 100.0, "a counter was charged");
        assert!(w.resources.contracts.is_empty());
        assert_ne!(
            evaluate(&w, japan, australia, &[money(m - 0.1)], &[com(Commodity::Bauxite, q)], 60),
            Verdict::Accept
        );
        let rel = w.relation(japan, australia);
        propose(&mut w, japan, australia, vec![money(m)], vec![com(Commodity::Bauxite, q)], 60).unwrap();
        assert_eq!(w.nation(japan).political_capital, 97.0);
        assert_eq!(w.relation(japan, australia), rel + SIGN_RELATION);
        let k = &w.resources.contracts[0];
        assert_eq!(
            (k.id, k.from, k.to, k.months_left, k.months_total, k.since, k.depth),
            (1, japan, australia, 60, 60, 0, 0.0)
        );
        assert_eq!(k.give, vec![money(m)]);
        assert_eq!(k.take, vec![com(Commodity::Bauxite, q)]);
        let expected = format!(
            "Japan and Australia sign a supply contract: Australia sends Japan 8,000 t/mo of bauxite for ${m:.1}bn a year, 60 months."
        );
        assert_eq!(w.headlines.last(), Some(&expected));
        assert!(crate::save(&w).contains("\"contracts\""));

        // Clipping: more than Australia can spare.
        let s = surplus(&w, australia, Commodity::Bauxite);
        assert!(s > 0.0);
        let big = s * 3.0;
        match evaluate(&w, japan, australia, &[money(0.0)], &[com(Commodity::Bauxite, big)], 36) {
            Verdict::Counter { money_bn_per_year, take } => {
                assert_eq!(take, vec![com(Commodity::Bauxite, s)]);
                assert_eq!(evaluate(&w, japan, australia, &[money(money_bn_per_year)], &take, 36), Verdict::Accept);
                assert_ne!(
                    evaluate(&w, japan, australia, &[money(money_bn_per_year)], &[com(Commodity::Bauxite, big)], 36),
                    Verdict::Accept
                );
            }
            other => panic!("{other:?}"),
        }
    }

    /// Acceptance item 7. A leg on a line with no 1990 figure is a hard
    /// error with its sentence. Since package D2 (fork F3) every line in the
    /// table is tracked and priced, so the arm is exercised with the line
    /// predicate injected; the live predicate lets a cobalt leg through to
    /// the receiver's own answer. Hard errors charge nothing.
    #[test]
    fn an_untracked_leg_is_refused_uncharged() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        let give = vec![money(0.0)];
        let take = vec![com(Commodity::Cobalt, 1.0)];
        let said = validate_bundle(&w, japan, australia, &give, &take, 36, |c| c != Commodity::Cobalt);
        assert_eq!(said.as_deref(), Some("No 1990 figure is transcribed for cobalt; it cannot be contracted."));
        assert_eq!(untracked_leg_sentence(Commodity::RareEarths), "No 1990 figure is transcribed for rare earths; it cannot be contracted.");
        assert!(ALL.iter().all(|c| contractable(*c)), "every line is tracked and priced since D2");
        let live = deal_refusal(&w, japan, australia, &give, &take, 36);
        assert_ne!(live, Some(untracked_leg_sentence(Commodity::Cobalt)));
        // A hard error through the command costs nothing.
        let e = propose(&mut w, japan, australia, give, take, 13).unwrap_err();
        assert_eq!(e, "Terms run 12, 36, 60 or 120 months.");
        assert_eq!(w.nation(japan).political_capital, 100.0);
    }

    /// Acceptance item 8, ruling 2 on the money side. Japan buys 8 kt/mo of
    /// bauxite from Australia for five years; a control world signs nothing.
    /// Every quantity the growth model reads — gdp, growth_last, oil_mbd,
    /// mil_strength, munitions, stability, the arsenal's book value — is
    /// bit-identical between the two for every nation every month; the
    /// buyer's debt runs above the control's and the seller's below it from
    /// the first delivery; no trade pact is created and no level gain paid
    /// (the pact lists and `trade_level_paid` agree between the arms); the
    /// RNG stream never parts.
    ///
    /// Construction: Japan is the seat (the fiscal AI skips it), aggression
    /// is off (no appetite reads a debt), and the pair's relation sits at
    /// 100 in both arms so the signing's +5 clamps to nothing. The rules
    /// that read a debt — the fiscal AI's consolidation at 0.85 and 0.30,
    /// the economy's drag at 0.90 — are asserted to have fired the same way
    /// in both arms every month: a threshold straddled by a 0.02%-of-output
    /// transfer would be that rule speaking, not growth, and the test says
    /// so rather than reading it as a growth effect. (A first construction
    /// pinned both debts to 0.50; Australia's decayed to 0.306 by month 28,
    /// which is how the sim's own paydown rate came to be known here.)
    #[test]
    fn a_contract_touches_no_growth() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mk = || {
            let mut w = world_1990(GameRules::default());
            w.rules.ai_aggression = 0.0;
            seat(&mut w, japan, australia);
            w.set_relation(japan, australia, 100.0);
            w
        };
        let (mut control, mut treated) = (mk(), mk());
        let m = buy(&mut treated, japan, australia, Commodity::Bauxite, 8_000.0, 60);
        assert!(m > 0.0);
        assert_eq!(treated.rng.state, control.rng.state);
        assert_eq!(treated.relation(japan, australia), 100.0);
        for month in 0..60 {
            tick_month(&mut control, &[]);
            tick_month(&mut treated, &[]);
            assert_eq!(treated.rng.state, control.rng.state, "month {month}: the streams parted");
            assert_eq!(control.nations.len(), treated.nations.len());
            for (a, b) in control.nations.iter().zip(&treated.nations) {
                assert_eq!(a.id, b.id);
                let pairs = [
                    ("gdp", a.gdp, b.gdp),
                    ("growth_last", a.growth_last, b.growth_last),
                    ("oil_mbd", a.oil_mbd, b.oil_mbd),
                    ("mil_strength", a.mil_strength, b.mil_strength),
                    ("munitions", a.munitions, b.munitions),
                    ("stability", a.stability, b.stability),
                    ("book_value", crate::arsenal::book_value(a), crate::arsenal::book_value(b)),
                ];
                for (name, x, y) in pairs {
                    assert_eq!(x.to_bits(), y.to_bits(), "month {month} {}: {name} {x} vs {y}", a.id.code());
                }
            }
            for id in [japan, australia] {
                let (c, t) = (control.nation(id).debt_gdp, treated.nation(id).debt_gdp);
                for bar in [0.30, 0.85, 0.90] {
                    assert_eq!(c < bar, t < bar, "month {month}: {} debt {c} vs {t} straddles {bar}", id.code());
                }
            }
            assert!(treated.nation(japan).debt_gdp > control.nation(japan).debt_gdp, "month {month}");
            assert!(treated.nation(australia).debt_gdp < control.nation(australia).debt_gdp, "month {month}");
            assert_eq!(treated.statecraft.trade, control.statecraft.trade, "month {month}: the contract made a pact");
            for id in [japan, australia] {
                assert_eq!(treated.nation(id).trade_level_paid, control.nation(id).trade_level_paid);
            }
        }
        assert!(treated.resources.contracts.is_empty(), "the term ran out at sixty");
    }

    /// The brief's "a contract delivers and expires". A twelve-month
    /// contract: each delivery moves the buyer's debt up by exactly
    /// `bn/12/gdp` and the seller's down by the same, deepens by 0.012 and
    /// counts a month off; the twelfth removes it with its headline; the
    /// delivery itself touches no reputation and no relation.
    #[test]
    fn a_contract_delivers_and_expires() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        let m = buy(&mut w, japan, australia, Commodity::Bauxite, 8_000.0, 12);
        let (rep_j, rep_a, rel) = (w.reputation(japan), w.reputation(australia), w.relation(japan, australia));
        for k in 1..=12u32 {
            let (dj, gj) = (w.nation(japan).debt_gdp, w.nation(japan).gdp);
            let (da, ga) = (w.nation(australia).debt_gdp, w.nation(australia).gdp);
            let want_j = dj + m / 12.0 / gj.max(0.1);
            let want_a = (da - m / 12.0 / ga.max(0.1)).max(0.0);
            w.headlines.clear();
            tick(&mut w);
            assert_eq!(w.nation(japan).debt_gdp.to_bits(), want_j.to_bits(), "delivery {k}");
            assert_eq!(w.nation(australia).debt_gdp.to_bits(), want_a.to_bits(), "delivery {k}");
            if k < 12 {
                let c = &w.resources.contracts[0];
                assert_eq!(c.months_left, 12 - k);
                assert!(near(c.depth, DEPTH_RATE * k as f64, 1e-12));
                assert!(w.headlines.is_empty(), "{:?}", w.headlines);
            } else {
                assert!(w.resources.contracts.is_empty());
                assert_eq!(w.headlines, vec!["The bauxite contract between Japan and Australia has run its term.".to_string()]);
            }
            assert_eq!((w.reputation(japan), w.reputation(australia), w.relation(japan, australia)), (rep_j, rep_a, rel));
        }
        // A thirteenth tick finds nothing to deliver and nothing to say.
        let (dj, da) = (w.nation(japan).debt_gdp, w.nation(australia).debt_gdp);
        w.headlines.clear();
        tick(&mut w);
        assert_eq!((w.nation(japan).debt_gdp, w.nation(australia).debt_gdp), (dj, da));
        assert!(w.headlines.is_empty());
    }

    /// Acceptance item 8. Japan takes two million tonnes of bauxite a month
    /// from Australia — within its surplus at signing. Indonesia takes
    /// Western Australia, where most of it is mined: the next delivery, the
    /// seller's flow no longer covers what it promised, so the buyer's
    /// `supply().contracts` is scaled by flow ÷ promised, the headline prints
    /// once, the contract stands, and neither reputation nor relation moves.
    #[test]
    fn force_majeure_is_pro_rata_and_uncharged() {
        let (japan, australia, indonesia) = (code("Japan"), code("Australia"), code("Indonesia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        let q = 2_000_000.0;
        assert!(surplus(&w, australia, Commodity::Bauxite) > q);
        buy(&mut w, japan, australia, Commodity::Bauxite, q, 60);
        assert_eq!(w.resources.contracts[0].take, vec![com(Commodity::Bauxite, q)]);
        assert_eq!(supply(&w, japan, Commodity::Bauxite, q).contracts, q);
        assert_eq!(delivery_ratio(&w, australia, Commodity::Bauxite), 1.0);

        assert_eq!(w.districts.get("AU-WA"), Some(&australia));
        w.districts.insert("AU-WA".into(), indonesia);
        w.districts_epoch = w.districts_epoch.wrapping_add(1);
        let (rep, rel) = (w.reputation(australia), w.relation(japan, australia));
        w.headlines.clear();
        tick(&mut w);
        let left = flow(&w, australia, Commodity::Bauxite) / 12.0;
        assert!(left > 0.0 && left < q, "Australia keeps {left} t/mo against a promise of {q}");
        let ratio = delivery_ratio(&w, australia, Commodity::Bauxite);
        assert!(near(ratio, left / q, 1e-12));
        let s = supply(&w, japan, Commodity::Bauxite, q);
        assert!(near(s.contracts, left, 1e-6), "{} vs {left}", s.contracts);
        assert!(near(s.contracts, q * ratio, 1e-6));
        let expected = "Australia cannot deliver all of its bauxite this month; contracts are filled pro rata.";
        assert_eq!(w.headlines.iter().filter(|h| h.as_str() == expected).count(), 1, "{:?}", w.headlines);
        assert_eq!(w.resources.contracts.len(), 1);
        assert_eq!(w.resources.contracts[0].months_left, 59);
        assert_eq!((w.reputation(australia), w.relation(japan, australia)), (rep, rel));
        // The seller's surplus reads the shortfall too.
        assert!(surplus(&w, australia, Commodity::Bauxite) < 0.0);
        // Next month, the same sentence once more — once per giver, line and month.
        w.headlines.clear();
        tick(&mut w);
        assert_eq!(w.headlines.iter().filter(|h| h.as_str() == expected).count(), 1);
    }

    /// Acceptance item 8; the brief's "breach is charged through the existing
    /// reneging path". Tearing up a contract at zero political capital is
    /// never refused: the standing stays at zero, reputation falls by
    /// `abrogate_trade`'s six, the relation by its twenty-five, and the other
    /// side answers every ask from the breaker with "You broke your last
    /// contract with us." for thirty-six months and with a price in the
    /// thirty-seventh, when the memory has cooled and the row is gone.
    #[test]
    fn cancelling_is_charged_never_refused() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, australia);
        buy(&mut w, japan, australia, Commodity::Bauxite, 8_000.0, 60);
        buy(&mut w, japan, australia, Commodity::Bauxite, 1_000.0, 12);
        let (first, second) = (w.resources.contracts[0].id, w.resources.contracts[1].id);
        w.nation_mut(japan).political_capital = 0.0;
        let (rep, rel) = (w.reputation(japan), w.relation(japan, australia));
        let before = crate::save(&w);
        apply_command(&mut w, &Command::CancelDeal { nation: japan, contract: first }).unwrap();
        assert_eq!(w.nation(japan).political_capital, 0.0);
        assert_eq!(w.reputation(japan), rep + CANCEL_REPUTATION);
        assert_eq!(w.relation(japan, australia), rel + CANCEL_RELATION);
        assert_eq!(w.resources.contracts.len(), 1);
        let until = month_abs(&w) + GRIEVANCE_MONTHS;
        assert_eq!(w.resources.grievances, vec![Grievance { victim: australia, breaker: japan, until }]);
        assert_eq!(w.headlines.last().map(String::as_str), Some("Japan tears up its supply contract with Australia."));
        assert_ne!(crate::save(&w), before);
        assert_eq!(
            apply_command(&mut w, &Command::CancelDeal { nation: japan, contract: 99 }),
            Err("No such contract.".into())
        );
        // A second breach a month later is the same grievance, extended.
        tick_month(&mut w, &[]);
        apply_command(&mut w, &Command::CancelDeal { nation: japan, contract: second }).unwrap();
        assert!(w.resources.contracts.is_empty());
        let until = month_abs(&w) + GRIEVANCE_MONTHS;
        assert_eq!(w.resources.grievances, vec![Grievance { victim: australia, breaker: japan, until }]);

        w.nation_mut(japan).political_capital = 100.0;
        let ask = |w: &mut WorldState| propose(w, japan, australia, vec![money(0.0)], vec![com(Commodity::Bauxite, 8_000.0)], 60);
        for month in 0..GRIEVANCE_MONTHS {
            assert_eq!(ask(&mut w), Err(Reason::BrokeContract.sentence()), "month {month}");
            assert_eq!(w.nation(japan).political_capital, 100.0);
            tick_month(&mut w, &[]);
            w.nation_mut(japan).political_capital = 100.0;
        }
        assert_eq!(month_abs(&w), until);
        // Only the memory is being asked about: the seat is re-warmed so a
        // relation that drifted over three years is not what answers.
        seat(&mut w, japan, australia);
        let e = ask(&mut w).unwrap_err();
        assert!(e.starts_with("We would want $"), "month 37 answered {e:?}");
        assert_eq!(w.resources.grievances.len(), 1, "the row lives until the month's tick");
        tick_month(&mut w, &[]);
        assert!(w.resources.grievances.is_empty());
    }

    /// Acceptance item 8. Japan buys bauxite from Australia for ten years;
    /// after sixty months of full cover its dependency on Australia is
    /// positive with no pact between them — exactly the contract's depth,
    /// because Japan mines none of its own — and the seller's on the buyer
    /// is nothing. commitment.rs and theatre.rs read `trade_dependency` by
    /// that one name at their pressed-access and consent sites, so the
    /// leverage is theirs for free; the source is pinned to say so.
    #[test]
    fn a_contract_is_leverage() {
        let (japan, australia) = (code("Japan"), code("Australia"));
        let mut w = world_1990(GameRules::default());
        w.rules.ai_aggression = 0.0;
        seat(&mut w, japan, australia);
        buy(&mut w, japan, australia, Commodity::Bauxite, 8_000.0, 120);
        assert_eq!(w.trade_dependency(japan, australia), 0.0, "no cover yet");
        for _ in 0..60 {
            tick_month(&mut w, &[]);
            w.statecraft.trade.retain(|t| t.a != japan && t.b != japan);
        }
        assert_eq!(w.trade_depth(japan, australia), 0.0, "a pact crept in");
        let k = &w.resources.contracts[0];
        assert_eq!(k.months_left, 60);
        assert!(near(k.depth, 0.72, 1e-9), "{}", k.depth);
        let dep = w.trade_dependency(japan, australia);
        assert!(dep > 0.0);
        assert_eq!(dep, contract_dependency(&w, japan, australia));
        assert_eq!(flow(&w, japan, Commodity::Bauxite), 0.0);
        assert!(near(dep, k.depth, 1e-12), "{dep} vs depth {}", k.depth);
        assert_eq!(w.trade_dependency(australia, japan), 0.0);
        assert!(include_str!("commitment.rs").contains("w.trade_dependency(host, seeker)"));
        assert!(include_str!("theatre.rs").contains("w.trade_dependency(host, seeker)"));
    }

    /// Acceptance item 8; the brief's "land transfer conserves district
    /// ownership". Through the one transfer function: Kuwait cedes Al Ahmadi
    /// to Iraq — Iraq's gas rises by the district's located share of Kuwait's
    /// figure, Kuwait's oil falls by the located fraction of its ledger, the
    /// people move by the district's share of Kuwait's people, output by
    /// three-quarters of that, Kuwait's stability by a point per percent,
    /// Iraq's separatism by the share; the map keeps every district and
    /// changes exactly one hand. Through the command: the United States
    /// sells Alaska to Canada by consent — the land premium is charged, the
    /// district's copper, gold, iron and the rest follow it, and no oil moves
    /// because the American ledger locates none.
    #[test]
    fn a_district_sold_by_consent_moves_its_share() {
        let (kuwait, iraq, usa, canada) = (code("Kuwait"), code("Iraq"), code("USA"), code("Canada"));
        let t = tables();
        let share_of = |c: &str, n: NationId, d: &str| t.located[c][&n].iter().find(|(x, _)| x == d).map_or(0.0, |(_, s)| *s);

        let mut w = built(world_1990(GameRules::default()));
        let (gas_share, oil_share) = (share_of("gas", kuwait, "KW-AH"), share_of("oil", kuwait, "KW-AH"));
        assert!(gas_share > 0.3 && oil_share > 0.3);
        let pop = pop_share_of(&w, kuwait, "KW-AH");
        assert!(near(pop, 0.0834, 1e-3), "{pop}");
        assert!(near(located_oil_fraction(&w, kuwait, "KW-AH"), oil_share, 1e-12));
        let (gas_iraq, gas_kuwait) = (flow(&w, iraq, Commodity::Gas), flow(&w, kuwait, Commodity::Gas));
        let (kp, kg, ko, ks) = {
            let n = w.nation(kuwait);
            (n.population, n.gdp, n.oil_mbd, n.stability)
        };
        let (ip, ig, io, isep) = {
            let n = w.nation(iraq);
            (n.population, n.gdp, n.oil_mbd, n.separatism)
        };
        let (count, held_kw, held_iq) = (w.districts.len(), holdings(&w, kuwait), holdings(&w, iraq));
        let epoch = w.districts_epoch;
        crate::districts::transfer_district(&mut w, kuwait, iraq, "KW-AH").unwrap();
        assert_eq!(w.districts_epoch, epoch.wrapping_add(1));
        assert_eq!(w.districts.len(), count);
        assert_eq!((holdings(&w, kuwait), holdings(&w, iraq)), (held_kw - 1, held_iq + 1));
        assert_eq!(w.districts.get("KW-AH"), Some(&iraq));
        tick(&mut w);
        assert!(near(flow(&w, iraq, Commodity::Gas) - gas_iraq, gas_share * gas_kuwait, 1e-9));
        assert!(near(flow(&w, kuwait, Commodity::Gas), gas_kuwait * (1.0 - gas_share), 1e-9));
        let (k, i) = (w.nation(kuwait), w.nation(iraq));
        assert!(near(k.oil_mbd, ko * (1.0 - oil_share), 1e-12) && near(i.oil_mbd, io + ko * oil_share, 1e-12));
        assert!(near(k.population, kp * (1.0 - pop), 1e-12) && near(i.population, ip + kp * pop, 1e-12));
        assert!(near(k.gdp, kg * (1.0 - 0.75 * pop), 1e-9) && near(i.gdp, ig + kg * 0.75 * pop, 1e-9));
        assert_eq!(k.stability, (ks - 100.0 * pop).max(5.0));
        assert_eq!(i.separatism, (isep + pop).min(1.0));
        assert!(near(flow(&w, iraq, Commodity::Oil), i.oil_mbd * 1000.0, 1e-9), "oil is the ledger");
        // Wrong owner: refused, nothing moves.
        let snap = crate::save(&w);
        assert_eq!(crate::districts::transfer_district(&mut w, kuwait, iraq, "KW-AH"), Err("Kuwait does not hold KW-AH.".into()));
        assert_eq!(crate::save(&w), snap);

        // By consent, through the command.
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, usa, canada);
        let pop = pop_share_of(&w, usa, "US-AK");
        assert!(pop > 0.0 && pop < NOT_FOR_SALE_POP);
        assert!(t.unlocated[usa.index()][OIL]);
        assert_eq!(located_oil_fraction(&w, usa, "US-AK"), 0.0);
        let premium = 20.0 + 300.0 * pop;
        assert_eq!(
            crate::price_of(&w, &Command::ProposeDeal { from: usa, to: canada, give: vec![land("US-AK")], take: vec![money(0.0)], months: 12 }),
            Some(3.0 + premium)
        );
        let (oil_usa, oil_canada) = (w.nation(usa).oil_mbd, w.nation(canada).oil_mbd);
        let gold_canada = flow(&w, canada, Commodity::Gold);
        let gold_share = share_of("gold", usa, "US-AK");
        let gold_usa = t.production[usa.index()][Commodity::Gold.idx()];
        let count = w.districts.len();
        propose(&mut w, usa, canada, vec![land("US-AK")], vec![money(0.0)], 12).unwrap();
        assert!(near(w.nation(usa).political_capital, 100.0 - 3.0 - premium, 1e-9));
        assert_eq!(w.districts.get("US-AK"), Some(&canada));
        assert_eq!(w.districts.len(), count);
        assert_eq!((w.nation(usa).oil_mbd, w.nation(canada).oil_mbd), (oil_usa, oil_canada), "an unlocated producer's ground moves no oil");
        assert_eq!(w.resources.contracts.len(), 1);
        assert_eq!(w.resources.contracts[0].give, vec![land("US-AK")]);
        assert_eq!(
            w.headlines.last().map(String::as_str),
            Some("United States and Canada sign a supply contract: United States sends Canada the district of Alaska for $0.0bn a year, 12 months.")
        );
        tick(&mut w);
        assert!(near(flow(&w, canada, Commodity::Gold) - gold_canada, gold_share * gold_usa, 1e-9));
    }

    /// Acceptance item 8. A party dies: the contract is gone the next tick,
    /// the headline says so, and no successor holds it.
    #[test]
    fn the_dead_take_their_contracts_with_them() {
        let (japan, ussr) = (code("Japan"), code("USSR"));
        let mut w = built(world_1990(GameRules::default()));
        seat(&mut w, japan, ussr);
        buy(&mut w, japan, ussr, Commodity::Iron, 10_000.0, 60);
        assert_eq!(w.resources.contracts.len(), 1);
        w.nation_mut(ussr).alive = false;
        let heads = tick_month(&mut w, &[]);
        assert!(
            heads.iter().any(|h| h == "The iron contract between Japan and Soviet Union dies with Soviet Union."),
            "{heads:?}"
        );
        assert!(w.resources.contracts.is_empty());
        let heirs: Vec<NationId> =
            crate::districts::SUCCESSOR_PARENTS.iter().filter(|(_, p)| *p == ussr).map(|(h, _)| *h).collect();
        assert!(!heirs.is_empty());
        assert!(w.resources.contracts.iter().all(|k| !heirs.contains(&k.from) && !heirs.contains(&k.to)));
        assert_eq!(contracted_in(&w, japan, Commodity::Iron), 0.0);
    }

    /// The brief's "determinism": two worlds given the same deals — a
    /// signing, six months, a cancellation, six more, a land sale, a year —
    /// serialize to the same bytes; and a save taken mid-contract reloads to
    /// the same future, legs and all.
    #[test]
    fn two_worlds_with_the_same_deals_are_byte_identical() {
        let (japan, australia, usa, canada) = (code("Japan"), code("Australia"), code("USA"), code("Canada"));
        let script = |w: &mut WorldState| {
            seat(w, japan, australia);
            buy(w, japan, australia, Commodity::Bauxite, 8_000.0, 60);
            let id = w.resources.contracts.last().unwrap().id;
            for _ in 0..6 {
                tick_month(w, &[]);
            }
            apply_command(w, &Command::CancelDeal { nation: japan, contract: id }).unwrap();
            for _ in 0..6 {
                tick_month(w, &[]);
            }
            w.nation_mut(usa).political_capital = 100.0;
            propose(w, usa, canada, vec![land("US-AK")], vec![money(0.0)], 12).unwrap();
            for _ in 0..12 {
                tick_month(w, &[]);
            }
        };
        let (mut a, mut b) = (world_1990(GameRules::default()), world_1990(GameRules::default()));
        script(&mut a);
        script(&mut b);
        assert_eq!(crate::save(&a), crate::save(&b));
        assert_eq!(a.districts.get("US-AK"), Some(&canada));

        let mut c = world_1990(GameRules::default());
        seat(&mut c, japan, australia);
        buy(&mut c, japan, australia, Commodity::Bauxite, 8_000.0, 60);
        for _ in 0..3 {
            tick_month(&mut c, &[]);
        }
        let text = crate::save(&c);
        assert!(text.contains("\"contracts\"") && text.contains("\"per_month\""));
        let mut d = crate::load(&text).unwrap();
        assert!(!d.resource_have.built);
        assert_eq!(d.resources, c.resources);
        for _ in 0..12 {
            tick_month(&mut c, &[]);
            tick_month(&mut d, &[]);
        }
        assert_eq!(crate::save(&c), crate::save(&d));
    }

    /// Acceptance item 4's grep: the trade arms write only what the register
    /// allows. Outside its tests this module never names the RNG, growth,
    /// productivity, munitions, strength, or writes to output, oil, stability
    /// or population; its only reach into another nation's books is
    /// `debt_gdp` at delivery, the relation at signing and cancellation and
    /// the reputation at cancellation. The consent slices of people, output,
    /// oil, stability and separatism live in `districts::transfer_district`
    /// and nowhere else.
    #[test]
    fn the_trade_arms_write_only_what_the_register_allows() {
        let src = include_str!("resources.rs");
        let code = src.split("#[cfg(test)]").next().unwrap();
        let body: String = code
            .lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .map(|l| l.split("//").next().unwrap())
            .collect::<Vec<_>>()
            .join("\n");
        for forbidden in [
            ".rng",
            "growth_last",
            "tfp",
            "munitions",
            "mil_strength",
            ".gdp =",
            ".gdp +=",
            ".gdp -=",
            ".gdp *=",
            "oil_mbd =",
            "oil_mbd +=",
            "oil_mbd -=",
            "oil_mbd *=",
            "stability =",
            "stability +=",
            "stability -=",
            "population =",
            "population +=",
            "population -=",
            "separatism",
            "trade_level",
            "political_capital",
        ] {
            assert!(!body.contains(forbidden), "resources.rs touches {forbidden:?}");
        }
        assert_eq!(body.matches("shift_relation(").count(), 2, "signing and cancelling");
        assert_eq!(body.matches("shift_reputation(").count(), 1, "cancelling");
        assert!(body.contains("SIGN_RELATION") && body.contains("CANCEL_RELATION") && body.contains("CANCEL_REPUTATION"));
        assert_eq!(
            body.matches("debt_gdp").count(),
            4,
            "one mine investment plus one settle: payer up, payee down, floored"
        );
        let districts = include_str!("districts.rs");
        assert_eq!(districts.matches("pub fn transfer_district").count(), 1);
        let transfer = districts.split("pub fn transfer_district").nth(1).unwrap().split("\n}\n").next().unwrap();
        for slice in ["population", "gdp", "oil_mbd", "stability", "separatism", "districts_epoch"] {
            assert!(transfer.contains(slice), "the transfer does not slice {slice}");
        }
        assert!(!transfer.contains("shift_relation"), "the contract's +5 covers it");
    }

    // -----------------------------------------------------------------------
    // Package S3: the market and the last-resort chain. Every test here turns
    // `resource_market` on by hand; the suite's default is off, and the
    // switch's own proof stands beside the goldens in lib.rs.
    // -----------------------------------------------------------------------

    /// A cover row for `id` with `c` at zero: the stall, by hand.
    fn starve(w: &mut WorldState, id: NationId, c: Commodity) {
        match w.resources.cover.binary_search_by_key(&id, |r| r.nation) {
            Ok(i) => w.resources.cover[i].months[c.idx()] = 0.0,
            Err(i) => {
                let mut months = [BUFFER_MONTHS; 12];
                months[c.idx()] = 0.0;
                w.resources.cover.insert(i, Cover { nation: id, months });
            }
        }
    }

    /// Every living producer of `c` other than `buyer` and `except`
    /// sanctions the buyer, and the buyer sanctions nobody — a seller the
    /// buyer itself embargoes is blocked, not asked, and would keep the gate
    /// shut for a reason this test is not about. Re-applied every month a
    /// test runs, because statecraft may lift or add one.
    fn close_market(w: &mut WorldState, buyer: NationId, c: Commodity, except: &[NationId]) {
        w.sanctions.retain(|(a, _)| *a != buyer);
        for s in producers(w, c) {
            if s != buyer && !except.contains(&s) && !w.is_sanctioning(s, buyer) {
                w.sanctions.push((s, buyer));
            }
        }
    }

    /// `months` forward on the calendar, nothing else.
    fn advance_calendar(w: &mut WorldState, months: i32) {
        for _ in 0..months {
            w.month += 1;
            if w.month > 12 {
                w.month = 1;
                w.year += 1;
            }
        }
    }

    /// Acceptance item 9: ruling 4's predicate, clause by clause, on a
    /// hand-built memory. It never opens on a single ask, an un-asked
    /// seller, a seller the buyer itself embargoes, a row cooled below
    /// GATE_HEAT, a target that did not refuse, a mine no army can reach, a
    /// claim already pressed, a priced-out ask (which writes no row — see
    /// `priced_out_is_not_a_refusal`), or a line nobody produces. With
    /// every refusal in place and the pile not yet empty the appetite is
    /// the market-off value bit for bit; with the pile empty, `worth` is
    /// exactly that value plus RESOURCE_WORTH and nothing else moved.
    ///
    /// Iron rule 7: a unit predicate on one hand-built world — no seed is
    /// sampled and no die is rolled, so the variance is zero and n is one;
    /// every clause is a hard bar, and a hard bar is tested by crossing it.
    #[test]
    fn the_last_resort_predicate() {
        use crate::dyads::{gdp_worth, last_resort, settled_flag, war_appetite, RESOURCE_WORTH};
        let (iraq, iran, chile, kuwait) = (code("Iraq"), code("Iran"), code("Chile"), code("Kuwait"));
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        w.rules.resource_market = true;
        let sellers: Vec<NationId> = producers(&w, k).into_iter().filter(|s| *s != iraq).collect();
        assert!(sellers.len() >= 10 && sellers.contains(&iran) && sellers.contains(&chile), "{}", sellers.len());
        assert!(!sellers.contains(&kuwait), "Kuwait mines no copper");
        let (d_star, _) = reachable_best_district(&w, iraq, iran, k).expect("Iran holds copper in Iraq's reach");
        assert_eq!(reachable_best_district(&w, iraq, chile, k), None, "no army of Iraq's reaches Chile");
        let aim = Aim { district: d_star.clone(), commodity: k };

        // No stall, no memory: nothing. A stall alone: nothing.
        assert_eq!(last_resort(&w, iraq, iran), None);
        starve(&mut w, iraq, k);
        assert_eq!(last_resort(&w, iraq, iran), None);
        // Everyone asked once: nothing.
        for s in &sellers {
            remember_refusal(&mut w, iraq, *s, k, Reason::Embargoed);
        }
        assert_eq!(refused_all(&w, iraq, k), None);
        assert_eq!(last_resort(&w, iraq, iran), None);
        // Everyone asked twice: the gate opens, toward the mine that refused.
        for s in &sellers {
            remember_refusal(&mut w, iraq, *s, k, Reason::Embargoed);
        }
        assert_eq!(refused_all(&w, iraq, k), Some((sellers.len(), sellers.len())));
        assert_eq!(last_resort(&w, iraq, iran), Some(aim.clone()));

        // One un-asked producer closes it.
        let mut v = w.clone();
        forget_refusal(&mut v, iraq, sellers[0], k);
        assert_eq!(last_resort(&v, iraq, iran), None);
        // One producer blocked by the buyer's own sanction closes it.
        let mut v = w.clone();
        v.sanctions.push((iraq, sellers[0]));
        assert_eq!(last_resort(&v, iraq, iran), None);
        // A row cooled below GATE_HEAT on any one producer closes it.
        let mut v = w.clone();
        let i = refusal_slot(&v, iraq, sellers[0], k).unwrap();
        v.resources.refusals[i].heat = 0.49;
        assert_eq!(last_resort(&v, iraq, iran), None);
        v.resources.refusals[i].heat = GATE_HEAT;
        assert_eq!(last_resort(&v, iraq, iran), Some(aim.clone()));
        // A priced-out row on any one producer, however many asks, never counts.
        let mut v = w.clone();
        v.resources.refusals[i].reason = Reason::NotForThatPrice { bn_per_year: 1.0 };
        v.resources.refusals[i].asks = 9;
        assert_eq!(refused_all(&v, iraq, k), None);
        assert_eq!(last_resort(&v, iraq, iran), None);
        // A target that is not a refuser never opens.
        assert_eq!(last_resort(&w, iraq, kuwait), None);
        // A mine no army can reach never opens, however often it refused.
        assert!(refusal_counted(&w, iraq, chile, k));
        assert_eq!(last_resort(&w, iraq, chile), None);
        // A claim already pressed by force closes it.
        let mut v = w.clone();
        v.set_flag(&settled_flag(iraq, iran));
        assert_eq!(last_resort(&v, iraq, iran), None);
        // No producers: no target, no aim.
        let mut v = w.clone();
        for s in &sellers {
            v.nation_mut(*s).alive = false;
        }
        assert_eq!(refused_all(&v, iraq, k), None);
        assert_eq!(last_resort(&v, iraq, iran), None);

        // Every refusal in place but the pile not empty: the appetite is the
        // market-off value, bit for bit.
        let mut v = w.clone();
        v.resources.cover.clear();
        let on = war_appetite(&v, iraq, iran);
        v.rules.resource_market = false;
        let off = war_appetite(&v, iraq, iran);
        assert!(off > 1e-4, "{off}");
        assert_eq!(on.to_bits(), off.to_bits());
        // Everything in place and the pile empty: worth is exactly the
        // market-off value plus RESOURCE_WORTH.
        let on = war_appetite(&w, iraq, iran);
        let gw = gdp_worth(w.nation(iraq).gdp, w.nation(iran).gdp);
        let expect = off * (gw + RESOURCE_WORTH) / gw;
        assert!(on < 0.25 && near(on, expect, 1e-12 * expect), "on {on} off {off} expected {expect}");
    }

    /// Ruling 4's audit line: a deficit alone contributes exactly 0.0. A
    /// state with every tracked line at zero cover and no refusal on file
    /// has, for every contact, the appetite it has with the market off — bit
    /// for bit. Iron rule 7: unit, no seed, variance 0, n = 1.
    #[test]
    fn a_deficit_alone_never_raises_appetite() {
        use crate::dyads::{contacts, war_appetite};
        let iraq = code("Iraq");
        let mut w = built(world_1990(GameRules::default()));
        w.rules.resource_market = true;
        for c in ALL.iter().copied().filter(|c| c.tracked()) {
            starve(&mut w, iraq, c);
        }
        assert!(w.resources.refusals.is_empty());
        let mut off = w.clone();
        off.rules.resource_market = false;
        let mut live = 0;
        for t in contacts(iraq) {
            let a = war_appetite(&w, iraq, *t);
            let b = war_appetite(&off, iraq, *t);
            assert_eq!(a.to_bits(), b.to_bits(), "{}", t.name());
            if a > 0.0 {
                live += 1;
            }
        }
        assert!(live > 0, "Iraq has appetites in 1990; the comparison must not be vacuous");
    }

    /// PricedOut is not a refusal (spec section 6.2): a seller whose price is
    /// past what the buyer may spend leaves no row — shown on the card at
    /// request time, never remembered. France's copper market is closed by
    /// every producer but Chile, France's contract cap is already spent, and
    /// one buy pass writes a row for every embargo and none for Chile; the
    /// universal refusal therefore never holds. Iron rule 7: unit, one
    /// hand-built world, variance 0, n = 1.
    #[test]
    fn priced_out_is_not_a_refusal() {
        let (france, chile, usa) = (code("France"), code("Chile"), code("USA"));
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        w.rules.resource_market = true;
        close_market(&mut w, france, k, &[chile]);
        w.set_relation(france, chile, 60.0);
        w.nation_mut(france).political_capital = 100.0;
        // The cap, already spent: a standing contract paying the whole 1% away.
        let gdp = w.nation(france).gdp;
        w.resources.next_id += 1;
        w.resources.contracts.push(Contract {
            id: w.resources.next_id,
            from: france,
            to: usa,
            give: vec![money(MAX_CONTRACT_SPEND * gdp)],
            take: vec![],
            months_left: 120,
            months_total: 120,
            since: 0,
            depth: 0.0,
        });
        assert!(cap(&w, france) <= 1e-9, "{}", cap(&w, france));
        // France is short: the ration leaves a gap the one open door cannot fill.
        let need = draw(&w, france)[k.idx()];
        let s = supply(&w, france, k, need);
        assert_eq!(s.holder, Some(chile));
        assert!(s.market > 0.0 && s.available < need, "{s:?} need {need}");
        let short = need - s.available;
        let capped = cap(&w, france) + DOLLAR < PRICE_STEP;
        assert!(capped);
        assert!(matches!(ask(&mut w, france, chile, k, short, capped, &mut BTreeMap::new()), Asked::PricedOut { .. }));
        assert_eq!(refusal_of(&w, france, chile, k), None, "an ask answers; the pass remembers");
        // The whole pass: a refusal per embargo, none for Chile, nothing
        // signed, no headline naming Chile — and for Chile a clock, not a
        // refusal: never counted, never in the card's count.
        write_cover(&mut w, france, k, s.available, need);
        ai_purchases(&mut w);
        let row = refusal_of(&w, france, chile, k).expect("remembered, so it is not asked again every month");
        assert!(!row.is_refusal() && matches!(row.reason, Reason::NotForThatPrice { .. }), "{row:?}");
        assert!(!refusal_counted(&w, france, chile, k));
        let rows: Vec<&Refusal> =
            w.resources.refusals.iter().filter(|r| r.buyer == france && r.c == k && r.is_refusal()).collect();
        let embargoes: Vec<NationId> = producers(&w, k).into_iter().filter(|s| *s != france && *s != chile).collect();
        assert_eq!(rows.len(), embargoes.len());
        assert!(rows.iter().all(|r| r.reason == Reason::Embargoed && r.asks == 1 && r.heat == 1.0 && r.seller != chile));
        assert_eq!(refusals_of(&w, france, k), embargoes.len());
        assert!(!w.headlines.iter().any(|h| h.contains("from Chile")), "{:?}", w.headlines);
        assert_eq!(w.resources.contracts.len(), 1, "nothing was signed");
        // However often it is asked, a priced-out seller never completes the universal refusal.
        let i = refusal_slot(&w, france, chile, k).unwrap();
        w.resources.refusals[i].asks = 5;
        w.resources.refusals[i].heat = 1.0;
        for s in &embargoes {
            remember_refusal(&mut w, france, *s, k, Reason::Embargoed);
        }
        assert!(embargoes.iter().all(|s| refusal_counted(&w, france, *s, k)));
        assert!(!refusal_counted(&w, france, chile, k));
        assert_eq!(refused_all(&w, france, k), None, "an open seller, priced out, is not a refusal");
    }

    /// Rulings 3 and 4 in a running world, France's copper market closed by
    /// every producer, the market on. The month France first falls short —
    /// long before the pile is empty — the buy pass asks every seller and
    /// every seller refuses (asks = 1, each headlined once); nothing is
    /// asked again until PATIENCE months later (asks = 2), when the
    /// universal refusal is headlined exactly once and never again while the
    /// memory stays warm; the last-resort gate stays shut for every contact
    /// until the month the pile is empty and the line actually stalls —
    /// never before BUFFER_MONTHS — and opens then only toward a refuser
    /// with a mine in reach.
    ///
    /// Iron rule 7: one seed, one timeline; the timings asserted are
    /// arithmetic on constants (PATIENCE, BUFFER_MONTHS), not samples —
    /// variance 0, n = 1. The roster is asserted unchanged for every month
    /// the counts are read, so a dissolution cannot quietly move them.
    #[test]
    fn a_starved_ai_asks_before_it_wants_and_the_universal_refusal_is_headlined_once() {
        use crate::dyads::{contacts, last_resort};
        let france = code("France");
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        w.rules.resource_market = true;
        let roster = alive_stamp(&w);
        let sellers: Vec<NationId> = producers(&w, k).into_iter().filter(|s| *s != france).collect();
        let patience = PATIENCE as usize;
        let mut stall_month = None;
        let mut first_open = None;
        let mut nobody: Vec<(usize, String)> = vec![];
        for m in 1..=30 {
            close_market(&mut w, france, k, &[]);
            let heads = crate::tick_month(&mut w, &[]);
            assert_eq!(alive_stamp(&w), roster, "month {m}: the roster moved under the test");
            let seeks = heads
                .iter()
                .filter(|h| h.starts_with("France seeks copper from ") && h.ends_with("refuses: Sanctions bar it."))
                .count();
            let rows: Vec<&Refusal> = w.resources.refusals.iter().filter(|r| r.buyer == france && r.c == k).collect();
            assert_eq!(rows.len(), sellers.len(), "month {m}");
            let expect_asks = 1 + (m as u32 - 1) / patience as u32;
            assert!(rows.iter().all(|r| r.asks == expect_asks && r.reason == Reason::Embargoed), "month {m}: {rows:?}");
            assert_eq!(seeks, if m == 1 { sellers.len() } else { 0 }, "month {m}: only a first refusal is headlined");
            nobody.extend(heads.iter().filter(|h| h.starts_with("Nobody will sell copper to France")).map(|h| (m, h.clone())));
            assert_eq!(refused_all(&w, france, k).is_some(), m > patience, "month {m}");
            let cv = cover(&w, france, k);
            if cv <= 0.0 && stall_month.is_none() {
                stall_month = Some(m);
            }
            let open = contacts(france).iter().any(|t| last_resort(&w, france, *t).is_some());
            if stall_month.is_none() {
                assert!(!open, "month {m}: the gate opened with {cv:.2} months in hand");
            } else if open && first_open.is_none() {
                first_open = Some(m);
            }
            if stall_month.is_some_and(|s| m >= s + 1) {
                break;
            }
        }
        let stall = stall_month.expect("France's copper never ran out in 30 months");
        assert!(stall as f64 >= BUFFER_MONTHS, "a pile cannot be spent before a year: month {stall}");
        assert_eq!(nobody.len(), 1, "{nobody:?}");
        assert_eq!(nobody[0].0, patience + 1);
        assert_eq!(nobody[0].1, format!("Nobody will sell copper to France — {} asked.", sellers.len()));
        // Which contacts the gate opened toward: exactly the refusers with a mine in reach.
        let reachable: Vec<NationId> = contacts(france)
            .iter()
            .copied()
            .filter(|t| refusal_counted(&w, france, *t, k) && reachable_best_district(&w, france, *t, k).is_some())
            .collect();
        let open: Vec<NationId> = contacts(france).iter().copied().filter(|t| last_resort(&w, france, *t).is_some()).collect();
        assert_eq!(open, reachable);
        assert_eq!(first_open, if reachable.is_empty() { None } else { Some(stall) });
    }

    /// The player as seller (spec section 6.2): an AI short of a line puts
    /// an offer in the player's inbox at the AI's own counter price instead
    /// of signing; a second ask for the same line while one is pending is
    /// not made; a fourth offer is not made while three wait; an offer the
    /// player lets lapse is remembered as `Unanswered` — the AI waits for
    /// you as long as it waits for itself — and is asked again once that has
    /// cooled to REASK_HEAT; accepted, it is signed at its own terms and the
    /// refusal forgotten. Iron rule 7: unit, one hand-built world, variance
    /// 0, n = 1.
    #[test]
    fn a_lapsed_offer_is_a_refusal_the_ai_remembers() {
        let (france, chile, usa) = (code("France"), code("Chile"), code("USA"));
        let k = Commodity::Copper;
        let setup = || {
            let mut w = built(world_1990(GameRules::default()));
            w.rules.resource_market = true;
            w.player = Some(chile);
            close_market(&mut w, france, k, &[chile]);
            w.set_relation(france, chile, 60.0);
            w.nation_mut(france).political_capital = 100.0;
            let need = draw(&w, france)[k.idx()];
            let s = supply(&w, france, k, need);
            assert!(s.available < need);
            write_cover(&mut w, france, k, s.available, need);
            w
        };
        let mut w = setup();
        ai_purchases(&mut w);
        let mine = |w: &WorldState| w.resources.offers.iter().filter(|o| o.from == france && o.to == chile).count();
        assert_eq!(mine(&w), 1);
        let o = w.resources.offers[0].clone();
        assert_eq!((o.months, o.expires), (AI_TERM, month_abs(&w) + PATIENCE));
        assert!(matches!(o.take[..], [Leg::Commodity { c: Commodity::Copper, per_month }] if per_month > 0.0), "{o:?}");
        assert!(matches!(o.give[..], [Leg::Money { bn_per_year }] if bn_per_year > 0.0), "{o:?}");
        assert_eq!(refusal_of(&w, france, chile, k), None, "an offer is not a refusal");
        // Asked again: the pending offer stands alone.
        ai_purchases(&mut w);
        assert_eq!(mine(&w), 1);
        // Left to lapse: gone, and remembered.
        advance_calendar(&mut w, PATIENCE);
        tick(&mut w);
        assert!(w.resources.offers.is_empty());
        let r = refusal_of(&w, france, chile, k).expect("the lapse is remembered").clone();
        assert_eq!((r.reason.clone(), r.asks, r.heat), (Reason::Unanswered, 1, 1.0));
        assert_eq!(r.reason.sentence(), "You let our last offer lapse.");
        // Not asked again while warm; asked again at REASK_HEAT.
        ai_purchases(&mut w);
        assert!(w.resources.offers.is_empty());
        for _ in 0..PATIENCE {
            cool_refusals(&mut w);
        }
        assert_eq!(refusal_of(&w, france, chile, k).unwrap().heat.to_bits(), REASK_HEAT.to_bits());
        ai_purchases(&mut w);
        assert_eq!(mine(&w), 1);
        // Accepted: signed at its own terms, the refusal forgotten.
        let id = w.resources.offers[0].id;
        w.nation_mut(chile).political_capital = 100.0;
        crate::apply_command(&mut w, &crate::Command::AcceptDeal { nation: chile, offer: id }).unwrap();
        assert!(w.resources.offers.is_empty());
        assert_eq!(refusal_of(&w, france, chile, k), None);
        assert_eq!(w.resources.contracts.len(), 1);
        assert_eq!((w.resources.contracts[0].from, w.resources.contracts[0].to), (france, chile));
        // A full inbox: a fourth is not asked this month.
        let mut w = setup();
        for i in 0..MAX_PENDING_OFFERS as u32 {
            w.resources.next_id += 1;
            w.resources.offers.push(Offer {
                id: w.resources.next_id,
                from: usa,
                to: chile,
                give: vec![money(0.1 * (i + 1) as f64)],
                take: vec![com(Commodity::Iron, 1.0)],
                months: AI_TERM,
                expires: month_abs(&w) + PATIENCE,
            });
        }
        ai_purchases(&mut w);
        assert_eq!(w.resources.offers.len(), MAX_PENDING_OFFERS);
        assert_eq!(mine(&w), 0);
    }

    /// The instrument behind `the_resource_pass_stays_under_budget`'s
    /// annotation, kept the way `war_census` is: over thirty-five years on
    /// the default seed with the market on, the buy pass's asks by outcome
    /// — signed, offered, priced out, refused, not asked — the month they
    /// peaked, and the unit cost of a pick, a supply, an evaluation and a
    /// seller's surplus. Not an assertion.
    ///
    ///     cargo test -p spheres-sim --release --lib the_buy_pass_ask_census -- --ignored --nocapture
    #[test]
    #[ignore = "instrument; run with --ignored --nocapture"]
    fn the_buy_pass_ask_census() {
        use std::hint::black_box;
        use std::time::Instant;
        let mut w = world_1990(GameRules { resource_market: true, ..GameRules::default() });
        let mut total = [0u64; 5];
        let mut months_with_asks = 0;
        let mut max_month = (0u32, 0usize);
        for m in 0..420usize {
            meter::ASKS.with(|a| a.set([0; 5]));
            crate::tick_month(&mut w, &[]);
            let a = meter::ASKS.with(|a| a.get());
            let n: u32 = a.iter().sum();
            if n > 0 {
                months_with_asks += 1;
            }
            if n > max_month.0 {
                max_month = (n, m);
            }
            for i in 0..5 {
                total[i] += a[i] as u64;
            }
            if m % 60 == 0 {
                let buyers: Vec<String> = w.resources.cover.iter().map(|r| r.nation.code().to_string()).collect();
                println!(
                    "month {m}: sanctions {} cover rows {} refusals {} offers {} contracts {} asks {:?} buyers {:?}",
                    w.sanctions.len(),
                    w.resources.cover.len(),
                    w.resources.refusals.len(),
                    w.resources.offers.len(),
                    w.resources.contracts.len(),
                    a,
                    buyers
                );
            }
        }
        println!("asks over 420 months [signed, offered, priced out, refused, not asked] = {total:?}; months with asks {months_with_asks}; max in a month {max_month:?}");
        let t = Instant::now();
        for _ in 0..100 {
            for n in &w.nations {
                if n.alive {
                    black_box(crate::arsenal::pick(n));
                }
            }
        }
        let alive = w.nations.iter().filter(|n| n.alive).count();
        println!("pick: {:.3} us each ({alive} alive)", t.elapsed().as_secs_f64() * 1e6 / 100.0 / alive as f64);
        let t = Instant::now();
        for _ in 0..1000 {
            for n in &w.nations {
                if n.alive {
                    black_box(w.is_sanctioning(n.id, NationId::from_index(0).unwrap()));
                }
            }
        }
        println!("is_sanctioning: {:.3} us each ({} pairs)", t.elapsed().as_secs_f64() * 1e6 / 1000.0 / alive as f64, w.sanctions.len());
        let buyers: Vec<NationId> = w.resources.cover.iter().map(|r| r.nation).collect();
        for b in buyers.iter().take(3) {
            let need = draw(&w, *b);
            for c in ALL.iter().copied().filter(|c| c.tracked() && need[c.idx()] > 0.0) {
                let t = Instant::now();
                for _ in 0..1000 {
                    black_box(supply(&w, *b, c, need[c.idx()]));
                }
                let su = t.elapsed().as_secs_f64() * 1e3;
                let sellers = producers(&w, c);
                let s = *sellers.iter().find(|s| **s != *b).unwrap();
                let t = Instant::now();
                for _ in 0..1000 {
                    black_box(evaluate(&w, *b, s, &[money(0.0)], &[com(c, need[c.idx()])], AI_TERM));
                }
                let ev = t.elapsed().as_secs_f64() * 1e3;
                let t = Instant::now();
                for _ in 0..1000 {
                    black_box(surplus(&w, s, c));
                }
                let sp = t.elapsed().as_secs_f64() * 1e3;
                println!(
                    "{} {}: supply {su:.2} us, evaluate vs {} {ev:.2} us, surplus(seller) {sp:.2} us; cap {:.3} short? {}",
                    b.code(),
                    c.name(),
                    s.code(),
                    cap(&w, *b),
                    supply(&w, *b, c, need[c.idx()]).available < need[c.idx()]
                );
            }
        }
    }

    /// The memory cools on the lattice of twenty-fourths: six coolings from
    /// one land on REASK_HEAT and twelve on GATE_HEAT, bit for bit — the
    /// difference between a wait of six months and one of seven — and the
    /// twenty-fourth removes the row. Iron rule 7: exact arithmetic, n = 1.
    #[test]
    fn cooling_is_on_the_lattice() {
        let (iraq, iran) = (code("Iraq"), code("Iran"));
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        remember_refusal(&mut w, iraq, iran, k, Reason::Distrust);
        for i in 1..=(HEAT_STEPS as i32) {
            cool_refusals(&mut w);
            match refusal_of(&w, iraq, iran, k) {
                Some(r) => {
                    assert!(i < HEAT_STEPS as i32);
                    let want = (HEAT_STEPS - i as f64) / HEAT_STEPS;
                    assert_eq!(r.heat.to_bits(), want.to_bits(), "step {i}: {} vs {want}", r.heat);
                }
                None => assert_eq!(i, HEAT_STEPS as i32, "the row went at step {i}"),
            }
            if i == PATIENCE {
                assert_eq!(refusal_of(&w, iraq, iran, k).unwrap().heat.to_bits(), REASK_HEAT.to_bits());
            }
            if i == 2 * PATIENCE {
                assert_eq!(refusal_of(&w, iraq, iran, k).unwrap().heat.to_bits(), GATE_HEAT.to_bits());
                assert!(refusal_counted(&w, iraq, iran, k) == false, "one ask never counts");
            }
        }
        assert!(w.resources.refusals.is_empty());
    }

    /// The aim (spec sections 6.6 and 6.7): `SetAim` is free, refused with a
    /// sentence unless the conflict exists, the opener names it, the
    /// district exists, the opponent holds it and it carries the line; set,
    /// it rides the conflict, and a settlement the opener wins moves that
    /// district first — the held set carries it and the concession begins
    /// with it. The defender winning carries no aim. Iron rule 7: unit,
    /// variance 0, n = 1.
    #[test]
    fn the_aim_cedes_first() {
        use crate::{apply_command, Command};
        let (iraq, iran) = (code("Iraq"), code("Iran"));
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        w.nation_mut(iraq).political_capital = 100.0;
        let th = crate::war::theatre_between(&w, iraq, iran);
        apply_command(&mut w, &Command::OpenConflict { opener: iraq, target: iran, theatre: th }).unwrap();
        let id = w.conflict_between(iraq, iran).unwrap().id;
        let (d_star, _) = reachable_best_district(&w, iraq, iran, k).unwrap();
        let name = crate::districts::name_of(&d_star).unwrap();
        let absent = ALL.iter().copied().find(|c| !presence_of(&d_star).contains(c)).expect("a line the district lacks");
        let aim = |nation: NationId, conflict: u32, district: &str, commodity: Commodity| Command::SetAim {
            conflict,
            nation,
            district: district.to_string(),
            commodity,
        };
        let pc = w.nation(iraq).political_capital;
        assert_eq!(apply_command(&mut w, &aim(iraq, 999, &d_star, k)), Err("No such conflict.".into()));
        assert_eq!(
            apply_command(&mut w, &aim(iran, id, &d_star, k)),
            Err("Only Iraq, who opened the quarrel, names what it is for.".into())
        );
        assert_eq!(apply_command(&mut w, &aim(iraq, id, "Nowhere", k)), Err("No district called Nowhere.".into()));
        assert_eq!(apply_command(&mut w, &aim(iraq, id, "KW-AH", Commodity::Gas)), Err("Iran does not hold Al Ahmadi.".into()));
        assert_eq!(
            apply_command(&mut w, &aim(iraq, id, &d_star, absent)),
            Err(format!("{} holds no {}.", name, absent.name()))
        );
        assert!(w.conflict(id).unwrap().aim.is_none());
        apply_command(&mut w, &aim(iraq, id, &d_star, k)).unwrap();
        assert_eq!(w.nation(iraq).political_capital, pc, "an aim is free");
        assert_eq!(w.conflict(id).unwrap().aim, Some(Aim { district: d_star.clone(), commodity: k }));
        // The settlement's held set carries the aim when the opener wins ...
        let c = w.conflict(id).unwrap().clone();
        assert!(c.front.is_empty(), "no front yet: the held set is the aim alone");
        let held = crate::war::settlement_held(&w, &c, iraq, iran);
        assert_eq!(held.iter().collect::<Vec<_>>(), vec![&d_star]);
        // ... and not when the defender does.
        assert!(crate::war::settlement_held(&w, &c, iran, iraq).is_empty());
        // The concession, at the settlement's own share, begins with it.
        let ceded = crate::districts::cede_share_preferring(&mut w, iraq, iran, 0.12, &held);
        assert_eq!(ceded.first(), Some(&d_star), "{ceded:?}");
        assert_eq!(w.districts.get(d_star.as_str()), Some(&iraq));
    }

    /// Acceptance item 10's headline: a war opened for a line prints the
    /// district, the line and the refusals count, begins `WAR:` like every
    /// invasion so every census and the classifier count it, and an
    /// invasion without an aim reads exactly as it always did. Iron rule 7:
    /// unit, exact strings, n = 1.
    #[test]
    fn the_resource_war_headline_is_a_war() {
        use crate::{apply_command, Command};
        let (iraq, iran) = (code("Iraq"), code("Iran"));
        let k = Commodity::Copper;
        let mut w = built(world_1990(GameRules::default()));
        w.rules.resource_market = true;
        w.nation_mut(iraq).political_capital = 100.0;
        let sellers: Vec<NationId> = producers(&w, k).into_iter().filter(|s| *s != iraq).collect();
        for s in &sellers {
            remember_refusal(&mut w, iraq, *s, k, Reason::Embargoed);
            remember_refusal(&mut w, iraq, *s, k, Reason::Embargoed);
        }
        let (d_star, _) = reachable_best_district(&w, iraq, iran, k).unwrap();
        let name = crate::districts::name_of(&d_star).unwrap();
        let th = crate::war::theatre_between(&w, iraq, iran);
        apply_command(&mut w, &Command::OpenConflict { opener: iraq, target: iran, theatre: th }).unwrap();
        let id = w.conflict_between(iraq, iran).unwrap().id;
        apply_command(&mut w, &Command::SetAim { conflict: id, nation: iraq, district: d_star.clone(), commodity: k }).unwrap();
        w.headlines.clear();
        crate::war::invasion_begins(&mut w, id, iraq);
        let expected = format!(
            "WAR: Iraq invades Iran for the copper of {} — refused by {} of {} sellers.",
            name,
            sellers.len(),
            sellers.len()
        );
        let wars: Vec<&String> = w.headlines.iter().filter(|h| h.starts_with("WAR:")).collect();
        assert_eq!(wars, vec![&expected]);
        // The same memory cooled beneath the bar: the rows still warm are counted.
        let mut v = w.clone();
        for _ in 0..(HEAT_STEPS as i32 / 2 + 1) {
            cool_refusals(&mut v);
        }
        assert_eq!(refused_all(&v, iraq, k), None);
        let c = v.conflict(id).unwrap().clone();
        assert_eq!(
            resource_war_headline(&v, &c, iraq, iran).as_deref(),
            Some(expected.as_str()),
            "the rows are still warm, and still counted"
        );
        // No aim: the sentence it always was.
        let mut w = built(world_1990(GameRules::default()));
        w.nation_mut(iraq).political_capital = 100.0;
        apply_command(&mut w, &Command::OpenConflict { opener: iraq, target: iran, theatre: th }).unwrap();
        let id = w.conflict_between(iraq, iran).unwrap().id;
        w.headlines.clear();
        crate::war::invasion_begins(&mut w, id, iraq);
        assert!(w.headlines.contains(&"WAR: Iraq invades Iran!".to_string()), "{:?}", w.headlines);
    }
}
